from (values
(364314,40480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Während sie die Wäsche an die Leine ..., klaute ihr der Wind fast das weiße Hemd!'::text,'hängte'::text,'hängte'::text,'gehängt hat'::text,'Katastrophe! Während sie die Wäsche an die Leine hängte, klaute ihr der Wind fast das weiße Hemd!'::text),
(364318,40480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Поки вона ... білизну на мотузку, вітер ледь не вкрав її білу сорочку!'::text,'розвішувала'::text,'розвісила'::text,'розвісила'::text,'Катастрофа! Поки вона розвішувала білизну на мотузку, вітер ледь не вкрав її білу сорочку!'::text),
(364317,40480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Mientras ella ... la ropa en el tendedero, el viento casi le roba la camisa blanca!'::text,'estaba tendiendo'::text,'tendió'::text,'ha tendido'::text,'¡Desastre! ¡Mientras ella estaba tendiendo la ropa en el tendedero, el viento casi le roba la camisa blanca!'::text),
(364316,40480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Pendant qu''elle ... le linge sur la corde, le vent a failli lui voler sa chemise blanche !'::text,'étendait'::text,'a étendu'::text,'a étendu'::text,'Catastrophe ! Pendant qu''elle étendait le linge sur la corde, le vent a failli lui voler sa chemise blanche !'::text),
(364319,40480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O çamaşırları ipe ..., rüzgâr neredeyse beyaz gömleğini çalıyordu!'::text,'asarken'::text,'astığında'::text,'asmışken'::text,'Felaket! O çamaşırları ipe asarken, rüzgâr neredeyse beyaz gömleğini çalıyordu!'::text),
(364320,40480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Miközben ő ... a ruhát a kötélre, a szél majdnem elvitte a fehér ingét!'::text,'teregette'::text,'kiteregette'::text,'kiteregette'::text,'Katasztrófa! Miközben ő teregette a ruhát a kötélre, a szél majdnem elvitte a fehér ingét!'::text),
(364323,40481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon seit Sonnenaufgang Wäsche auf dieser Terrasse auf, und der Wind macht ständig alles kaputt!'::text,'hängt'::text,'hängt'::text,'hängt'::text,'Sie hängt schon seit Sonnenaufgang Wäsche auf dieser Terrasse auf, und der Wind macht ständig alles kaputt!'::text),
(364327,40481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... білизну на цій терасі від самого світанку, а вітер постійно все псує!'::text,'розвішує'::text,'розвішує'::text,'розвішує'::text,'Вона розвішує білизну на цій терасі від самого світанку, а вітер постійно все псує!'::text),
(364326,40481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... ropa en esta terraza desde el amanecer y el viento no deja de arruinarlo todo!'::text,'ha estado tendiendo'::text,'está tendiendo'::text,'tiende'::text,'¡Ella ha estado tendiendo ropa en esta terraza desde el amanecer y el viento no deja de arruinarlo todo!'::text),
(364325,40481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... du linge sur cette terrasse depuis l''aube, et le vent n''arrête pas de tout gâcher !'::text,'étend'::text,'étend'::text,'étend'::text,'Elle étend du linge sur cette terrasse depuis l''aube, et le vent n''arrête pas de tout gâcher !'::text),
(364328,40481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şafaktan beri bu terasta çamaşır ..., rüzgâr da sürekli her şeyi mahvediyor!'::text,'asıyor'::text,'asıyor'::text,'asar'::text,'O şafaktan beri bu terasta çamaşır asıyor, rüzgâr da sürekli her şeyi mahvediyor!'::text),
(364329,40481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő hajnal óta ... a ruhát ezen a teraszon, és a szél folyton mindent tönkretesz!'::text,'teregeti'::text,'teregeti'::text,'teregeti'::text,'Ő hajnal óta teregeti a ruhát ezen a teraszon, és a szél folyton mindent tönkretesz!'::text),
(364332,40482,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... sie die ganze Wäsche in zehn Minuten auf und lachte dann das Meer an.'::text,'hängte'::text,'hängte'::text,'hängte'::text,'Hör mal, angeblich hängte sie die ganze Wäsche in zehn Minuten auf und lachte dann das Meer an.'::text),
(364336,40482,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... всю білизну за десять хвилин, а потім засміялася до моря.'::text,'розвісила'::text,'розвішувала'::text,'розвісила'::text,'Слухай, кажуть, вона розвісила всю білизну за десять хвилин, а потім засміялася до моря.'::text),
(364335,40482,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dicen que ella ... toda la ropa en diez minutos y luego se rio del mar.'::text,'tendió'::text,'estaba tendiendo'::text,'ha tendido'::text,'Oye, dicen que ella tendió toda la ropa en diez minutos y luego se rio del mar.'::text),
(364334,40482,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... tout le linge en dix minutes, puis elle a ri face à la mer.'::text,'a étendu'::text,'étendait'::text,'a étendu'::text,'Écoute, apparemment elle a étendu tout le linge en dix minutes, puis elle a ri face à la mer.'::text),
(364337,40482,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya o bütün çamaşırları on dakikada ... ve sonra denize güldü.'::text,'astı'::text,'asıyordu'::text,'asmış'::text,'Dinle, güya o bütün çamaşırları on dakikada astı ve sonra denize güldü.'::text),
(364338,40482,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ő tíz perc alatt ... az összes ruhát, aztán kinevette a tengert.'::text,'teregette ki'::text,'teregette'::text,'teregette ki'::text,'Figyelj, állítólag ő tíz perc alatt teregette ki az összes ruhát, aztán kinevette a tengert.'::text),
(364350,40484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, als der Wind auffrischte, ... sie die ganze Wäsche schon aufgehängt, ziemlich ikonisch.'::text,'hatte'::text,'hat'::text,'hängt'::text,'Digga, als der Wind auffrischte, hatte sie die ganze Wäsche schon aufgehängt, ziemlich ikonisch.'::text),
(364354,40484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, коли вітер посилився, вона вже ... всю білизну, досить культово.'::text,'розвісила'::text,'розвісила'::text,'розвішує'::text,'Бро, коли вітер посилився, вона вже розвісила всю білизну, досить культово.'::text),
(364353,40484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, cuando se levantó el viento, ella ya ... toda la ropa, bastante icónico.'::text,'había tendido'::text,'ha tendido'::text,'tiende'::text,'Bro, cuando se levantó el viento, ella ya había tendido toda la ropa, bastante icónico.'::text),
(364352,40484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, quand le vent s''est levé, elle ... déjà tout le linge, assez iconique.'::text,'avait étendu'::text,'a étendu'::text,'étend'::text,'Frère, quand le vent s''est levé, elle avait étendu déjà tout le linge, assez iconique.'::text),
(364355,40484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, rüzgâr çıktığında o bütün çamaşırları çoktan ..., baya ikonik.'::text,'asmıştı'::text,'asmış'::text,'asıyor'::text,'Kanka, rüzgâr çıktığında o bütün çamaşırları çoktan asmıştı, baya ikonik.'::text),
(364356,40484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire feltámadt a szél, ő már ... az összes ruhát, elég ikonikus.'::text,'kiteregette'::text,'kiteregette'::text,'teregeti'::text,'Tesó, mire feltámadt a szél, ő már kiteregette az összes ruhát, elég ikonikus.'::text),
(364359,40485,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, morgen um diese Zeit ... sie wieder Wäsche auf dieser Terrasse auf, kein Witz.'::text,'hängt'::text,'hängt'::text,'hängt'::text,'Alter, morgen um diese Zeit hängt sie wieder Wäsche auf dieser Terrasse auf, kein Witz.'::text),
(364363,40485,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, завтра в цей час вона знову ... білизну на тій терасі, без жартів.'::text,'розвішуватиме'::text,'розвісить'::text,'розвішує'::text,'Чувак, завтра в цей час вона знову розвішуватиме білизну на тій терасі, без жартів.'::text),
(364362,40485,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mañana a esta hora ella ... ropa otra vez en esa terraza, en serio.'::text,'estará tendiendo'::text,'tenderá'::text,'tiende'::text,'Tío, mañana a esta hora ella estará tendiendo ropa otra vez en esa terraza, en serio.'::text),
(364361,40485,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, demain à cette heure-ci, elle ... encore du linge sur cette terrasse, sans mentir.'::text,'sera en train d''étendre'::text,'étendra'::text,'étend'::text,'Mec, demain à cette heure-ci, elle sera en train d''étendre encore du linge sur cette terrasse, sans mentir.'::text),
(364364,40485,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte o yine o terasta çamaşır ..., cidden.'::text,'asıyor olacak'::text,'asacak'::text,'asıyor'::text,'Kanka, yarın bu saatte o yine o terasta çamaşır asıyor olacak, cidden.'::text),
(364365,40485,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, holnap ilyenkor ő megint ... a ruhát azon a teraszon, komolyan.'::text,'teregetni fogja'::text,'ki fogja teregetni'::text,'teregeti'::text,'Haver, holnap ilyenkor ő megint teregetni fogja a ruhát azon a teraszon, komolyan.'::text),
(364368,40486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie verspricht ihrer Nachbarin, dass sie die Wäsche vor dem Regen ...'::text,'reinholen wird'::text,'reinholen wird'::text,'gerade reinholt'::text,'Sie verspricht ihrer Nachbarin, dass sie die Wäsche vor dem Regen reinholen wird.'::text),
(364372,40486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона обіцяє сусідці, що ... білизну в дім до дощу.'::text,'занесе'::text,'заноситиме'::text,'заносить'::text,'Вона обіцяє сусідці, що занесе білизну в дім до дощу.'::text),
(364371,40486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le promete a su vecina que ... la ropa antes de la lluvia.'::text,'recogerá'::text,'estará recogiendo'::text,'está recogiendo'::text,'Le promete a su vecina que recogerá la ropa antes de la lluvia.'::text),
(364370,40486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle promet à sa voisine qu''elle ... le linge avant la pluie.'::text,'rentrera'::text,'sera en train de rentrer'::text,'rentre'::text,'Elle promet à sa voisine qu''elle rentrera le linge avant la pluie.'::text),
(364373,40486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Komşusuna yağmurdan önce çamaşırları içeri ... söz veriyor.'::text,'getireceğine'::text,'getiriyor olacağına'::text,'getirdiğine'::text,'Komşusuna yağmurdan önce çamaşırları içeri getireceğine söz veriyor.'::text),
(364374,40486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri a szomszédjának, hogy eső előtt ... a ruhát.'::text,'beviszi'::text,'be fogja vinni'::text,'éppen viszi be'::text,'Megígéri a szomszédjának, hogy eső előtt beviszi a ruhát.'::text),
(364377,40487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie jung war, ... sie die Wäsche jeden Tag von Hand aufzuhängen.'::text,'pflegte'::text,'pflegte'::text,'war gewohnt'::text,'Als sie jung war, pflegte sie die Wäsche jeden Tag von Hand aufzuhängen.'::text),
(364381,40487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона була молодою, вона ... розвішувати білизну вручну кожного дня.'::text,'мала звичку'::text,'мала звичку'::text,'звикла'::text,'Коли вона була молодою, вона мала звичку розвішувати білизну вручну кожного дня.'::text),
(364380,40487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando era joven, ... tender la ropa a mano todos los días.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Cuando era joven, solía tender la ropa a mano todos los días.'::text),
(364379,40487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle était jeune, elle ... suspendre le linge à la main chaque jour.'::text,'avait l''habitude de'::text,'avait l''habitude de'::text,'était habituée à'::text,'Quand elle était jeune, elle avait l''habitude de suspendre le linge à la main chaque jour.'::text),
(364382,40487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gençken o çamaşırları her gün elle ...'::text,'asardı'::text,'asardı'::text,'asmaya alışkındı'::text,'Gençken o çamaşırları her gün elle asardı.'::text),
(364383,40487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fiatalon minden egyes nap kézzel ... a ruhát.'::text,'teregette ki'::text,'teregette ki'::text,'szokta kiteregetni'::text,'Fiatalon minden egyes nap kézzel teregette ki a ruhát.'::text),
(364386,40488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie genießt das ... der Wäsche draußen im Wind vom Meer.'::text,'Aufhängen'::text,'Aufhängen'::text,'Aufhängen'::text,'Sie genießt das Aufhängen der Wäsche draußen im Wind vom Meer.'::text),
(364390,40488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй подобається ... білизну надворі на вітрі з моря.'::text,'розвішувати'::text,'розвішувати'::text,'розвішувати'::text,'Їй подобається розвішувати білизну надворі на вітрі з моря.'::text),
(364389,40488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Disfruta ... la ropa fuera, con el viento del mar.'::text,'tendiendo'::text,'tender'::text,'tender'::text,'Disfruta tendiendo la ropa fuera, con el viento del mar.'::text),
(364388,40488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle adore ... le linge dehors, dans le vent qui vient de la mer.'::text,'étendre'::text,'étendre'::text,'étendre'::text,'Elle adore étendre le linge dehors, dans le vent qui vient de la mer.'::text),
(364391,40488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deniz rüzgârında çamaşırları dışarıda ... seviyor.'::text,'asmayı'::text,'asmayı'::text,'asmayı'::text,'Deniz rüzgârında çamaşırları dışarıda asmayı seviyor.'::text),
(364392,40488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Élvezi, hogy kint ... a ruhát a tenger felől fújó szélben.'::text,'teregeti'::text,'teregeti'::text,'teregeti'::text,'Élvezi, hogy kint teregeti a ruhát a tenger felől fújó szélben.'::text),
(364395,40489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wind ... ihre saubere Wäsche gerade herum, ein leicht chaotischer Morgen.'::text,'wirbelt'::text,'wirbelt'::text,'wirbelte'::text,'Der Wind wirbelt ihre saubere Wäsche gerade herum, ein leicht chaotischer Morgen.'::text),
(364399,40489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вітер саме зараз ... її чисту білизну, трохи хаотичний ранок.'::text,'розкидає'::text,'розкидає'::text,'розкидав'::text,'Вітер саме зараз розкидає її чисту білизну, трохи хаотичний ранок.'::text),
(364398,40489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El viento ... su ropa limpia de un lado a otro ahora mismo, una mañana ligeramente caótica.'::text,'está agitando'::text,'agita'::text,'ha agitado'::text,'El viento está agitando su ropa limpia de un lado a otro ahora mismo, una mañana ligeramente caótica.'::text),
(364397,40489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vent ... son linge propre dans tous les sens en ce moment, une matinée légèrement chaotique.'::text,'fait voler'::text,'fait voler'::text,'a fait voler'::text,'Le vent fait voler son linge propre dans tous les sens en ce moment, une matinée légèrement chaotique.'::text),
(364400,40489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgâr şu an onun temiz çamaşırlarını ..., hafif kaotik bir sabah.'::text,'savuruyor'::text,'savurur'::text,'savurdu'::text,'Rüzgâr şu an onun temiz çamaşırlarını savuruyor, hafif kaotik bir sabah.'::text),
(364401,40489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szél épp most ... a tiszta ruháit, enyhén kaotikus reggel.'::text,'fújja szét'::text,'fújja szét'::text,'fújta szét'::text,'A szél épp most fújja szét a tiszta ruháit, enyhén kaotikus reggel.'::text),
(349671,38853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um 9 Uhr ... das Team für das Kundenvideo die Ellbogen aneinander.'::text,'stößt'::text,'stößt'::text,'stößt'::text,'Morgen um 9 Uhr stößt das Team für das Kundenvideo die Ellbogen aneinander.'::text),
(349675,38853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о 9:00 команда ... ліктями для відео клієнта.'::text,'стукатиметься'::text,'стукнеться'::text,'стукається'::text,'Завтра о 9:00 команда стукатиметься ліктями для відео клієнта.'::text),
(349674,38853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las 9:00, el equipo ... los codos para el vídeo del cliente.'::text,'estará chocando'::text,'chocará'::text,'choca'::text,'Mañana a las 9:00, el equipo estará chocando los codos para el vídeo del cliente.'::text),
(349673,38853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à 9 h, l''équipe ... les coudes pour la vidéo du client.'::text,'sera en train d''entrechoquer'::text,'entrechoquera'::text,'entrechoque'::text,'Demain à 9 h, l''équipe sera en train d''entrechoquer les coudes pour la vidéo du client.'::text),
(349676,38853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın sabah 9''da ekip müşteri videosu için dirsek ...'::text,'tokuşturuyor olacak'::text,'tokuşturacak'::text,'tokuşturuyor'::text,'Yarın sabah 9''da ekip müşteri videosu için dirsek tokuşturuyor olacak.'::text),
(349677,38853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap reggel 9-kor a csapat ... a könyökét az ügyfélvideóhoz.'::text,'fogja összeütögetni'::text,'össze fogja ütni'::text,'összeüti'::text,'Holnap reggel 9-kor a csapat fogja összeütögetni a könyökét az ügyfélvideóhoz.'::text),
(349680,38854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... morgen auch die Ellbogen aneinander, glaube ich, weil morgen nach heute kommt.'::text,'stoßen'::text,'stoßen'::text,'stoßen'::text,'Sie stoßen morgen auch die Ellbogen aneinander, glaube ich, weil morgen nach heute kommt.'::text),
(349684,38854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... ліктями й завтра, я думаю, бо завтра настає після сьогодні.'::text,'стукнуться'::text,'стукатимуться'::text,'стукаються'::text,'Вони стукнуться ліктями й завтра, я думаю, бо завтра настає після сьогодні.'::text),
(349683,38854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana también ... los codos, creo, porque mañana viene después de hoy.'::text,'chocarán'::text,'estarán chocando'::text,'están chocando'::text,'Mañana también chocarán los codos, creo, porque mañana viene después de hoy.'::text),
(349682,38854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... les coudes demain aussi, je pense, parce que demain vient après aujourd''hui.'::text,'entrechoqueront'::text,'seront en train d''entrechoquer'::text,'entrechoquent'::text,'Ils entrechoqueront les coudes demain aussi, je pense, parce que demain vient après aujourd''hui.'::text),
(349685,38854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence yarın da dirsek ..., çünkü yarın bugünden sonra gelir.'::text,'tokuşturacaklar'::text,'tokuşturuyor olacaklar'::text,'tokuşturuyorlar'::text,'Bence yarın da dirsek tokuşturacaklar, çünkü yarın bugünden sonra gelir.'::text),
(349686,38854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem holnap is ... a könyöküket, mert a holnap a ma után jön.'::text,'összeütik'::text,'össze fogják ütögetni'::text,'ütögetik össze'::text,'Szerintem holnap is összeütik a könyöküket, mert a holnap a ma után jön.'::text),
(349689,38855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn zwei Leute die Ellbogen aneinanderstoßen, ... sie sich nicht an den Händen.'::text,'berühren'::text,'berühren'::text,'berührten'::text,'Wenn zwei Leute die Ellbogen aneinanderstoßen, berühren sie sich nicht an den Händen.'::text),
(349693,38855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли двоє людей стукаються ліктями, вони ... рук одне одного.'::text,'не торкаються'::text,'не торкнуться'::text,'не торкалися'::text,'Коли двоє людей стукаються ліктями, вони не торкаються рук одне одного.'::text),
(349692,38855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si dos personas chocan los codos, ... las manos.'::text,'no se tocan'::text,'no se tocarán'::text,'no se tocaron'::text,'Si dos personas chocan los codos, no se tocan las manos.'::text),
(349691,38855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si deux personnes se font un check du coude, elles ... pas les mains.'::text,'ne se touchent'::text,'ne se toucheront'::text,'ne se touchaient'::text,'Si deux personnes se font un check du coude, elles ne se touchent pas les mains.'::text),
(349694,38855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki kişi dirsek tokuşturursa, birbirlerinin ellerine ...'::text,'dokunmazlar'::text,'dokunmayacaklar'::text,'dokunmadılar'::text,'İki kişi dirsek tokuşturursa, birbirlerinin ellerine dokunmazlar.'::text),
(349695,38855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha két ember összeüti a könyökét, ... egymás kezéhez.'::text,'nem érnek'::text,'nem fognak érni'::text,'nem értek'::text,'Ha két ember összeüti a könyökét, nem érnek egymás kezéhez.'::text),
(349698,38856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der neue Kollege kommt, ... das Team auch mit ihm die Ellbogen zusammen.'::text,'stößt'::text,'stieße'::text,'stieß'::text,'Wenn der neue Kollege kommt, stößt das Team auch mit ihm die Ellbogen zusammen.'::text),
(349702,38856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо прийде новий колега, команда ... ліктями і з ним.'::text,'стукнеться'::text,'стукнулася б'::text,'стукнулася'::text,'Якщо прийде новий колега, команда стукнеться ліктями і з ним.'::text),
(349701,38856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si llega el nuevo compañero, el equipo ... los codos también con él.'::text,'chocará'::text,'chocaría'::text,'chocó'::text,'Si llega el nuevo compañero, el equipo chocará los codos también con él.'::text),
(349700,38856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le nouveau collègue arrive, l''équipe ... un check du coude avec lui aussi.'::text,'fera'::text,'ferait'::text,'a fait'::text,'Si le nouveau collègue arrive, l''équipe fera un check du coude avec lui aussi.'::text),
(349703,38856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni iş arkadaşı gelirse, ekip onunla da dirsek ...'::text,'tokuşturacak'::text,'tokuştururdu'::text,'tokuşturdu'::text,'Yeni iş arkadaşı gelirse, ekip onunla da dirsek tokuşturacak.'::text),
(349704,38856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megérkezik az új kolléga, a csapat vele is ... a könyökét.'::text,'összeüti'::text,'összeütné'::text,'összeütötte'::text,'Ha megérkezik az új kolléga, a csapat vele is összeüti a könyökét.'::text),
(349707,38857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie sich die Hand geben würden, statt die Ellbogen aneinanderzustoßen, ... die Begrüßung förmlicher.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn sie sich die Hand geben würden, statt die Ellbogen aneinanderzustoßen, wäre die Begrüßung förmlicher.'::text),
(349711,38857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони тиснули руки замість стукатися ліктями, привітання ... офіційнішим.'::text,'було б'::text,'буде'::text,NULL::text,'Якби вони тиснули руки замість стукатися ліктями, привітання було б офіційнішим.'::text),
(349710,38857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se dieran la mano en vez de chocar los codos, el saludo ... más formal.'::text,'sería'::text,'será'::text,'es'::text,'Si se dieran la mano en vez de chocar los codos, el saludo sería más formal.'::text),
(349709,38857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils se serraient la main au lieu de se faire un check du coude, la salutation ... plus formelle.'::text,'serait'::text,'sera'::text,'est'::text,'S''ils se serraient la main au lieu de se faire un check du coude, la salutation serait plus formelle.'::text),
(349712,38857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dirsek tokuşturmak yerine el sıkışsalardı, selamlaşma daha resmi ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Dirsek tokuşturmak yerine el sıkışsalardı, selamlaşma daha resmi olurdu.'::text),
(349713,38857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha könyökütés helyett kezet fognának, a köszönés formálisabb ...'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha könyökütés helyett kezet fognának, a köszönés formálisabb lenne.'::text),
(349725,38859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, dass der Ellbogengruß von der Frau am Fenster ...'::text,'gestartet wurde'::text,'gestartet hat'::text,'Starten'::text,'Bestie, ich hab gehört, dass der Ellbogengruß von der Frau am Fenster gestartet wurde.'::text),
(349729,38859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що стукання ліктями ... жінкою біля вікна.'::text,'було започатковане'::text,'започаткувало'::text,'започаткування'::text,'Подруго, я чула, що стукання ліктями було започатковане жінкою біля вікна.'::text),
(349728,38859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me han dicho que el choque de codos ... por la mujer de la ventana.'::text,'fue iniciado'::text,'inició'::text,'iniciando'::text,'Amiga, me han dicho que el choque de codos fue iniciado por la mujer de la ventana.'::text),
(349727,38859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que le check du coude ... par la femme près de la fenêtre.'::text,'a été lancé'::text,'a lancé'::text,'lançant'::text,'Ma belle, il paraît que le check du coude a été lancé par la femme près de la fenêtre.'::text),
(349730,38859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre dirsek selamı pencerenin yanındaki kadın tarafından ...'::text,'başlatılmış'::text,'başlatmış'::text,'başlatan'::text,'Kanka, duyduğuma göre dirsek selamı pencerenin yanındaki kadın tarafından başlatılmış.'::text),
(349731,38859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy a könyökpacsit az ablak melletti nő ...'::text,'indította el'::text,'indította el'::text,'elindítva'::text,'Csajszi, azt hallottam, hogy a könyökpacsit az ablak melletti nő indította el.'::text),
(349734,38860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwer ... den Ellbogen-Trend gestartet haben; jetzt macht es das ganze Büro. Perfekte Planung.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Irgendwer muss den Ellbogen-Trend gestartet haben; jetzt macht es das ganze Büro. Perfekte Planung.'::text),
(349738,38860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хтось ... започаткувати цей тренд із ліктями; тепер так робить увесь офіс. Бездоганне планування.'::text,'мусив'::text,'міг'::text,'не міг'::text,'Хтось мусив започаткувати цей тренд із ліктями; тепер так робить увесь офіс. Бездоганне планування.'::text),
(349737,38860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alguien ... haber empezado la moda de los codos; ahora lo hace toda la oficina. Planificación impecable.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Alguien debe de haber empezado la moda de los codos; ahora lo hace toda la oficina. Planificación impecable.'::text),
(349736,38860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelqu''un ... lancé la tendance du coude ; maintenant tout le bureau le fait. Planification impeccable.'::text,'a dû'::text,'a peut-être'::text,'n''a pas pu'::text,'Quelqu''un a dû lancé la tendance du coude ; maintenant tout le bureau le fait. Planification impeccable.'::text),
(349739,38860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birisi dirsek trendini ...; şimdi bütün ofis bunu yapıyor. Kusursuz planlama.'::text,'başlatmış olmalı'::text,'başlatmış olabilir'::text,'başlatmış olamaz'::text,'Birisi dirsek trendini başlatmış olmalı; şimdi bütün ofis bunu yapıyor. Kusursuz planlama.'::text),
(349740,38860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valaki ... elindította a könyöktrendet; most az egész iroda ezt csinálja. Hibátlan tervezés.'::text,'biztosan'::text,'talán'::text,'aligha'::text,'Valaki biztosan elindította a könyöktrendet; most az egész iroda ezt csinálja. Hibátlan tervezés.'::text),
(349743,38861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... Ellbogen sie zuerst angestoßen hat, hat eindeutig den besten Tag seines Lebens.'::text,'dessen'::text,'der'::text,'den'::text,'Der Mann, dessen Ellbogen sie zuerst angestoßen hat, hat eindeutig den besten Tag seines Lebens.'::text),
(349747,38861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... лікоть вона стукнула першим, явно переживає найкращий день у своєму житті.'::text,'чий'::text,'який'::text,'який'::text,'Чоловік, чий лікоть вона стукнула першим, явно переживає найкращий день у своєму житті.'::text),
(349746,38861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... codo ella chocó primero está claramente teniendo el mejor día de su vida.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El hombre cuyo codo ella chocó primero está claramente teniendo el mejor día de su vida.'::text),
(349745,38861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... elle a touché le coude en premier vit clairement le plus beau jour de sa vie.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''homme dont elle a touché le coude en premier vit clairement le plus beau jour de sa vie.'::text),
(349748,38861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadının ilk ... dirseğine vurduğu adam belli ki hayatının en güzel gününü yaşıyor.'::text,''::text,NULL::text,NULL::text,'Kadının ilk dirseğine vurduğu adam belli ki hayatının en güzel gününü yaşıyor.'::text),
(349749,38861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a férfi, ... könyökét elsőként megérintette, egyértelműen élete legjobb napját éli.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Az a férfi, akinek a könyökét elsőként megérintette, egyértelműen élete legjobb napját éli.'::text),
(349752,38862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er meinte, der Ellbogengruß ... viel cooler als ein Händedruck, ohne Witz.'::text,'sei'::text,'ist'::text,'wird'::text,'Digga, er meinte, der Ellbogengruß sei viel cooler als ein Händedruck, ohne Witz.'::text),
(349756,38862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він сказав, що стукання ліктями ... набагато крутіше за рукостискання, без жартів.'::text,'було'::text,'є'::text,'буде'::text,'Бро, він сказав, що стукання ліктями було набагато крутіше за рукостискання, без жартів.'::text),
(349755,38862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dijo que chocar los codos ... mucho más guay que dar la mano, en serio.'::text,'era'::text,'es'::text,'será'::text,'Bro, dijo que chocar los codos era mucho más guay que dar la mano, en serio.'::text),
(349754,38862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il a dit que le check du coude ... carrément plus cool qu''une poignée de main, sans mentir.'::text,'était'::text,'est'::text,'sera'::text,'Frère, il a dit que le check du coude était carrément plus cool qu''une poignée de main, sans mentir.'::text),
(349757,38862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dirsek selamının tokalaşmadan çok daha havalı ... söyledi, cidden.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Kanka, dirsek selamının tokalaşmadan çok daha havalı olduğunu söyledi, cidden.'::text),
(349758,38862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, hogy a könyökpacsi ... sokkal menőbb, mint a kézfogás, komolyan.'::text,''::text,NULL::text,'lesz'::text,'Tesó, azt mondta, hogy a könyökpacsi sokkal menőbb, mint a kézfogás, komolyan.'::text),
(349761,38863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, in diesem Büro gab es ... nur Händeschütteln, jetzt sind es Ellbogen, ziemlich ikonisch.'::text,'früher'::text,'früher'::text,'gewohnheitsmäßig'::text,'Alter, in diesem Büro gab es früher nur Händeschütteln, jetzt sind es Ellbogen, ziemlich ikonisch.'::text),
(349765,38863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, у цьому офісі ... тільки тиснули руки, а тепер ліктями, досить культово.'::text,'раніше'::text,'раніше'::text,'звикли'::text,'Чувак, у цьому офісі раніше тільки тиснули руки, а тепер ліктями, досить культово.'::text),
(349764,38863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, en esta oficina ... todo apretones de manos, ahora son codos, bastante icónico.'::text,'solía ser'::text,'solía ser'::text,'estaba acostumbrada a ser'::text,'Tío, en esta oficina solía ser todo apretones de manos, ahora son codos, bastante icónico.'::text),
(349763,38863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ce bureau, ... que des poignées de main, maintenant c''est les coudes, assez iconique.'::text,'c''était'::text,'c''était'::text,'c''était'::text,'Mec, ce bureau, c''était que des poignées de main, maintenant c''est les coudes, assez iconique.'::text),
(349766,38863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu ofiste eskiden hep tokalaşma ..., şimdi dirsek, baya ikonik.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Kanka, bu ofiste eskiden hep tokalaşma olurdu, şimdi dirsek, baya ikonik.'::text),
(349767,38863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ebben az irodában ... mindenki kezet fogott, most könyökpacsi van, elég ikonikus.'::text,'régen'::text,'régen'::text,'megszokásból'::text,'Haver, ebben az irodában régen mindenki kezet fogott, most könyökpacsi van, elég ikonikus.'::text),
(368004,40890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein riesiger Wal neben einem kleinen Boot ..., schaukelt das Boot.'::text,'auftaucht'::text,'auftauchte'::text,'auftauchen wird'::text,'Wenn ein riesiger Wal neben einem kleinen Boot auftaucht, schaukelt das Boot.'::text),
(368008,40890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли величезний кит ... поруч із маленьким човном, човен гойдається.'::text,'виринає'::text,'виринув'::text,'вирине'::text,'Коли величезний кит виринає поруч із маленьким човном, човен гойдається.'::text),
(368007,40890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una ballena enorme ... junto a un barco pequeño, el barco se balancea.'::text,'sale'::text,'salió'::text,'saldrá'::text,'Si una ballena enorme sale junto a un barco pequeño, el barco se balancea.'::text),
(368006,40890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une baleine massive ... près d''un petit bateau, le bateau tangue.'::text,'surgit'::text,'a surgi'::text,'surgira'::text,'Si une baleine massive surgit près d''un petit bateau, le bateau tangue.'::text),
(368009,40890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devasa bir balina küçük bir teknenin yanında ..., tekne sallanır.'::text,'yüzeye çıkarsa'::text,'yüzeye çıktıysa'::text,'yüzeye çıkacaksa'::text,'Devasa bir balina küçük bir teknenin yanında yüzeye çıkarsa, tekne sallanır.'::text),
(368010,40890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy hatalmas bálna ... egy kis csónak mellett, a csónak ringatózik.'::text,'feljön'::text,'feljött'::text,'fel fog jönni'::text,'Ha egy hatalmas bálna feljön egy kis csónak mellett, a csónak ringatózik.'::text),
(368013,40891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn dieser riesige Wal noch näher kommt, ... das Boot völlig stabil, ganz klar.'::text,'bleibt'::text,'bliebe'::text,'blieb'::text,'Wenn dieser riesige Wal noch näher kommt, bleibt das Boot völlig stabil, ganz klar.'::text),
(368017,40891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо цей величезний кит підпливе ще ближче, човен ... ідеально стійким, звісно.'::text,'залишиться'::text,'залишився б'::text,'залишився'::text,'Якщо цей величезний кит підпливе ще ближче, човен залишиться ідеально стійким, звісно.'::text),
(368016,40891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si esa ballena enorme se acerca un poco más, el barco ... perfectamente estable, obviamente.'::text,'se quedará'::text,'se quedaría'::text,'se quedó'::text,'Si esa ballena enorme se acerca un poco más, el barco se quedará perfectamente estable, obviamente.'::text),
(368015,40891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette baleine massive s''approche encore, le bateau ... parfaitement stable, évidemment.'::text,'restera'::text,'resterait'::text,'est resté'::text,'Si cette baleine massive s''approche encore, le bateau restera parfaitement stable, évidemment.'::text),
(368018,40891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O devasa balina biraz daha yaklaşırsa, tekne tamamen sabit ..., tabii ki.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'O devasa balina biraz daha yaklaşırsa, tekne tamamen sabit kalacak, tabii ki.'::text),
(368019,40891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az a hatalmas bálna még közelebb jön, a csónak tökéletesen stabil ..., nyilván.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha az a hatalmas bálna még közelebb jön, a csónak tökéletesen stabil marad, nyilván.'::text),
(368022,40892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der Wal ein bisschen weniger riesig, ... die beiden total ruhig, na klar.'::text,'wären'::text,'werden'::text,'sind'::text,'Wäre der Wal ein bisschen weniger riesig, wären die beiden total ruhig, na klar.'::text),
(368026,40892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кит був трохи менш величезним, ці двоє ... абсолютно спокійні, звісно.'::text,'були б'::text,'будуть'::text,NULL::text,'Якби кит був трохи менш величезним, ці двоє були б абсолютно спокійні, звісно.'::text),
(368025,40892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la ballena fuera un poco menos enorme, estos dos ... totalmente tranquilos, claro.'::text,'estarían'::text,'estarán'::text,'están'::text,'Si la ballena fuera un poco menos enorme, estos dos estarían totalmente tranquilos, claro.'::text),
(368024,40892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la baleine était un peu moins massive, ces deux-là ... totalement calmes, bien sûr.'::text,'seraient'::text,'seront'::text,'sont'::text,'Si la baleine était un peu moins massive, ces deux-là seraient totalement calmes, bien sûr.'::text),
(368027,40892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balina biraz daha az devasa olsaydı, bu ikisi tamamen sakin ..., tabii ki.'::text,'olurdu'::text,'olacak'::text,NULL::text,'Balina biraz daha az devasa olsaydı, bu ikisi tamamen sakin olurdu, tabii ki.'::text),
(368028,40892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a bálna egy kicsit kevésbé lenne hatalmas, ez a kettő teljesen nyugodt ..., persze.'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a bálna egy kicsit kevésbé lenne hatalmas, ez a kettő teljesen nyugodt lenne, persze.'::text),
(368031,40893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der riesige Wal ... von zwei Männern in gelben Regenjacken von ihrem kleinen Boot aus gesichtet.'::text,'wurde'::text,'sichtete'::text,'sichtete'::text,'Der riesige Wal wurde von zwei Männern in gelben Regenjacken von ihrem kleinen Boot aus gesichtet.'::text),
(368035,40893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезний кит ... двома чоловіками в жовтих дощовиках з їхнього маленького човна.'::text,'був помічений'::text,'помітив'::text,'спостерігав'::text,'Величезний кит був помічений двома чоловіками в жовтих дощовиках з їхнього маленького човна.'::text),
(368034,40893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ballena enorme ... por dos hombres con impermeables amarillos desde su pequeño barco.'::text,'fue vista'::text,'vio'::text,'estaba viendo'::text,'La ballena enorme fue vista por dos hombres con impermeables amarillos desde su pequeño barco.'::text),
(368033,40893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La baleine massive ... par deux hommes en cirés jaunes depuis leur petit bateau.'::text,'a été vue'::text,'a vu'::text,'voyait'::text,'La baleine massive a été vue par deux hommes en cirés jaunes depuis leur petit bateau.'::text),
(368036,40893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devasa balina, sarı yağmurluklu iki adam tarafından küçük teknelerinden ...'::text,'görüldü'::text,'gördü'::text,'görüyordu'::text,'Devasa balina, sarı yağmurluklu iki adam tarafından küçük teknelerinden görüldü.'::text),
(368037,40893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hatalmas bálnát két sárga esőkabátos férfi ... a kis csónakjukból.'::text,'vette észre'::text,'vette észre'::text,'figyelte'::text,'A hatalmas bálnát két sárga esőkabátos férfi vette észre a kis csónakjukból.'::text),
(368049,40895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der riesige Wal ... etwa 12 Meter lang sein, was das Saisonziel übertrifft.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Der riesige Wal muss etwa 12 Meter lang sein, was das Saisonziel übertrifft.'::text),
(368053,40895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезний кит ... мати близько 12 метрів завдовжки, що перевищує ціль цього сезону.'::text,'мусить'::text,'не може'::text,'мав би'::text,'Величезний кит мусить мати близько 12 метрів завдовжки, що перевищує ціль цього сезону.'::text),
(368052,40895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ballena enorme ... medir unos 12 metros, lo que supera el objetivo de esta temporada.'::text,'debe de'::text,'no puede'::text,'debería'::text,'La ballena enorme debe de medir unos 12 metros, lo que supera el objetivo de esta temporada.'::text),
(368051,40895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La baleine massive ... mesurer environ 12 mètres, ce qui dépasse l''objectif de la saison.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'La baleine massive doit mesurer environ 12 mètres, ce qui dépasse l''objectif de la saison.'::text),
(368054,40895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devasa balina yaklaşık 12 metre ..., bu da bu sezonun hedefini aşıyor.'::text,'olmalı'::text,'olamaz'::text,'olması gerekir'::text,'Devasa balina yaklaşık 12 metre olmalı, bu da bu sezonun hedefini aşıyor.'::text),
(368055,40895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hatalmas bálna ... körülbelül 12 méter hosszú, ami túlszárnyalja az idei szezon célját.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'A hatalmas bálna biztosan körülbelül 12 méter hosszú, ami túlszárnyalja az idei szezon célját.'::text),
(368058,40896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wal, ... neben dem Boot auftaucht, ist riesig, weil er sehr groß ist.'::text,'der'::text,'der'::text,'wo'::text,'Der Wal, der neben dem Boot auftaucht, ist riesig, weil er sehr groß ist.'::text),
(368062,40896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кит, ... виринає біля човна, величезний, бо він дуже великий.'::text,'який'::text,'який'::text,'де'::text,'Кит, який виринає біля човна, величезний, бо він дуже великий.'::text),
(368061,40896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ballena ... está saliendo junto al barco es enorme, porque es muy grande.'::text,'que'::text,'que'::text,'donde'::text,'La ballena que está saliendo junto al barco es enorme, porque es muy grande.'::text),
(368060,40896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La baleine ... surgit à côté du bateau est massive, parce qu''elle est très grande.'::text,'qui'::text,'qui'::text,'où'::text,'La baleine qui surgit à côté du bateau est massive, parce qu''elle est très grande.'::text),
(368063,40896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teknenin yanında ... yüzeye çıkan balina devasa, çünkü çok büyük.'::text,''::text,NULL::text,NULL::text,'Teknenin yanında yüzeye çıkan balina devasa, çünkü çok büyük.'::text),
(368064,40896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bálna, ... a csónak mellett emelkedik fel, hatalmas, mert nagyon nagy.'::text,'amely'::text,'aki'::text,'ahol'::text,'A bálna, amely a csónak mellett emelkedik fel, hatalmas, mert nagyon nagy.'::text),
(368067,40897,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Forscher berichtete, dass das riesige Exemplar am Vortag dort aufgetaucht ...'::text,'war'::text,'ist'::text,'ist'::text,'Der Forscher berichtete, dass das riesige Exemplar am Vortag dort aufgetaucht war.'::text),
(368071,40897,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дослідник повідомив, що величезна особина ... виринула там напередодні.'::text,''::text,NULL::text,NULL::text,'Дослідник повідомив, що величезна особина виринула там напередодні.'::text),
(368070,40897,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El investigador informó de que el enorme ejemplar ... salido a la superficie allí el día anterior.'::text,'había'::text,'ha'::text,'ha'::text,'El investigador informó de que el enorme ejemplar había salido a la superficie allí el día anterior.'::text),
(368069,40897,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chercheur a indiqué que le spécimen massif ... fait surface à cet endroit la veille.'::text,'avait'::text,'a'::text,'a'::text,'Le chercheur a indiqué que le spécimen massif avait fait surface à cet endroit la veille.'::text),
(368072,40897,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araştırmacı, devasa örneğin ... bir önceki gün orada yüzeye çıktığını bildirdi.'::text,''::text,NULL::text,NULL::text,'Araştırmacı, devasa örneğin bir önceki gün orada yüzeye çıktığını bildirdi.'::text),
(368073,40897,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutató jelentette, hogy a hatalmas példány ... előző nap bukkant fel ott.'::text,''::text,NULL::text,NULL::text,'A kutató jelentette, hogy a hatalmas példány előző nap bukkant fel ott.'::text),
(368076,40898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden ..., dass Wale klein sind, aber dieser riesige hat das für immer zerstört!'::text,'glaubten früher'::text,'glaubten früher'::text,'waren es gewohnt zu glauben'::text,'Die beiden glaubten früher, dass Wale klein sind, aber dieser riesige hat das für immer zerstört!'::text),
(368080,40898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці двоє ..., що кити маленькі, але цей величезний зруйнував це назавжди!'::text,'колись вірили'::text,'колись вірили'::text,'звикли вірити'::text,'Ці двоє колись вірили, що кити маленькі, але цей величезний зруйнував це назавжди!'::text),
(368079,40898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Estos dos ... que las ballenas eran pequeñas, pero esta enorme lo destruyó para siempre!'::text,'solían creer'::text,'solían creer'::text,'estaban acostumbrados a creer'::text,'¡Estos dos solían creer que las ballenas eran pequeñas, pero esta enorme lo destruyó para siempre!'::text),
(368078,40898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces deux-là ... que les baleines étaient petites, mais celle-ci, massive, a tout détruit pour toujours !'::text,'croyaient avant'::text,'croyaient avant'::text,'avaient l''habitude de croire'::text,'Ces deux-là croyaient avant que les baleines étaient petites, mais celle-ci, massive, a tout détruit pour toujours !'::text),
(368081,40898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu ikisi eskiden balinaların küçük olduğuna ..., ama bu devasa balina bunu sonsuza dek yıktı!'::text,'inanırlardı'::text,'inanırlardı'::text,'inanmaya alışkındı'::text,'Bu ikisi eskiden balinaların küçük olduğuna inanırlardı, ama bu devasa balina bunu sonsuza dek yıktı!'::text),
(368082,40898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a kettő ..., hogy a bálnák kicsik, de ez a hatalmas örökre lerombolta ezt!'::text,'régen azt hitte'::text,'régen azt hitte'::text,'megszokásból azt hitte'::text,'Ez a kettő régen azt hitte, hogy a bálnák kicsik, de ez a hatalmas örökre lerombolta ezt!'::text),
(368085,40899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Männer versuchen, jede ... des riesigen Wals mit ihrem Boot zu vermeiden.'::text,'Berührung'::text,'Berührung'::text,'Berührung'::text,'Die beiden Männer versuchen, jede Berührung des riesigen Wals mit ihrem Boot zu vermeiden.'::text),
(368089,40899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє чоловіків намагаються уникнути ... величезного кита своїм човном.'::text,'дотику до'::text,'дотику до'::text,'дотику до'::text,'Двоє чоловіків намагаються уникнути дотику до величезного кита своїм човном.'::text),
(368088,40899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos hombres intentan evitar ... a la enorme ballena con su barco.'::text,'tocar'::text,'tocar'::text,'tocar'::text,'Los dos hombres intentan evitar tocar a la enorme ballena con su barco.'::text),
(368087,40899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux hommes essaient d''éviter de ... la baleine massive avec leur bateau.'::text,'toucher'::text,'toucher'::text,'toucher'::text,'Les deux hommes essaient d''éviter de toucher la baleine massive avec leur bateau.'::text),
(368090,40899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki adam tekneleriyle devasa balinaya ... kaçınmaya çalışıyor.'::text,'dokunmaktan'::text,'dokunmaktan'::text,'dokunmaktan'::text,'İki adam tekneleriyle devasa balinaya dokunmaktan kaçınmaya çalışıyor.'::text),
(368091,40899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két férfi igyekszik elkerülni, hogy a csónakkal ... a hatalmas bálnához.'::text,'hozzáérjenek'::text,'hozzáérjenek'::text,'hozzáérjenek'::text,'A két férfi igyekszik elkerülni, hogy a csónakkal hozzáérjenek a hatalmas bálnához.'::text),
(368094,40900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wal neben dem Boot ist riesig, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Der Wal neben dem Boot ist riesig, nicht wahr?'::text),
(368098,40900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той кит біля човна величезний, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Той кит біля човна величезний, правда?'::text),
(368097,40900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esa ballena junto al barco es enorme, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Esa ballena junto al barco es enorme, ¿verdad?'::text),
(368096,40900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette baleine à côté du bateau est massive, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Cette baleine à côté du bateau est massive, n''est-ce pas ?'::text),
(368099,40900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teknenin yanındaki balina devasa, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Teknenin yanındaki balina devasa, değil mi?'::text),
(368100,40900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csónak melletti bálna hatalmas, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A csónak melletti bálna hatalmas, ugye?'::text),
(340842,37872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein bärtiger Kollege begrüßt ihn mit Handschlag, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Sein bärtiger Kollege begrüßt ihn mit Handschlag, nicht wahr?'::text),
(340846,37872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його бородатий колега вітає його рукостисканням, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Його бородатий колега вітає його рукостисканням, правда?'::text),
(340845,37872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero con barba lo saluda con un apretón de manos, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Su compañero con barba lo saluda con un apretón de manos, ¿verdad?'::text),
(340844,37872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son collègue barbu le salue d''une poignée de main, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Son collègue barbu le salue d''une poignée de main, n''est-ce pas ?'::text),
(340847,37872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakallı iş arkadaşı onu tokalaşarak selamlıyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Sakallı iş arkadaşı onu tokalaşarak selamlıyor, değil mi?'::text),
(340848,37872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakállas kollégája kézfogással köszönti, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A szakállas kollégája kézfogással köszönti, ugye?'::text),
(340851,37873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat noch nie einen einzigen Morgen verpasst, und ... sein Kollege. Keinen einzigen!'::text,'ebenso wenig'::text,'ebenso'::text,'ebenso wenig'::text,'Er hat noch nie einen einzigen Morgen verpasst, und ebenso wenig sein Kollege. Keinen einzigen!'::text),
(340855,37873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не пропустив жодного ранку, і ... його колега. Жодного!'::text,'так само не пропустив'::text,'так само пропустив'::text,'так само не пропустив'::text,'Він не пропустив жодного ранку, і так само не пропустив його колега. Жодного!'::text),
(340854,37873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No se ha perdido ni una sola mañana, y ... su compañero. ¡Ni una sola!'::text,'tampoco'::text,'también'::text,'tampoco'::text,'No se ha perdido ni una sola mañana, y tampoco su compañero. ¡Ni una sola!'::text),
(340853,37873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''a jamais raté un seul matin, et son collègue ... ! Pas un seul !'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Il n''a jamais raté un seul matin, et son collègue non plus ! Pas un seul !'::text),
(340856,37873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir sabahı bile kaçırmadı, iş arkadaşı da ...! Bir tane bile!'::text,'kaçırmadı'::text,'kaçırdı'::text,'kaçırmadı'::text,'Tek bir sabahı bile kaçırmadı, iş arkadaşı da kaçırmadı! Bir tane bile!'::text),
(340857,37873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyetlen reggelt sem hagyott ki, és a kollégája ...! Egyetlenegyet sem!'::text,'sem'::text,'is'::text,'sem'::text,'Egyetlen reggelt sem hagyott ki, és a kollégája sem! Egyetlenegyet sem!'::text),
(340860,37874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Kollege ... schon die ganze Woche auf diesen Handschlag, bevor er reinkam. Verzweifelt!'::text,'wartete'::text,'wartet'::text,'wartete'::text,'Sein Kollege wartete schon die ganze Woche auf diesen Handschlag, bevor er reinkam. Verzweifelt!'::text),
(340864,37874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його колега ... на це рукостискання цілий тиждень, перш ніж той зайшов. Відчай!'::text,'чекав'::text,'чекає'::text,'чекав'::text,'Його колега чекав на це рукостискання цілий тиждень, перш ніж той зайшов. Відчай!'::text),
(340863,37874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero ... toda la semana esperando este apretón de manos antes de que él entrara. ¡Desesperado!'::text,'llevaba'::text,'lleva'::text,'estaba'::text,'Su compañero llevaba toda la semana esperando este apretón de manos antes de que él entrara. ¡Desesperado!'::text),
(340862,37874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son collègue ... cette poignée de main depuis toute la semaine avant qu''il n''entre. Désespéré !'::text,'attendait'::text,'attend'::text,'attendait'::text,'Son collègue attendait cette poignée de main depuis toute la semaine avant qu''il n''entre. Désespéré !'::text),
(340865,37874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş arkadaşı, o içeri girmeden önce bütün hafta bu tokalaşmayı ...! Ne çaresizlik!'::text,'bekliyordu'::text,'bekliyor'::text,'bekliyordu'::text,'İş arkadaşı, o içeri girmeden önce bütün hafta bu tokalaşmayı bekliyordu! Ne çaresizlik!'::text),
(340866,37874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kollégája már egész héten ... erre a kézfogásra, mielőtt belépett. Kétségbeesett!'::text,'várt'::text,'vár'::text,'várt'::text,'A kollégája már egész héten várt erre a kézfogásra, mielőtt belépett. Kétségbeesett!'::text),
(340869,37875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... sein Kollege jede Akte auf dem Schreibtisch geprüft haben, sonst ist dieses Büro komplett verloren!'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Mittag wird sein Kollege jede Akte auf dem Schreibtisch geprüft haben, sonst ist dieses Büro komplett verloren!'::text),
(340873,37875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду його колега ... кожну папку на тому столі, інакше цьому офісу повний кінець!'::text,'перевірить'::text,'перевірить'::text,'перевірятиме'::text,'До обіду його колега перевірить кожну папку на тому столі, інакше цьому офісу повний кінець!'::text),
(340872,37875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el mediodía, su compañero ... todos los archivos de ese escritorio, o esta oficina está completamente perdida!'::text,'habrá revisado'::text,'revisará'::text,'estará revisando'::text,'¡Para el mediodía, su compañero habrá revisado todos los archivos de ese escritorio, o esta oficina está completamente perdida!'::text),
(340871,37875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, son collègue ... chaque dossier sur ce bureau, sinon cette boîte est complètement fichue !'::text,'aura vérifié'::text,'vérifiera'::text,'sera en train de vérifier'::text,'D''ici midi, son collègue aura vérifié chaque dossier sur ce bureau, sinon cette boîte est complètement fichue !'::text),
(340874,37875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar iş arkadaşı o masadaki her dosyayı ..., yoksa bu ofis tamamen mahvolur!'::text,'kontrol etmiş olacak'::text,'kontrol edecek'::text,'kontrol ediyor olacak'::text,'Öğlene kadar iş arkadaşı o masadaki her dosyayı kontrol etmiş olacak, yoksa bu ofis tamamen mahvolur!'::text),
(340875,37875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre a kollégája ... az összes aktát azon az asztalon, különben ez az iroda teljesen elveszett!'::text,'át fogja nézni'::text,'át fogja nézni'::text,'nézegetni fogja'::text,'Délre a kollégája át fogja nézni az összes aktát azon az asztalon, különben ez az iroda teljesen elveszett!'::text),
(340887,37877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre er zu spät gekommen, ... sein Kollege ihn an der Tür nicht begrüßt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wäre er zu spät gekommen, hätte sein Kollege ihn an der Tür nicht begrüßt.'::text),
(340891,37877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він запізнився, його колега ... біля дверей.'::text,'не привітав би його'::text,'не привітає його'::text,'не привітав його'::text,'Якби він запізнився, його колега не привітав би його біля дверей.'::text),
(340890,37877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera llegado tarde, su compañero ... en la puerta.'::text,'no lo habría saludado'::text,'no lo saludará'::text,'no lo saludó'::text,'Si hubiera llegado tarde, su compañero no lo habría saludado en la puerta.'::text),
(340889,37877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il était arrivé en retard, son collègue ... à la porte.'::text,'ne l''aurait pas salué'::text,'ne le saluera pas'::text,'ne l''a pas salué'::text,'S''il était arrivé en retard, son collègue ne l''aurait pas salué à la porte.'::text),
(340892,37877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geç gelseydi, iş arkadaşı onu kapıda ...'::text,'karşılamazdı'::text,'karşılamayacak'::text,'karşılamadı'::text,'Geç gelseydi, iş arkadaşı onu kapıda karşılamazdı.'::text),
(340893,37877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha későn jött volna be, a kollégája ... az ajtóban.'::text,'nem köszöntötte volna'::text,'nem fogja köszönteni'::text,'nem köszöntötte'::text,'Ha későn jött volna be, a kollégája nem köszöntötte volna az ajtóban.'::text),
(340896,37878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte ihn sein Kollege heute Morgen nicht begrüßt, ... er jetzt schlechter gelaunt.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Hätte ihn sein Kollege heute Morgen nicht begrüßt, wäre er jetzt schlechter gelaunt.'::text),
(340900,37878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби колега не привітав його сьогодні вранці, він ... зараз у гіршому настрої.'::text,'був би'::text,'був би'::text,'буде'::text,'Якби колега не привітав його сьогодні вранці, він був би зараз у гіршому настрої.'::text),
(340899,37878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su compañero no lo hubiera saludado esta mañana, ... de peor humor ahora.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si su compañero no lo hubiera saludado esta mañana, estaría de peor humor ahora.'::text),
(340898,37878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son collègue ne l''avait pas salué ce matin, il ... de moins bonne humeur maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si son collègue ne l''avait pas salué ce matin, il serait de moins bonne humeur maintenant.'::text),
(340901,37878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş arkadaşı bu sabah onu selamlamasaydı, şimdi daha kötü bir ruh halinde ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'İş arkadaşı bu sabah onu selamlamasaydı, şimdi daha kötü bir ruh halinde olurdu.'::text),
(340902,37878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kollégája ma reggel nem köszöntötte volna, most rosszabb kedvében ...'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha a kollégája ma reggel nem köszöntötte volna, most rosszabb kedvében lenne.'::text),
(340905,37879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein bärtiger Kollege soll zehn Jahre lang in diesem Büro ...'::text,'gearbeitet haben'::text,'arbeiten'::text,'arbeitend'::text,'Sein bärtiger Kollege soll zehn Jahre lang in diesem Büro gearbeitet haben.'::text),
(340909,37879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що його бородатий колега ... в цьому офісі десять років.'::text,'пропрацював'::text,'працює'::text,'працюючи'::text,'Кажуть, що його бородатий колега пропрацював в цьому офісі десять років.'::text),
(340908,37879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que su compañero con barba ... en esta oficina diez años.'::text,'ha trabajado'::text,'trabaja'::text,'trabajando'::text,'Se dice que su compañero con barba ha trabajado en esta oficina diez años.'::text),
(340907,37879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que son collègue barbu ... dans ce bureau pendant dix ans.'::text,'a travaillé'::text,'travaille'::text,'travaillant'::text,'On dit que son collègue barbu a travaillé dans ce bureau pendant dix ans.'::text),
(340910,37879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakallı iş arkadaşının bu ofiste on yıl ... söyleniyor.'::text,'çalışmış olduğu'::text,'çalıştığı'::text,'çalışarak'::text,'Sakallı iş arkadaşının bu ofiste on yıl çalışmış olduğu söyleniyor.'::text),
(340911,37879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a szakállas kollégája tíz évig ... ebben az irodában.'::text,'dolgozott'::text,'dolgozik'::text,'dolgozva'::text,'Állítólag a szakállas kollégája tíz évig dolgozott ebben az irodában.'::text),
(340914,37880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sein Kollege hat zugegeben, all die Akten selbst ..., ohne Witz.'::text,'gedruckt zu haben'::text,'zu drucken'::text,'gedruckt'::text,'Digga, sein Kollege hat zugegeben, all die Akten selbst gedruckt zu haben, ohne Witz.'::text),
(340918,37880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, його колега зізнався, що ... всі ці папки сам, без жартів.'::text,'надрукував'::text,'надрукує'::text,'надрукував'::text,'Бро, його колега зізнався, що надрукував всі ці папки сам, без жартів.'::text),
(340917,37880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, su compañero admitió ... todos esos archivos él mismo, en serio.'::text,'haber impreso'::text,'imprimir'::text,'imprimió'::text,'Bro, su compañero admitió haber impreso todos esos archivos él mismo, en serio.'::text),
(340916,37880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, son collègue a avoué ... tous ces dossiers lui-même, sans mentir.'::text,'avoir imprimé'::text,'imprimer'::text,'imprimé'::text,'Frère, son collègue a avoué avoir imprimé tous ces dossiers lui-même, sans mentir.'::text),
(340919,37880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, iş arkadaşı bütün o dosyaları kendisinin ... itiraf etti, cidden.'::text,'bastığını'::text,'basacağını'::text,'bastı'::text,'Kanka, iş arkadaşı bütün o dosyaları kendisinin bastığını itiraf etti, cidden.'::text),
(340920,37880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kollégája beismerte, hogy ... az összes aktát saját maga, komolyan.'::text,'kinyomtatta'::text,'kinyomtatja'::text,'kinyomtatta'::text,'Tesó, a kollégája beismerte, hogy kinyomtatta az összes aktát saját maga, komolyan.'::text),
(340923,37881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Kollege ... lange geblieben sein, da die Berichtsakten um 8 Uhr fertig waren.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Sein Kollege muss lange geblieben sein, da die Berichtsakten um 8 Uhr fertig waren.'::text),
(340927,37881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його колега ... допізна, адже файли зі звітом були готові до 8:00.'::text,'мабуть, залишався'::text,'мав залишитися'::text,'не міг залишатися'::text,'Його колега мабуть, залишався допізна, адже файли зі звітом були готові до 8:00.'::text),
(340926,37881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero ... hasta tarde, ya que los archivos del informe estaban listos a las 8:00.'::text,'debió de quedarse'::text,'debería haberse quedado'::text,'no pudo quedarse'::text,'Su compañero debió de quedarse hasta tarde, ya que los archivos del informe estaban listos a las 8:00.'::text),
(340925,37881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son collègue ... tard, puisque les dossiers du rapport étaient prêts à 8 h.'::text,'a dû rester'::text,'aurait dû rester'::text,'n''a pas pu rester'::text,'Son collègue a dû rester tard, puisque les dossiers du rapport étaient prêts à 8 h.'::text),
(340928,37881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor dosyaları sabah 8''de hazır olduğuna göre iş arkadaşı geç saate kadar ...'::text,'kalmış olmalı'::text,'kalmalıydı'::text,'kalmış olamaz'::text,'Rapor dosyaları sabah 8''de hazır olduğuna göre iş arkadaşı geç saate kadar kalmış olmalı.'::text),
(340929,37881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kollégája ... sokáig bent maradt, hiszen a jelentés aktái reggel 8-ra elkészültek.'::text,'biztosan'::text,'elvileg'::text,'aligha'::text,'A kollégája biztosan sokáig bent maradt, hiszen a jelentés aktái reggel 8-ra elkészültek.'::text),
(342237,38027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, die Personalabteilung ... angeblich seit drei Wochen diesen Vertrag vor.'::text,'bereitet'::text,'bereitet'::text,'bereitet'::text,'Rate mal, die Personalabteilung bereitet angeblich seit drei Wochen diesen Vertrag vor.'::text),
(342241,38027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, HR нібито ... цей договір уже три тижні.'::text,'готує'::text,'готує'::text,'готує'::text,'Уяви, HR нібито готує цей договір уже три тижні.'::text),
(342240,38027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, parece que Recursos Humanos ... este contrato desde hace tres semanas.'::text,'está preparando'::text,'está preparando'::text,'prepara'::text,'Adivina qué, parece que Recursos Humanos está preparando este contrato desde hace tres semanas.'::text),
(342239,38027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment les RH ... ce contrat depuis trois semaines.'::text,'préparent'::text,'préparent'::text,'préparent'::text,'Devine quoi, apparemment les RH préparent ce contrat depuis trois semaines.'::text),
(342242,38027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, İK güya üç haftadır bu sözleşmeyi ...'::text,'hazırlıyormuş'::text,'hazırlıyor'::text,'hazırlar'::text,'Bil bakalım ne oldu, İK güya üç haftadır bu sözleşmeyi hazırlıyormuş.'::text),
(342243,38027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag a HR már három hete ... ezt a szerződést.'::text,'készíti'::text,'készíti'::text,'készíti'::text,'Képzeld, állítólag a HR már három hete készíti ezt a szerződést.'::text),
(342246,38028,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst nachdem er den Vertrag unterschrieben hatte, ... sie ihm die Hand auf die Schulter.'::text,'legte'::text,'legte'::text,'legte'::text,'Erst nachdem er den Vertrag unterschrieben hatte, legte sie ihm die Hand auf die Schulter.'::text),
(342250,38028,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише після того, як він підписав договір, ... руку йому на плече.'::text,'вона поклала'::text,'вона поклала'::text,'вона поклала'::text,'Лише після того, як він підписав договір, вона поклала руку йому на плече.'::text),
(342249,38028,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo después de que él firmara el contrato ... la mano en el hombro.'::text,'le puso ella'::text,'ella le puso'::text,'ella sí le puso'::text,'Solo después de que él firmara el contrato le puso ella la mano en el hombro.'::text),
(342248,38028,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seulement après qu''il a signé le contrat ... la main sur son épaule.'::text,'a-t-elle posé'::text,'elle a posé'::text,'elle a bien posé'::text,'Seulement après qu''il a signé le contrat a-t-elle posé la main sur son épaule.'::text),
(342251,38028,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak sözleşmeyi imzaladıktan sonra kadın elini onun omzuna ...'::text,'koydu'::text,'koydu'::text,'koydu'::text,'Ancak sözleşmeyi imzaladıktan sonra kadın elini onun omzuna koydu.'::text),
(342252,38028,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak miután aláírta a szerződést, ... a kezét a vállára.'::text,'tette'::text,'tette'::text,'tette'::text,'Csak miután aláírta a szerződést, tette a kezét a vállára.'::text),
(342255,38029,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Managerin ließ ihn den Vertrag ..., bevor sie ihm seinen neuen Schreibtisch zeigte.'::text,'unterschreiben'::text,'unterschreiben'::text,'unterschrieben'::text,'Die Managerin ließ ihn den Vertrag unterschreiben, bevor sie ihm seinen neuen Schreibtisch zeigte.'::text),
(342259,38029,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Менеджерка змусила його ... договір, перш ніж показала йому новий стіл.'::text,'підписати'::text,'підписати'::text,'підписав'::text,'Менеджерка змусила його підписати договір, перш ніж показала йому новий стіл.'::text),
(342258,38029,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jefa le hizo ... el contrato antes de enseñarle su nuevo escritorio.'::text,'firmar'::text,'firmar'::text,'firmado'::text,'La jefa le hizo firmar el contrato antes de enseñarle su nuevo escritorio.'::text),
(342257,38029,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La manager lui a fait ... le contrat avant de lui montrer son nouveau bureau.'::text,'signer'::text,'signer'::text,'signé'::text,'La manager lui a fait signer le contrat avant de lui montrer son nouveau bureau.'::text),
(342260,38029,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müdür, ona yeni masasını göstermeden önce sözleşmeyi ona ...'::text,'imzalattı'::text,'imzalattı'::text,'imzaladı'::text,'Müdür, ona yeni masasını göstermeden önce sözleşmeyi ona imzalattı.'::text),
(342261,38029,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A menedzser ... vele a szerződést, mielőtt megmutatta neki az új asztalát.'::text,'aláíratta'::text,'aláíratta'::text,'aláírta'::text,'A menedzser aláíratta vele a szerződést, mielőtt megmutatta neki az új asztalát.'::text),
(342264,38030,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Managerin wünscht sich, dass jeder neue Mitarbeiter einen Vertrag so schnell ...'::text,'unterschreiben würde'::text,'unterschreibt'::text,'unterschreiben wird'::text,'Seine Managerin wünscht sich, dass jeder neue Mitarbeiter einen Vertrag so schnell unterschreiben würde.'::text),
(342268,38030,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його менеджерка хоче, щоб кожен новий працівник ... договір так швидко.'::text,'підписував'::text,'підписує'::text,'підпише'::text,'Його менеджерка хоче, щоб кожен новий працівник підписував договір так швидко.'::text),
(342267,38030,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su jefa desearía que cada nuevo empleado ... un contrato así de rápido.'::text,'firmara'::text,'firma'::text,'firmará'::text,'Su jefa desearía que cada nuevo empleado firmara un contrato así de rápido.'::text),
(342266,38030,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa manager aimerait que chaque nouvel employé ... un contrat aussi vite.'::text,'signe'::text,'signe'::text,'signera'::text,'Sa manager aimerait que chaque nouvel employé signe un contrat aussi vite.'::text),
(342269,38030,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müdürü, her yeni çalışanın sözleşmeyi bu kadar hızlı ... istiyor.'::text,'imzalamasını'::text,'imzaladığını'::text,'imzalayacağını'::text,'Müdürü, her yeni çalışanın sözleşmeyi bu kadar hızlı imzalamasını istiyor.'::text),
(342270,38030,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A menedzsere azt szeretné, ha minden új munkatárs ilyen gyorsan ... alá egy szerződést.'::text,'írna'::text,'ír'::text,'fog írni'::text,'A menedzsere azt szeretné, ha minden új munkatárs ilyen gyorsan írna alá egy szerződést.'::text),
(342282,38032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Vertrag wurde in etwa zehn Sekunden unterschrieben, ... seiner beträchtlichen Länge.'::text,'trotz'::text,'obwohl'::text,'für den Fall'::text,'Der Vertrag wurde in etwa zehn Sekunden unterschrieben, trotz seiner beträchtlichen Länge.'::text),
(342286,38032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Договір підписали приблизно за десять секунд, ... його значний обсяг.'::text,'попри'::text,'хоча'::text,'на випадок'::text,'Договір підписали приблизно за десять секунд, попри його значний обсяг.'::text),
(342285,38032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El contrato se firmó en aproximadamente diez segundos, ... su considerable extensión.'::text,'a pesar de'::text,'aunque'::text,'por si'::text,'El contrato se firmó en aproximadamente diez segundos, a pesar de su considerable extensión.'::text),
(342284,38032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le contrat a été signé en environ dix secondes, ... sa longueur considérable.'::text,'malgré'::text,'bien que'::text,'au cas où'::text,'Le contrat a été signé en environ dix secondes, malgré sa longueur considérable.'::text),
(342287,38032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sözleşme, oldukça uzun olmasına ... yaklaşık on saniyede imzalandı.'::text,'rağmen'::text,'rağmen'::text,'diye'::text,'Sözleşme, oldukça uzun olmasına rağmen yaklaşık on saniyede imzalandı.'::text),
(342288,38032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szerződést nagyjából tíz másodperc alatt aláírták, jelentős hossza ...'::text,'ellenére'::text,'bár'::text,'arra az esetre'::text,'A szerződést nagyjából tíz másodperc alatt aláírták, jelentős hossza ellenére.'::text),
(342291,38033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In dem Moment, als er den Vertrag unterschrieb, wusste er, dass sein altes Leben für immer ...!'::text,'vorbei sein würde'::text,'vorbei sein wird'::text,'vorbei ist'::text,'In dem Moment, als er den Vertrag unterschrieb, wusste er, dass sein altes Leben für immer vorbei sein würde!'::text),
(342295,38033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно він підписав той договір, він знав, що його старе життя ... назавжди!'::text,'зникне'::text,'зникне'::text,'зникло'::text,'Щойно він підписав той договір, він знав, що його старе життя зникне назавжди!'::text),
(342294,38033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En cuanto firmó ese contrato, supo que su vieja vida ... para siempre!'::text,'se acabaría'::text,'se acabará'::text,'se acaba'::text,'¡En cuanto firmó ese contrato, supo que su vieja vida se acabaría para siempre!'::text),
(342293,38033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où il a signé ce contrat, il a su que son ancienne vie ... pour toujours !'::text,'serait finie'::text,'sera finie'::text,'est finie'::text,'Au moment où il a signé ce contrat, il a su que son ancienne vie serait finie pour toujours !'::text),
(342296,38033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sözleşmeyi imzaladığı an, eski hayatının sonsuza dek ... biliyordu!'::text,'biteceğini'::text,'biteceğini'::text,'bittiğini'::text,'O sözleşmeyi imzaladığı an, eski hayatının sonsuza dek biteceğini biliyordu!'::text),
(342297,38033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abban a pillanatban, hogy aláírta a szerződést, tudta, hogy a régi élete örökre ...!'::text,'oda lesz'::text,'oda lesz'::text,'oda van'::text,'Abban a pillanatban, hogy aláírta a szerződést, tudta, hogy a régi élete örökre oda lesz!'::text),
(342300,38034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ganze Büro ... gerade wie verrückt, und keiner hat den Vertrag gelesen!'::text,'klatscht'::text,'klatscht'::text,'hat geklatscht'::text,'Das ganze Büro klatscht gerade wie verrückt, und keiner hat den Vertrag gelesen!'::text),
(342304,38034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Увесь офіс саме зараз ... як скажений, а ніхто навіть не читав той договір!'::text,'аплодує'::text,'аплодує'::text,'аплодував'::text,'Увесь офіс саме зараз аплодує як скажений, а ніхто навіть не читав той договір!'::text),
(342303,38034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Toda la oficina ... como loca ahora mismo, y nadie ha leído ese contrato!'::text,'está aplaudiendo'::text,'aplaude'::text,'ha aplaudido'::text,'¡Toda la oficina está aplaudiendo como loca ahora mismo, y nadie ha leído ese contrato!'::text),
(342302,38034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le bureau ... comme des fous en ce moment, et personne n''a lu ce contrat !'::text,'applaudit'::text,'applaudit'::text,'a applaudi'::text,'Tout le bureau applaudit comme des fous en ce moment, et personne n''a lu ce contrat !'::text),
(342305,38034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün ofis şu an deli gibi ... ve o sözleşmeyi kimse okumadı!'::text,'alkışlıyor'::text,'alkışlar'::text,'alkışladı'::text,'Bütün ofis şu an deli gibi alkışlıyor ve o sözleşmeyi kimse okumadı!'::text),
(342306,38034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész iroda épp most ... őrült módjára, és senki sem olvasta el azt a szerződést!'::text,'tapsol'::text,'tapsol'::text,'tapsolt'::text,'Az egész iroda épp most tapsol őrült módjára, és senki sem olvasta el azt a szerződést!'::text),
(342309,38035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis er den Vertrag unterschrieb, ... sie schon eine volle Minute auf diese Zeile gezeigt. Unglaublich!'::text,'hatte'::text,'hatte'::text,'hat'::text,'Bis er den Vertrag unterschrieb, hatte sie schon eine volle Minute auf diese Zeile gezeigt. Unglaublich!'::text),
(342313,38035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він нарешті підписав договір, вона вже цілу хвилину ... на той рядок. Неймовірно!'::text,'показувала'::text,'показувала'::text,'показує'::text,'Коли він нарешті підписав договір, вона вже цілу хвилину показувала на той рядок. Неймовірно!'::text),
(342312,38035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando firmó el contrato, ella ... un minuto entero señalando esa línea. ¡Increíble!'::text,'llevaba'::text,'estaba'::text,'lleva'::text,'Para cuando firmó el contrato, ella llevaba un minuto entero señalando esa línea. ¡Increíble!'::text),
(342311,38035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a signé le contrat, elle ... cette ligne du doigt depuis une bonne minute. Incroyable !'::text,'montrait'::text,'montrait'::text,'montre'::text,'Quand il a signé le contrat, elle montrait cette ligne du doigt depuis une bonne minute. Incroyable !'::text),
(342314,38035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sözleşmeyi imzaladığında kadın tam bir dakikadır o satırı ...! İnanılmaz!'::text,'gösteriyordu'::text,'gösteriyordu'::text,'gösteriyor'::text,'O sözleşmeyi imzaladığında kadın tam bir dakikadır o satırı gösteriyordu! İnanılmaz!'::text),
(342315,38035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire aláírta a szerződést, ő már egy teljes perce ... arra a sorra. Hihetetlen!'::text,'mutatott'::text,'mutatott'::text,'mutat'::text,'Mire aláírta a szerződést, ő már egy teljes perce mutatott arra a sorra. Hihetetlen!'::text),
(342318,38036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich wird er bis nächsten Monat zehn weitere solche Verträge ...'::text,'unterschrieben haben'::text,'unterschreiben'::text,'unterschreiben'::text,'Bestie, angeblich wird er bis nächsten Monat zehn weitere solche Verträge unterschrieben haben.'::text),
(342322,38036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до наступного місяця він ... ще десять таких договорів.'::text,'підпише'::text,'підпише'::text,'підписує'::text,'Подруго, кажуть, до наступного місяця він підпише ще десять таких договорів.'::text),
(342321,38036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que para el mes que viene él ... diez contratos más como ese.'::text,'habrá firmado'::text,'firmará'::text,'firma'::text,'Amiga, parece que para el mes que viene él habrá firmado diez contratos más como ese.'::text),
(342320,38036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment d''ici le mois prochain, il ... dix autres contrats comme celui-là.'::text,'aura signé'::text,'signera'::text,'signe'::text,'Ma belle, apparemment d''ici le mois prochain, il aura signé dix autres contrats comme celui-là.'::text),
(342323,38036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya gelecek aya kadar o, bunun gibi on sözleşme daha ...'::text,'imzalamış olacak'::text,'imzalayacak'::text,'imzalıyor'::text,'Kanka, güya gelecek aya kadar o, bunun gibi on sözleşme daha imzalamış olacak.'::text),
(342324,38036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag jövő hónapra ő ... még tíz ilyen szerződést.'::text,'alá fog írni'::text,'alá fog írni'::text,'aláír'::text,'Csajszi, állítólag jövő hónapra ő alá fog írni még tíz ilyen szerződést.'::text),
(339204,37690,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er die letzte Schublade ..., übernahm das Chaos auf dem Boden komplett das Zimmer!'::text,'ausleerte'::text,'ausleerte'::text,'ausgeleert hat'::text,'Während er die letzte Schublade ausleerte, übernahm das Chaos auf dem Boden komplett das Zimmer!'::text),
(339208,37690,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... останню шухляду, хаос на підлозі повністю захопив кімнату!'::text,'спорожнював'::text,'спорожнив'::text,'спорожнив'::text,'Поки він спорожнював останню шухляду, хаос на підлозі повністю захопив кімнату!'::text),
(339207,37690,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras él ... el último cajón, el caos del suelo se apoderó por completo de la habitación!'::text,'estaba vaciando'::text,'vació'::text,'ha vaciado'::text,'¡Mientras él estaba vaciando el último cajón, el caos del suelo se apoderó por completo de la habitación!'::text),
(339206,37690,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... le dernier tiroir, le chaos par terre a complètement envahi la pièce !'::text,'vidait'::text,'a vidé'::text,'a vidé'::text,'Pendant qu''il vidait le dernier tiroir, le chaos par terre a complètement envahi la pièce !'::text),
(339209,37690,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O son çekmeceyi ..., yerdeki kaos odayı tamamen ele geçirdi!'::text,'boşaltırken'::text,'boşalttığında'::text,'boşaltmışken'::text,'O son çekmeceyi boşaltırken, yerdeki kaos odayı tamamen ele geçirdi!'::text),
(339210,37690,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... az utolsó fiókot, a padlón lévő káosz teljesen elfoglalta a szobát!'::text,'ürítette'::text,'kiürítette'::text,'kiürítette'::text,'Miközben ő ürítette az utolsó fiókot, a padlón lévő káosz teljesen elfoglalta a szobát!'::text),
(339213,37691,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon den ganzen Nachmittag Schubladen auf den Boden aus und hat immer noch nicht aufgehört. Totales Chaos!'::text,'leert'::text,'leerte'::text,'leert'::text,'Er leert schon den ganzen Nachmittag Schubladen auf den Boden aus und hat immer noch nicht aufgehört. Totales Chaos!'::text),
(339217,37691,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... шухляди на підлогу все пообіддя і досі не зупинився. Повний хаос!'::text,'спорожнює'::text,'спорожнив'::text,'спорожнює'::text,'Він спорожнює шухляди на підлогу все пообіддя і досі не зупинився. Повний хаос!'::text),
(339216,37691,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... cajones en el suelo toda la tarde y todavía no ha parado. ¡Caos total!'::text,'ha estado vaciando'::text,'vació'::text,'está vaciando'::text,'Él ha estado vaciando cajones en el suelo toda la tarde y todavía no ha parado. ¡Caos total!'::text),
(339215,37691,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des tiroirs par terre depuis le début de l''après-midi et ne s''est toujours pas arrêté. Chaos total !'::text,'vide'::text,'a vidé'::text,'vide'::text,'Il vide des tiroirs par terre depuis le début de l''après-midi et ne s''est toujours pas arrêté. Chaos total !'::text),
(339218,37691,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün öğleden sonra çekmeceleri yere ... ve hâlâ durmadı. Tam bir kaos!'::text,'boşaltıyor'::text,'boşalttı'::text,'boşaltıyor'::text,'Bütün öğleden sonra çekmeceleri yere boşaltıyor ve hâlâ durmadı. Tam bir kaos!'::text),
(339219,37691,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délután ... a fiókokat a padlóra, és még mindig nem hagyta abba. Teljes káosz!'::text,'ürítgeti'::text,'ürítette ki'::text,'üríti'::text,'Egész délután ürítgeti a fiókokat a padlóra, és még mindig nem hagyta abba. Teljes káosz!'::text),
(339231,37693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch eine Schublade ausleert, ... das Chaos auch das Sofa.'::text,'erreicht'::text,'erreichte'::text,'erreichte'::text,'Wenn er noch eine Schublade ausleert, erreicht das Chaos auch das Sofa.'::text),
(339235,37693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він спорожнить ще одну шухляду, хаос ... і до дивана.'::text,'дістанеться'::text,'дістався б'::text,'дістався'::text,'Якщо він спорожнить ще одну шухляду, хаос дістанеться і до дивана.'::text),
(339234,37693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si vacía un cajón más, el caos ... también al sofá.'::text,'llegará'::text,'llegaría'::text,'llegó'::text,'Si vacía un cajón más, el caos llegará también al sofá.'::text),
(339233,37693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il vide encore un tiroir, le chaos ... aussi le canapé.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'S''il vide encore un tiroir, le chaos atteindra aussi le canapé.'::text),
(339236,37693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir çekmece daha boşaltırsa, kaos kanepeye de ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Bir çekmece daha boşaltırsa, kaos kanepeye de ulaşacak.'::text),
(339237,37693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy fiókot kiürít, a káosz a kanapét is ...'::text,'eléri'::text,'elérné'::text,'elérte'::text,'Ha még egy fiókot kiürít, a káosz a kanapét is eléri.'::text),
(339240,37694,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er weniger Spielzeug hätte, ... das Chaos auf seinem Boden viel kleiner.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn er weniger Spielzeug hätte, wäre das Chaos auf seinem Boden viel kleiner.'::text),
(339244,37694,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в нього було менше іграшок, хаос на його підлозі ... набагато меншим.'::text,'був би'::text,'буде'::text,NULL::text,'Якби в нього було менше іграшок, хаос на його підлозі був би набагато меншим.'::text),
(339243,37694,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuviera menos juguetes, el caos de su suelo ... mucho menor.'::text,'sería'::text,'será'::text,'es'::text,'Si tuviera menos juguetes, el caos de su suelo sería mucho menor.'::text),
(339242,37694,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait moins de jouets, le chaos sur son sol ... beaucoup plus petit.'::text,'serait'::text,'sera'::text,'est'::text,'S''il avait moins de jouets, le chaos sur son sol serait beaucoup plus petit.'::text),
(339245,37694,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha az oyuncağı olsaydı, yerdeki kaos çok daha küçük ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Daha az oyuncağı olsaydı, yerdeki kaos çok daha küçük olurdu.'::text),
(339246,37694,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kevesebb játéka lenne, a káosz a padlóján sokkal kisebb ...'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha kevesebb játéka lenne, a káosz a padlóján sokkal kisebb lenne.'::text),
(339249,37695,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Chaos ... vorhin von einem einzigen Mann und einem einzigen Schrank angerichtet.'::text,'wurde'::text,'wird'::text,'richtete'::text,'Dieses Chaos wurde vorhin von einem einzigen Mann und einem einzigen Schrank angerichtet.'::text),
(339253,37695,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей хаос ... раніше одним чоловіком і однією-єдиною шафою.'::text,'був створений'::text,'створюється'::text,'створив'::text,'Цей хаос був створений раніше одним чоловіком і однією-єдиною шафою.'::text),
(339252,37695,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este caos ... antes por un solo hombre y un único armario.'::text,'fue creado'::text,'es creado'::text,'creó'::text,'Este caos fue creado antes por un solo hombre y un único armario.'::text),
(339251,37695,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce chaos ... plus tôt par un seul homme et une seule armoire.'::text,'a été créé'::text,'est créé'::text,'a créé'::text,'Ce chaos a été créé plus tôt par un seul homme et une seule armoire.'::text),
(339254,37695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kaos daha önce tek bir adam ve tek bir dolap tarafından ...'::text,'yaratıldı'::text,'yaratılıyor'::text,'yarattı'::text,'Bu kaos daha önce tek bir adam ve tek bir dolap tarafından yaratıldı.'::text),
(339255,37695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezt a káoszt korábban egyetlen férfi és egyetlen szekrény ...'::text,'okozta'::text,'okozza'::text,'okozta'::text,'Ezt a káoszt korábban egyetlen férfi és egyetlen szekrény okozta.'::text),
(339258,37696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Chaos selbst, als er die letzte Schublade ausleerte.'::text,'verursachte'::text,'wurde verursacht'::text,'verursachend'::text,'Er verursachte das Chaos selbst, als er die letzte Schublade ausleerte.'::text),
(339262,37696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сам ... цей хаос, коли спорожнив останню шухляду.'::text,'створив'::text,'був створений'::text,'створюючи'::text,'Він сам створив цей хаос, коли спорожнив останню шухляду.'::text),
(339261,37696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él mismo ... el caos cuando vació el último cajón.'::text,'creó'::text,'fue creado'::text,'creando'::text,'Él mismo creó el caos cuando vació el último cajón.'::text),
(339260,37696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le chaos lui-même quand il a vidé le dernier tiroir.'::text,'a créé'::text,'a été créé'::text,'créant'::text,'Il a créé le chaos lui-même quand il a vidé le dernier tiroir.'::text),
(339263,37696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son çekmeceyi boşalttığında kaosu kendisi ...'::text,'yarattı'::text,'yaratıldı'::text,'yaratarak'::text,'Son çekmeceyi boşalttığında kaosu kendisi yarattı.'::text),
(339264,37696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A káoszt ő maga ..., amikor kiürítette az utolsó fiókot.'::text,'okozta'::text,'okozódott'::text,'okozva'::text,'A káoszt ő maga okozta, amikor kiürítette az utolsó fiókot.'::text),
(339267,37697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... jedes Brettspiel der Welt besitzen, um so ein beeindruckendes Chaos zu machen.'::text,'musst'::text,'kannst nicht'::text,'solltest'::text,'Ehrlich, du musst jedes Brettspiel der Welt besitzen, um so ein beeindruckendes Chaos zu machen.'::text),
(339271,37697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... мати всі настільні ігри на світі, щоб влаштувати такий вражаючий хаос.'::text,'мусиш'::text,'не можеш'::text,'мав би'::text,'Чесно, ти мусиш мати всі настільні ігри на світі, щоб влаштувати такий вражаючий хаос.'::text),
(339270,37697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ... tener todos los juegos de mesa del mundo para montar un caos tan impresionante.'::text,'debes de'::text,'no puedes'::text,'deberías'::text,'En serio, debes de tener todos los juegos de mesa del mundo para montar un caos tan impresionante.'::text),
(339269,37697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... avoir tous les jeux de société du monde pour faire un chaos aussi impressionnant.'::text,'dois'::text,'ne peux pas'::text,'devrais'::text,'Franchement, tu dois avoir tous les jeux de société du monde pour faire un chaos aussi impressionnant.'::text),
(339272,37697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu kadar etkileyici bir kaos yaratmak için dünyadaki bütün kutu oyunlarına sahip ...'::text,'olmalısın'::text,'olamazsın'::text,'olman gerekir'::text,'Açıkçası, bu kadar etkileyici bir kaos yaratmak için dünyadaki bütün kutu oyunlarına sahip olmalısın.'::text),
(339273,37697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, neked ... az összes társasjáték megvan, ha ilyen lenyűgöző káoszt tudsz csinálni.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'Őszintén, neked biztosan az összes társasjáték megvan, ha ilyen lenyűgöző káoszt tudsz csinálni.'::text),
(339276,37698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schrank, ... er auf den Boden ausgeleert hat, hat dieses Chaos ausgelöst. Perfekte Planung.'::text,'den'::text,'der'::text,'dessen'::text,'Der Schrank, den er auf den Boden ausgeleert hat, hat dieses Chaos ausgelöst. Perfekte Planung.'::text),
(339280,37698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шафа, ... він спорожнив на підлогу, спричинила цей хаос. Бездоганне планування.'::text,'яку'::text,'хто'::text,'чия'::text,'Шафа, яку він спорожнив на підлогу, спричинила цей хаос. Бездоганне планування.'::text),
(339279,37698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El armario ... vació en el suelo provocó este caos. Planificación impecable.'::text,'que'::text,'quien'::text,'cuyo'::text,'El armario que vació en el suelo provocó este caos. Planificación impecable.'::text),
(339278,37698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''armoire ... l''homme a vidée par terre a déclenché ce chaos. Planification impeccable.'::text,'que'::text,'qui'::text,'dont'::text,'L''armoire que l''homme a vidée par terre a déclenché ce chaos. Planification impeccable.'::text),
(339281,37698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yere ... boşalttığı dolap bu kaosu başlattı. Kusursuz planlama.'::text,''::text,NULL::text,NULL::text,'Yere boşalttığı dolap bu kaosu başlattı. Kusursuz planlama.'::text),
(339282,37698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szekrény, ... a padlóra ürített, elindította ezt a káoszt. Hibátlan tervezés.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'A szekrény, amelyet a padlóra ürített, elindította ezt a káoszt. Hibátlan tervezés.'::text),
(339285,37699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... sein Zimmer auf, und dann ging das Chaos los. Super gemacht.'::text,'räume'::text,'räumt'::text,'räumt'::text,'Er sagte, er räume sein Zimmer auf, und dann ging das Chaos los. Super gemacht.'::text),
(339289,37699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що ... свою кімнату, а потім почався хаос. Чудова робота.'::text,'прибирає'::text,'прибирає'::text,'прибирає'::text,'Він сказав, що прибирає свою кімнату, а потім почався хаос. Чудова робота.'::text),
(339288,37699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... su habitación, y entonces empezó el caos. Buen trabajo.'::text,'estaba ordenando'::text,'está ordenando'::text,'ordena'::text,'Dijo que estaba ordenando su habitación, y entonces empezó el caos. Buen trabajo.'::text),
(339287,37699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... sa chambre, et puis le chaos a commencé. Bravo.'::text,'rangeait'::text,'range'::text,'range'::text,'Il a dit qu''il rangeait sa chambre, et puis le chaos a commencé. Bravo.'::text),
(339290,37699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odasını ... söyledi, sonra da kaos başladı. Harika iş.'::text,'topladığını'::text,'topladığını'::text,'topladığını'::text,'Odasını topladığını söyledi, sonra da kaos başladı. Harika iş.'::text),
(339291,37699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy ... a szobáját, aztán elkezdődött a káosz. Szép munka.'::text,'rendbe teszi'::text,'rendbe teszi'::text,'rendbe teszi'::text,'Azt mondta, hogy rendbe teszi a szobáját, aztán elkezdődött a káosz. Szép munka.'::text),
(339294,37700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Zimmer ... vor dem Chaos ordentlich, ganz klar.'::text,'war früher'::text,'war früher'::text,'war gewohnt'::text,'Dieses Zimmer war früher vor dem Chaos ordentlich, ganz klar.'::text),
(339298,37700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця кімната ... охайною до хаосу, звісно.'::text,'колись була'::text,'колись була'::text,'звикла бути'::text,'Ця кімната колись була охайною до хаосу, звісно.'::text),
(339297,37700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta habitación ... ordenada antes del caos, obviamente.'::text,'solía estar'::text,'solía estar'::text,'estaba acostumbrada a estar'::text,'Esta habitación solía estar ordenada antes del caos, obviamente.'::text),
(339296,37700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette chambre ... rangée avant le chaos, évidemment.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'Cette chambre était rangée avant le chaos, évidemment.'::text),
(339299,37700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu oda kaostan önce toplu ..., tabii ki.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu oda kaostan önce toplu olurdu, tabii ki.'::text),
(339300,37700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a szoba a káosz előtt rendes ..., nyilván.'::text,'volt régen'::text,'volt régen'::text,'szokott lenni'::text,'Ez a szoba a káosz előtt rendes volt régen, nyilván.'::text),
(350283,38921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die Gruppe sie wieder von den Matten aus. Offensichtlich braucht sie die Hilfe.'::text,'ermutigt'::text,'ermutigt'::text,'ermutigt'::text,'Morgen um diese Zeit ermutigt die Gruppe sie wieder von den Matten aus. Offensichtlich braucht sie die Hilfe.'::text),
(350287,38921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час група знову ... її з матів. Їй явно потрібна допомога.'::text,'підбадьорюватиме'::text,'підбадьорить'::text,'підбадьорює'::text,'Завтра в цей час група знову підбадьорюватиме її з матів. Їй явно потрібна допомога.'::text),
(350286,38921,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el grupo ... otra vez desde las colchonetas. Está claro que necesita la ayuda.'::text,'la estará animando'::text,'la animará'::text,'la anima'::text,'Mañana a esta hora, el grupo la estará animando otra vez desde las colchonetas. Está claro que necesita la ayuda.'::text),
(350285,38921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, le groupe ... encore depuis les tapis. Elle a clairement besoin d''aide.'::text,'sera en train de l''encourager'::text,'l''encouragera'::text,'l''encourage'::text,'Demain à la même heure, le groupe sera en train de l''encourager encore depuis les tapis. Elle a clairement besoin d''aide.'::text),
(350288,38921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte grup onu yine minderlerden ...; belli ki yardıma ihtiyacı var.'::text,'cesaretlendiriyor olacak'::text,'cesaretlendirecek'::text,'cesaretlendiriyor'::text,'Yarın bu saatte grup onu yine minderlerden cesaretlendiriyor olacak; belli ki yardıma ihtiyacı var.'::text),
(350289,38921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a csoport megint ... őt a szőnyegekről. Nyilván szüksége van a segítségre.'::text,'bátorítani fogja'::text,'bátorítani fogja'::text,'bátorítja'::text,'Holnap ilyenkor a csoport megint bátorítani fogja őt a szőnyegekről. Nyilván szüksége van a segítségre.'::text),
(350292,38922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gruppe verspricht, dass sie sie bei jedem Aufstieg ...'::text,'ermutigen wird'::text,'ermutigen wird'::text,'gerade ermutigt'::text,'Die Gruppe verspricht, dass sie sie bei jedem Aufstieg ermutigen wird.'::text),
(350296,38922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Група обіцяє, що ... її під час кожного підйому.'::text,'підбадьорить'::text,'підбадьорюватиме'::text,'підбадьорює'::text,'Група обіцяє, що підбадьорить її під час кожного підйому.'::text),
(350295,38922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El grupo promete que la ... en cada escalada.'::text,'animará'::text,'estará animando'::text,'está animando'::text,'El grupo promete que la animará en cada escalada.'::text),
(350294,38922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe promet qu''il ... à chaque ascension.'::text,'l''encouragera'::text,'l''encouragera'::text,'l''encourage'::text,'Le groupe promet qu''il l''encouragera à chaque ascension.'::text),
(350297,38922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup, her tırmanışta onu ... söz veriyor.'::text,'cesaretlendireceğine'::text,'cesaretlendiriyor olacağına'::text,'cesaretlendirdiğine'::text,'Grup, her tırmanışta onu cesaretlendireceğine söz veriyor.'::text),
(350298,38922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csoport megígéri, hogy minden mászásnál ... őt.'::text,'bátorítani fogja'::text,'bátorítani fogja'::text,'bátorítja'::text,'A csoport megígéri, hogy minden mászásnál bátorítani fogja őt.'::text),
(350301,38923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Freunde eine Kletterin von den Matten aus ..., klettert sie meistens höher.'::text,'ermutigen'::text,'ermutigten'::text,'ermutigen werden'::text,'Wenn Freunde eine Kletterin von den Matten aus ermutigen, klettert sie meistens höher.'::text),
(350305,38923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли друзі ... скелелазку з матів, вона зазвичай лізе вище.'::text,'підбадьорюють'::text,'підбадьорювали'::text,'підбадьорюватимуть'::text,'Коли друзі підбадьорюють скелелазку з матів, вона зазвичай лізе вище.'::text),
(350304,38923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los amigos ... a una escaladora desde las colchonetas, normalmente sube más alto.'::text,'animan'::text,'animaron'::text,'animarán'::text,'Si los amigos animan a una escaladora desde las colchonetas, normalmente sube más alto.'::text),
(350303,38923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si des amis ... une grimpeuse depuis les tapis, elle grimpe généralement plus haut.'::text,'encouragent'::text,'encourageaient'::text,'encourageront'::text,'Si des amis encouragent une grimpeuse depuis les tapis, elle grimpe généralement plus haut.'::text),
(350306,38923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar bir tırmanıcıyı minderlerden ..., genelde daha yükseğe tırmanır.'::text,'cesaretlendirirse'::text,'cesaretlendirdiyse'::text,'cesaretlendirecekse'::text,'Arkadaşlar bir tırmanıcıyı minderlerden cesaretlendirirse, genelde daha yükseğe tırmanır.'::text),
(350307,38923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a barátok ... egy mászót a szőnyegekről, általában magasabbra mászik.'::text,'bátorítanak'::text,'bátorítottak'::text,'bátorítani fognak'::text,'Ha a barátok bátorítanak egy mászót a szőnyegekről, általában magasabbra mászik.'::text),
(350319,38925,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für eine Albtraumwand! Sie haben sie den ganzen Weg nach oben ermutigt, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Was für eine Albtraumwand! Sie haben sie den ganzen Weg nach oben ermutigt, nicht wahr?'::text),
(350323,38925,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яка жахлива стіна! Вони підбадьорювали її всю дорогу нагору, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Яка жахлива стіна! Вони підбадьорювали її всю дорогу нагору, правда?'::text),
(350322,38925,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué pared de pesadilla! La animaron durante toda la subida, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'¡Qué pared de pesadilla! La animaron durante toda la subida, ¿verdad?'::text),
(350321,38925,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quel mur cauchemardesque ! Ils l''ont encouragée pendant toute la montée, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Quel mur cauchemardesque ! Ils l''ont encouragée pendant toute la montée, n''est-ce pas ?'::text),
(350324,38925,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kâbus bir duvar! Onu yukarı çıkana kadar cesaretlendirdiler, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Ne kâbus bir duvar! Onu yukarı çıkana kadar cesaretlendirdiler, değil mi?'::text),
(350325,38925,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda rémálom fal! Végig bátorították felfelé, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Micsoda rémálom fal! Végig bátorították felfelé, ugye?'::text),
(350328,38926,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kletterer schreien, um sie zu ermutigen, und die ganze Halle ...!'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Die Kletterer schreien, um sie zu ermutigen, und die ganze Halle auch!'::text),
(350332,38926,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скелелази кричать, щоб її підбадьорити, і вся зала ...!'::text,'теж'::text,'теж'::text,'теж ні'::text,'Скелелази кричать, щоб її підбадьорити, і вся зала теж!'::text),
(350331,38926,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los escaladores gritan para animarla, y todo el gimnasio ...!'::text,'también'::text,'también'::text,'tampoco'::text,'¡Los escaladores gritan para animarla, y todo el gimnasio también!'::text),
(350330,38926,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les grimpeurs crient pour l''encourager, et toute la salle ... !'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Les grimpeurs crient pour l''encourager, et toute la salle aussi !'::text),
(350333,38926,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tırmanıcılar onu cesaretlendirmek için bağırıyor, bütün salon da ...!'::text,'bağırıyor'::text,'bağırıyor'::text,'bağırmıyor'::text,'Tırmanıcılar onu cesaretlendirmek için bağırıyor, bütün salon da bağırıyor!'::text),
(350334,38926,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mászók kiabálnak, hogy bátorítsák, és az egész terem ...!'::text,'is'::text,'is'::text,'sem'::text,'A mászók kiabálnak, hogy bátorítsák, és az egész terem is!'::text),
(350337,38927,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, bis zum Ende des Trainings ... sie jeden einzelnen Kletterer in der Halle ermutigt haben.'::text,'werden'::text,'werden'::text,'werden'::text,'Hör mal, ich hab gehört, bis zum Ende des Trainings werden sie jeden einzelnen Kletterer in der Halle ermutigt haben.'::text),
(350341,38927,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що до кінця тренування вони ... кожного скелелаза в залі.'::text,'підбадьорять'::text,'підбадьорять'::text,'підбадьорюватимуть'::text,'Слухай, я чула, що до кінця тренування вони підбадьорять кожного скелелаза в залі.'::text),
(350340,38927,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que para el final de la sesión ... a cada escalador del gimnasio.'::text,'habrán animado'::text,'animarán'::text,'estarán animando'::text,'Oye, me han dicho que para el final de la sesión habrán animado a cada escalador del gimnasio.'::text),
(350339,38927,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît qu''à la fin de la séance, ils ... chaque grimpeur de la salle.'::text,'auront encouragé'::text,'encourageront'::text,'seront en train d''encourager'::text,'Écoute, il paraît qu''à la fin de la séance, ils auront encouragé chaque grimpeur de la salle.'::text),
(350342,38927,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre antrenmanın sonuna kadar salondaki her bir tırmanıcıyı ...'::text,'cesaretlendirmiş olacaklarmış'::text,'cesaretlendireceklermiş'::text,'cesaretlendiriyor olacaklarmış'::text,'Dinle, duyduğuma göre antrenmanın sonuna kadar salondaki her bir tırmanıcıyı cesaretlendirmiş olacaklarmış.'::text),
(350343,38927,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy az edzés végére a teremben ... minden egyes mászót.'::text,'meg fognak bátorítani'::text,'meg fognak bátorítani'::text,'bátorítani fognak'::text,'Figyelj, azt hallottam, hogy az edzés végére a teremben meg fognak bátorítani minden egyes mászót.'::text),
(350355,38929,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, die Gruppe hat angeblich versprochen, sie ..., bis sie oben ankommt.'::text,'zu ermutigen'::text,'zu ermutigen'::text,'zu ermutigen'::text,'Rate mal, die Gruppe hat angeblich versprochen, sie zu ermutigen, bis sie oben ankommt.'::text),
(350359,38929,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, група нібито пообіцяла ... її, доки вона не долізе до верху.'::text,'підбадьорювати'::text,'підбадьорювати'::text,'підбадьорювати'::text,'Уяви, група нібито пообіцяла підбадьорювати її, доки вона не долізе до верху.'::text),
(350358,38929,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, parece que el grupo prometió ... hasta que llegara arriba.'::text,'animarla'::text,'animarla'::text,'animarla'::text,'Adivina qué, parece que el grupo prometió animarla hasta que llegara arriba.'::text),
(350357,38929,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, le groupe aurait promis de ... jusqu''à ce qu''elle atteigne le sommet.'::text,'l''encourager'::text,'l''encourager'::text,'l''encourager'::text,'Devine quoi, le groupe aurait promis de l''encourager jusqu''à ce qu''elle atteigne le sommet.'::text),
(350360,38929,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, grup güya zirveye ulaşana kadar onu ... söz vermiş.'::text,'cesaretlendirmeye'::text,'cesaretlendirmeye'::text,'cesaretlendirmeye'::text,'Bil bakalım ne oldu, grup güya zirveye ulaşana kadar onu cesaretlendirmeye söz vermiş.'::text),
(350361,38929,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, a csoport állítólag megígérte, hogy ... őt, amíg fel nem ér a csúcsra.'::text,'bátorítja'::text,'bátorítja'::text,'bátorítja'::text,'Képzeld, a csoport állítólag megígérte, hogy bátorítja őt, amíg fel nem ér a csúcsra.'::text),
(350364,38930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wie du kletterst, ... gerade jeden in dieser Halle.'::text,'ermutigt'::text,'ermutigt'::text,'hat ermutigt'::text,'Ehrlich, wie du kletterst, ermutigt gerade jeden in dieser Halle.'::text),
(350368,38930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, те, як ти лазиш, саме зараз ... кожного в цій залі.'::text,'надихає'::text,'надихає'::text,'надихнуло'::text,'Чесно, те, як ти лазиш, саме зараз надихає кожного в цій залі.'::text),
(350367,38930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, tu forma de escalar ... a todo el gimnasio ahora mismo.'::text,'está animando'::text,'anima'::text,'ha animado'::text,'En serio, tu forma de escalar está animando a todo el gimnasio ahora mismo.'::text),
(350366,38930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ta façon de grimper ... tout le monde dans cette salle en ce moment.'::text,'encourage'::text,'encourage'::text,'a encouragé'::text,'Franchement, ta façon de grimper encourage tout le monde dans cette salle en ce moment.'::text),
(350369,38930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, tırmanma şeklin şu an bu salondaki herkesi ...'::text,'cesaretlendiriyor'::text,'cesaretlendirir'::text,'cesaretlendirdi'::text,'Açıkçası, tırmanma şeklin şu an bu salondaki herkesi cesaretlendiriyor.'::text),
(350370,38930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ahogy mászol, most ... mindenkit ebben a teremben.'::text,'bátorít'::text,'bátorít'::text,'bátorított'::text,'Őszintén, ahogy mászol, most bátorít mindenkit ebben a teremben.'::text),
(350373,38931,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, noch bevor du oben warst, ... du die ganze Gruppe ermutigt, diese Wand zu probieren.'::text,'hattest'::text,'hast'::text,'hast'::text,'Mal ehrlich, noch bevor du oben warst, hattest du die ganze Gruppe ermutigt, diese Wand zu probieren.'::text),
(350377,38931,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не збрешу, ще до того, як ти долізла нагору, ти ... всю групу спробувати ту стіну.'::text,'надихнула'::text,'надихнула'::text,'надихаєш'::text,'Не збрешу, ще до того, як ти долізла нагору, ти надихнула всю групу спробувати ту стіну.'::text),
(350376,38931,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, antes de llegar arriba, ya ... a todo el grupo a probar esa pared.'::text,'habías animado'::text,'has animado'::text,'animas'::text,'No te voy a mentir, antes de llegar arriba, ya habías animado a todo el grupo a probar esa pared.'::text),
(350375,38931,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, avant même d''arriver en haut, tu ... tout le groupe à tenter ce mur.'::text,'avais encouragé'::text,'as encouragé'::text,'encourages'::text,'Je vais pas mentir, avant même d''arriver en haut, tu avais encouragé tout le groupe à tenter ce mur.'::text),
(350378,38931,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, daha zirveye varmadan bütün grubu o duvarı denemeye ...'::text,'cesaretlendirmiştin'::text,'cesaretlendirdin'::text,'cesaretlendiriyorsun'::text,'Yalan yok, daha zirveye varmadan bütün grubu o duvarı denemeye cesaretlendirmiştin.'::text),
(350379,38931,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, még mielőtt felértél volna, ... az egész csoportot, hogy kipróbálják azt a falat.'::text,'már felbátorítottad'::text,'felbátorítottad'::text,'bátorítod'::text,'Nem hazudok, még mielőtt felértél volna, már felbátorítottad az egész csoportot, hogy kipróbálják azt a falat.'::text),
(369840,41094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... der Mechaniker das neue Teil am Motor des Motorrollers eingebaut haben.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis heute Abend wird der Mechaniker das neue Teil am Motor des Motorrollers eingebaut haben.'::text),
(369844,41094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора механік ... нову деталь на мотор скутера.'::text,'встановить'::text,'встановить'::text,'встановлює'::text,'До вечора механік встановить нову деталь на мотор скутера.'::text),
(369843,41094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, el mecánico ... la pieza nueva al motor del escúter.'::text,'habrá montado'::text,'montará'::text,'monta'::text,'Para esta noche, el mecánico habrá montado la pieza nueva al motor del escúter.'::text),
(369842,41094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, le mécanicien ... la nouvelle pièce sur le moteur du scooter.'::text,'aura monté'::text,'montera'::text,'monte'::text,'D''ici ce soir, le mécanicien aura monté la nouvelle pièce sur le moteur du scooter.'::text),
(369845,41094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar tamirci yeni parçayı scooter''ın motoruna ...'::text,'takmış olacak'::text,'takacak'::text,'takıyor'::text,'Bu akşama kadar tamirci yeni parçayı scooter''ın motoruna takmış olacak.'::text),
(369846,41094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére a szerelő ... az új alkatrészt a robogó motorjára.'::text,'felszereli'::text,'fel fogja szerelni'::text,'szereli'::text,'Estére a szerelő felszereli az új alkatrészt a robogó motorjára.'::text),
(369849,41095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um sechs Uhr wird er acht Stunden lang am Motor dieses Motorrollers ...'::text,'gearbeitet haben'::text,'arbeiten'::text,'arbeiten'::text,'Um sechs Uhr wird er acht Stunden lang am Motor dieses Motorrollers gearbeitet haben.'::text),
(369853,41095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О шостій він уже ... над мотором цього скутера вісім годин.'::text,'працюватиме'::text,'працюватиме'::text,'працюватиме'::text,'О шостій він уже працюватиме над мотором цього скутера вісім годин.'::text),
(369852,41095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las seis, ... ocho horas trabajando en el motor de este escúter.'::text,'llevará'::text,'estará'::text,'estará'::text,'A las seis, llevará ocho horas trabajando en el motor de este escúter.'::text),
(369851,41095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À six heures, il ... pendant huit heures sur le moteur de ce scooter.'::text,'aura travaillé'::text,'travaillera'::text,'travaillera'::text,'À six heures, il aura travaillé pendant huit heures sur le moteur de ce scooter.'::text),
(369854,41095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat altıya kadar bu scooter motoru üzerinde sekiz saattir ...'::text,'çalışıyor olacak'::text,'çalışıyor olacak'::text,'çalışacak'::text,'Saat altıya kadar bu scooter motoru üzerinde sekiz saattir çalışıyor olacak.'::text),
(369855,41095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hat órára már nyolc órája ... ezen a robogómotoron.'::text,'fog dolgozni'::text,'fog dolgozni'::text,'fog dolgozni'::text,'Hat órára már nyolc órája fog dolgozni ezen a robogómotoron.'::text),
(369858,41096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er den V8-Motor zuerst ausgemessen, ... er sich nicht schockiert an den Kopf gefasst. Perfekte Planung.'::text,'hätte'::text,'wird'::text,'hat'::text,'Hätte er den V8-Motor zuerst ausgemessen, hätte er sich nicht schockiert an den Kopf gefasst. Perfekte Planung.'::text),
(369862,41096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він спершу виміряв той мотор V8, він ... за голову від шоку. Бездоганне планування.'::text,'не схопився б'::text,'не схопиться'::text,'не схопився'::text,'Якби він спершу виміряв той мотор V8, він не схопився б за голову від шоку. Бездоганне планування.'::text),
(369861,41096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera medido primero ese motor V8, ... la cabeza del susto. Planificación impecable.'::text,'no se habría agarrado'::text,'no se agarrará'::text,'no se agarró'::text,'Si hubiera medido primero ese motor V8, no se habría agarrado la cabeza del susto. Planificación impecable.'::text),
(369860,41096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait mesuré ce moteur V8 d''abord, il ... la tête sous le choc. Planification impeccable.'::text,'ne se serait pas pris'::text,'ne se prendra pas'::text,'ne s''est pas pris'::text,'S''il avait mesuré ce moteur V8 d''abord, il ne se serait pas pris la tête sous le choc. Planification impeccable.'::text),
(369863,41096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O V8 motorunu önce ölçseydi, şoktan ellerini başına ..., kusursuz planlama.'::text,'koymazdı'::text,'koymayacak'::text,'koymadı'::text,'O V8 motorunu önce ölçseydi, şoktan ellerini başına koymazdı, kusursuz planlama.'::text),
(369864,41096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha előbb lemérte volna azt a V8-as motort, ... a fejéhez a sokktól. Hibátlan tervezés.'::text,'nem kapott volna'::text,'nem fog kapni'::text,'nem kapott'::text,'Ha előbb lemérte volna azt a V8-as motort, nem kapott volna a fejéhez a sokktól. Hibátlan tervezés.'::text),
(369867,41097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er einen kleineren Motor bestellt, ... er jetzt nicht mit den Händen am Kopf da. Tolle Planung.'::text,'stünde'::text,'stünde'::text,'stünde'::text,'Hätte er einen kleineren Motor bestellt, stünde er jetzt nicht mit den Händen am Kopf da. Tolle Planung.'::text),
(369871,41097,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він замовив менший мотор, він ... зараз там, тримаючись за голову. Чудове планування.'::text,'не стояв би'::text,'не стояв би'::text,'не стоятиме'::text,'Якби він замовив менший мотор, він не стояв би зараз там, тримаючись за голову. Чудове планування.'::text),
(369870,41097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera pedido un motor más pequeño, ahora ... ahí agarrándose la cabeza. Gran planificación.'::text,'no estaría'::text,'no habría estado'::text,'no estará'::text,'Si hubiera pedido un motor más pequeño, ahora no estaría ahí agarrándose la cabeza. Gran planificación.'::text),
(369869,41097,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait commandé un moteur plus petit, il ... là maintenant, la tête entre les mains. Superbe planification.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'S''il avait commandé un moteur plus petit, il ne serait pas là maintenant, la tête entre les mains. Superbe planification.'::text),
(369872,41097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha küçük bir motor sipariş etseydi, şimdi orada başını tutarak ..., harika planlama.'::text,'durmazdı'::text,'durmamış olurdu'::text,'durmayacak'::text,'Daha küçük bir motor sipariş etseydi, şimdi orada başını tutarak durmazdı, harika planlama.'::text),
(369873,41097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kisebb motort rendelt volna, most ... ott a fejét fogva. Remek tervezés.'::text,'nem állna'::text,'nem állt volna'::text,'nem fog állni'::text,'Ha kisebb motort rendelt volna, most nem állna ott a fejét fogva. Remek tervezés.'::text),
(369876,41098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der V8-Motor soll aus einem Rennwagen ..., offensichtlich perfekt für einen Motorroller.'::text,'ausgebaut worden sein'::text,'ausbauen'::text,'ausbauend'::text,'Der V8-Motor soll aus einem Rennwagen ausgebaut worden sein, offensichtlich perfekt für einen Motorroller.'::text),
(369880,41098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що той мотор V8 ... з гоночного авто, очевидно ідеальний для скутера.'::text,'був знятий'::text,'знімає'::text,'знімаючи'::text,'Кажуть, що той мотор V8 був знятий з гоночного авто, очевидно ідеальний для скутера.'::text),
(369879,41098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que ese motor V8 ... de un coche de carreras, obviamente perfecto para un escúter.'::text,'fue sacado'::text,'saca'::text,'sacando'::text,'Se dice que ese motor V8 fue sacado de un coche de carreras, obviamente perfecto para un escúter.'::text),
(369878,41098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que ce moteur V8 ... sur une voiture de course, évidemment parfait pour un scooter.'::text,'a été prélevé'::text,'prélève'::text,'prélevant'::text,'On dit que ce moteur V8 a été prélevé sur une voiture de course, évidemment parfait pour un scooter.'::text),
(369881,41098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O V8 motorunun bir yarış arabasından ... söyleniyor, belli ki scooter için mükemmel.'::text,'alınmış olduğu'::text,'aldığı'::text,'alarak'::text,'O V8 motorunun bir yarış arabasından alınmış olduğu söyleniyor, belli ki scooter için mükemmel.'::text),
(369882,41098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, azt a V8-as motort egy versenyautóból ..., nyilván tökéletes egy robogóhoz.'::text,'szerelték ki'::text,'szereli ki'::text,'kiszerelve'::text,'Azt mondják, azt a V8-as motort egy versenyautóból szerelték ki, nyilván tökéletes egy robogóhoz.'::text),
(369885,41099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, den falschen Motor ..., und jetzt ist sein ganzes Wochenende ruiniert!'::text,'bestellt zu haben'::text,'zu bestellen'::text,'bestellt'::text,'Er gab zu, den falschen Motor bestellt zu haben, und jetzt ist sein ganzes Wochenende ruiniert!'::text),
(369889,41099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зізнався, що ... не той мотор, і тепер усі його вихідні зіпсовані!'::text,'замовив'::text,'замовить'::text,'замовив'::text,'Він зізнався, що замовив не той мотор, і тепер усі його вихідні зіпсовані!'::text),
(369888,41099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Admitió ... el motor equivocado, y ahora tiene todo el fin de semana arruinado!'::text,'haber pedido'::text,'pedir'::text,'pidió'::text,'¡Admitió haber pedido el motor equivocado, y ahora tiene todo el fin de semana arruinado!'::text),
(369887,41099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a avoué ... le mauvais moteur, et maintenant tout son week-end est fichu !'::text,'avoir commandé'::text,'commander'::text,'commandé'::text,'Il a avoué avoir commandé le mauvais moteur, et maintenant tout son week-end est fichu !'::text),
(369890,41099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanlış motoru ... itiraf etti ve şimdi bütün hafta sonu mahvoldu!'::text,'sipariş ettiğini'::text,'sipariş etmeyi'::text,'sipariş etti'::text,'Yanlış motoru sipariş ettiğini itiraf etti ve şimdi bütün hafta sonu mahvoldu!'::text),
(369891,41099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy ... a rossz motort, és most az egész hétvégéje tönkrement!'::text,'megrendelte'::text,'megrendeli'::text,'megrendelte'::text,'Beismerte, hogy megrendelte a rossz motort, és most az egész hétvégéje tönkrement!'::text),
(369894,41100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hätte diesen Monstermotor nicht ..., ohne seine Garage auszumessen! Was für eine Katastrophe!'::text,'kaufen sollen'::text,'kaufen dürfen'::text,'kaufen können'::text,'Er hätte diesen Monstermotor nicht kaufen sollen, ohne seine Garage auszumessen! Was für eine Katastrophe!'::text),
(369898,41100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... той монстр-мотор, не вимірявши гараж! Яка катастрофа!'::text,'не мав купувати'::text,'не мусив купувати'::text,'не міг купити'::text,'Він не мав купувати той монстр-мотор, не вимірявши гараж! Яка катастрофа!'::text),
(369897,41100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... ese motor monstruoso sin medir su garaje! ¡Qué desastre!'::text,'no debería haber comprado'::text,'no debe de haber comprado'::text,'no pudo comprar'::text,'¡Él no debería haber comprado ese motor monstruoso sin medir su garaje! ¡Qué desastre!'::text),
(369896,41100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... ce moteur monstre sans mesurer son garage ! Quelle catastrophe !'::text,'n''aurait pas dû acheter'::text,'n''a pas dû acheter'::text,'n''a pas pu acheter'::text,'Il n''aurait pas dû acheter ce moteur monstre sans mesurer son garage ! Quelle catastrophe !'::text),
(369899,41100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Garajını ölçmeden o canavar motoru ...! Ne felaket!'::text,'almamalıydı'::text,'almamış olmalı'::text,'alamadı'::text,'Garajını ölçmeden o canavar motoru almamalıydı! Ne felaket!'::text),
(369900,41100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki ... azt a szörnymotort a garázsa lemérése nélkül! Micsoda katasztrófa!'::text,'nem kellett volna megvennie'::text,'nem vehette meg'::text,'nem tudta megvenni'::text,'Neki nem kellett volna megvennie azt a szörnymotort a garázsa lemérése nélkül! Micsoda katasztrófa!'::text),
(369903,41101,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... einen so großen Motor wie diesen V8 gesehen.'::text,'hat er'::text,'er hat'::text,'hat er'::text,'Noch nie hat er einen so großen Motor wie diesen V8 gesehen.'::text),
(369907,41101,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи раніше ... такого великого мотора, як цей V8.'::text,'він не бачив'::text,'він не бачив'::text,'він не бачив'::text,'Ніколи раніше він не бачив такого великого мотора, як цей V8.'::text),
(369906,41101,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca antes ... un motor tan grande como este V8.'::text,'ha visto'::text,'ha visto'::text,'vio'::text,'Nunca antes ha visto un motor tan grande como este V8.'::text),
(369905,41101,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais auparavant ... vu un moteur aussi gros que ce V8.'::text,'n''a-t-il'::text,'il n''a'::text,'n''a-t-il'::text,'Jamais auparavant n''a-t-il vu un moteur aussi gros que ce V8.'::text),
(369908,41101,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha önce hiç bu V8 kadar büyük bir motor ...'::text,'görmemişti'::text,'görmemişti'::text,'görmemişti'::text,'Daha önce hiç bu V8 kadar büyük bir motor görmemişti.'::text),
(369909,41101,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még soha ... ilyen nagy motort, mint ez a V8.'::text,'nem látott'::text,'nem látott'::text,'nem látott'::text,'Még soha nem látott ilyen nagy motort, mint ez a V8.'::text),
(369921,41103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er wünscht sich, der V8-Motor ... ein bisschen kleiner, ist echt irre.'::text,'wäre'::text,'ist'::text,'wird'::text,'Digga, er wünscht sich, der V8-Motor wäre ein bisschen kleiner, ist echt irre.'::text),
(369925,41103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він хотів би, щоб той мотор V8 ... трохи менший, це реально божевілля.'::text,'був'::text,'є'::text,'буде'::text,'Бро, він хотів би, щоб той мотор V8 був трохи менший, це реально божевілля.'::text),
(369924,41103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él desearía que ese motor V8 ... un poco más pequeño, es una locura total.'::text,'fuera'::text,'es'::text,'será'::text,'Bro, él desearía que ese motor V8 fuera un poco más pequeño, es una locura total.'::text),
(369923,41103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il aimerait que ce moteur V8 ... un peu plus petit, c''est carrément dingue.'::text,'soit'::text,'est'::text,'sera'::text,'Frère, il aimerait que ce moteur V8 soit un peu plus petit, c''est carrément dingue.'::text),
(369926,41103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke o V8 motor biraz daha küçük ... diyor, cidden çılgınca.'::text,'olsa'::text,NULL::text,'olacak'::text,'Kanka, keşke o V8 motor biraz daha küçük olsa diyor, cidden çılgınca.'::text),
(369927,41103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt szeretné, ha az a V8-as motor egy kicsit kisebb ..., elég őrület.'::text,'lenne'::text,NULL::text,'lesz'::text,'Tesó, azt szeretné, ha az a V8-as motor egy kicsit kisebb lenne, elég őrület.'::text),
(369930,41104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der V8-Motor, ... Chromdeckel in der Sonne glänzt, steht auf einem schwarzen Stahlgestell.'::text,'dessen'::text,'der'::text,'der'::text,'Der V8-Motor, dessen Chromdeckel in der Sonne glänzt, steht auf einem schwarzen Stahlgestell.'::text),
(369934,41104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мотор V8, ... хромований верх блищить на сонці, стоїть на чорній сталевій підставці.'::text,'чий'::text,'який'::text,'що'::text,'Мотор V8, чий хромований верх блищить на сонці, стоїть на чорній сталевій підставці.'::text),
(369933,41104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El motor V8, ... tapa cromada brilla al sol, está sobre un soporte de acero negro.'::text,'cuya'::text,'que'::text,'que'::text,'El motor V8, cuya tapa cromada brilla al sol, está sobre un soporte de acero negro.'::text),
(369932,41104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le moteur V8, ... le dessus chromé brille au soleil, repose sur un support en acier noir.'::text,'dont'::text,'qui'::text,'que'::text,'Le moteur V8, dont le dessus chromé brille au soleil, repose sur un support en acier noir.'::text),
(369935,41104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... krom kapağı güneşte parlayan V8 motor, siyah çelik bir sehpanın üzerinde duruyor.'::text,''::text,NULL::text,NULL::text,'Krom kapağı güneşte parlayan V8 motor, siyah çelik bir sehpanın üzerinde duruyor.'::text),
(369936,41104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A V8-as motor, ... krómozott teteje csillog a napon, egy fekete acélállványon áll.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A V8-as motor, amelynek a krómozott teteje csillog a napon, egy fekete acélállványon áll.'::text),
(381648,42406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, angeblich ... er seit drei Wochen an dem Roboter, nur um einen Becher zu bekommen.'::text,'arbeitet'::text,'arbeitet'::text,'arbeitet'::text,'Also, angeblich arbeitet er seit drei Wochen an dem Roboter, nur um einen Becher zu bekommen.'::text),
(381652,42406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, він ... над тим роботом три тижні, аби просто отримати кухоль.'::text,'працює'::text,'працює'::text,'працює'::text,'Отже, кажуть, він працює над тим роботом три тижні, аби просто отримати кухоль.'::text),
(381651,42406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ver, parece que ... tres semanas trabajando en ese robot solo para conseguir una taza.'::text,'lleva'::text,'está'::text,'está'::text,'A ver, parece que lleva tres semanas trabajando en ese robot solo para conseguir una taza.'::text),
(381650,42406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment il ... sur ce robot depuis trois semaines juste pour avoir un mug.'::text,'travaille'::text,'travaille'::text,'travaille'::text,'Bon, apparemment il travaille sur ce robot depuis trois semaines juste pour avoir un mug.'::text),
(381653,42406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, güya üç haftadır o robot üzerinde ..., sırf bir kupa almak için.'::text,'çalışıyormuş'::text,'çalışıyor'::text,'çalışır'::text,'Tamam, güya üç haftadır o robot üzerinde çalışıyormuş, sırf bir kupa almak için.'::text),
(381654,42406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag három hete ... azon a roboton, csak hogy kapjon egy bögrét.'::text,'dolgozik'::text,'dolgozik'::text,'dolgozik'::text,'Szóval állítólag három hete dolgozik azon a roboton, csak hogy kapjon egy bögrét.'::text),
(381657,42407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... so ruhig, als sich dein Roboter plötzlich mit dem Becher umdrehte. Lässig.'::text,'tipptest'::text,'tipptest'::text,'hast getippt'::text,'Du tipptest so ruhig, als sich dein Roboter plötzlich mit dem Becher umdrehte. Lässig.'::text),
(381661,42407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... так спокійно, коли твій робот раптом розвернувся з кухлем. Стильно.'::text,'друкував'::text,'надрукував'::text,'надрукував'::text,'Ти друкував так спокійно, коли твій робот раптом розвернувся з кухлем. Стильно.'::text),
(381660,42407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... con tanta calma cuando tu robot se giró de repente con la taza. Con estilo.'::text,'estabas escribiendo'::text,'escribiste'::text,'has escrito'::text,'Tú estabas escribiendo con tanta calma cuando tu robot se giró de repente con la taza. Con estilo.'::text),
(381659,42407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... si calmement quand ton robot s''est soudain retourné avec le mug. Classe.'::text,'tapais'::text,'as tapé'::text,'as tapé'::text,'Tu tapais si calmement quand ton robot s''est soudain retourné avec le mug. Classe.'::text),
(381662,42407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Robotun aniden kupayla döndüğünde sen o kadar sakin ..., çok havalı.'::text,'yazıyordun'::text,'yazdın'::text,'yazdın'::text,'Robotun aniden kupayla döndüğünde sen o kadar sakin yazıyordun, çok havalı.'::text),
(381663,42407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te olyan nyugodtan ..., amikor a robotod hirtelen megfordult a bögrével. Menő.'::text,'gépeltél'::text,'gépeltél'::text,'gépeltél'::text,'Te olyan nyugodtan gépeltél, amikor a robotod hirtelen megfordult a bögrével. Menő.'::text),
(381666,42408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch: Dein Roboter ... dir einen Becher gereicht, und jetzt kannst du endlich trinken.'::text,'hat'::text,'hat'::text,'reicht'::text,'Irgendwie ikonisch: Dein Roboter hat dir einen Becher gereicht, und jetzt kannst du endlich trinken.'::text),
(381670,42408,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить культово: твій робот ... тобі кухоль, і тепер ти нарешті можеш попити.'::text,'подав'::text,'подавав'::text,'подає'::text,'Досить культово: твій робот подав тобі кухоль, і тепер ти нарешті можеш попити.'::text),
(381669,42408,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante icónico: tu robot te ... una taza y por fin puedes beber.'::text,'ha pasado'::text,'ha estado pasando'::text,'pasa'::text,'Bastante icónico: tu robot te ha pasado una taza y por fin puedes beber.'::text),
(381668,42408,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Assez iconique : ton robot ... un mug, et maintenant tu peux enfin boire.'::text,'t''a tendu'::text,'t''a tendu'::text,'te tend'::text,'Assez iconique : ton robot t''a tendu un mug, et maintenant tu peux enfin boire.'::text),
