(381690,42410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a robot ilyen simán ... minden bögrét, soha többé senki sem fog kávét főzni. Semmi különös.'::text,'adja oda'::text,'oda fogja adni'::text,'adta oda'::text,'Ha ez a robot ilyen simán adja oda minden bögrét, soha többé senki sem fog kávét főzni. Semmi különös.'::text),
(381693,42411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn ich so einen Roboter hätte, ... ich nie wieder für Kaffee auf, kein Witz.'::text,'stünde'::text,'stehe'::text,'stehe'::text,'Digga, wenn ich so einen Roboter hätte, stünde ich nie wieder für Kaffee auf, kein Witz.'::text),
