(381734,42415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siyah bir kıskaç ... taktığı robot kol ona bir kupa uzattı.'::text,''::text,NULL::text,NULL::text,'Siyah bir kıskaç taktığı robot kol ona bir kupa uzattı.'::text),
(381735,42415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A robotkar, ... fekete markolót szerelt, odaadott neki egy bögrét.'::text,'amelyre'::text,'aki'::text,'ahol'::text,'A robotkar, amelyre fekete markolót szerelt, odaadott neki egy bögrét.'::text),
(350778,38976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Bauer die Futtersäcke ..., haute die Ziege ab. Perfekte Sicherheit.'::text,'zählte'::text,'zählte'::text,'gezählt hat'::text,'Während der Bauer die Futtersäcke zählte, haute die Ziege ab. Perfekte Sicherheit.'::text),
(350782,38976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки фермер ... мішки з кормом, коза втекла. Бездоганна охорона.'::text,'рахував'::text,'порахував'::text,'порахував'::text,'Поки фермер рахував мішки з кормом, коза втекла. Бездоганна охорона.'::text),
(350781,38976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el granjero ... los sacos de pienso, la cabra se escapó. Seguridad impecable.'::text,'estaba contando'::text,'contó'::text,'ha contado'::text,'Mientras el granjero estaba contando los sacos de pienso, la cabra se escapó. Seguridad impecable.'::text),
(350780,38976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le fermier ... les sacs de fourrage, la chèvre s''est échappée. Sécurité impeccable.'::text,'comptait'::text,'a compté'::text,'a compté'::text,'Pendant que le fermier comptait les sacs de fourrage, la chèvre s''est échappée. Sécurité impeccable.'::text),
(350783,38976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiftçi yem çuvallarını ..., keçi kaçtı. Kusursuz güvenlik.'::text,'sayarken'::text,'saydığında'::text,'saymışken'::text,'Çiftçi yem çuvallarını sayarken, keçi kaçtı. Kusursuz güvenlik.'::text),
(350784,38976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a gazda ... a takarmányzsákokat, a kecske megszökött. Hibátlan biztonság.'::text,'számolta'::text,'megszámolta'::text,'megszámolta'::text,'Miközben a gazda számolta a takarmányzsákokat, a kecske megszökött. Hibátlan biztonság.'::text),
(350796,38978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, während der Bauer seinen Hut ..., ist die Ziege abgehauen, echt.'::text,'zurechtrückte'::text,'zurechtrückte'::text,'zurechtgerückt hat'::text,'Digga, während der Bauer seinen Hut zurechtrückte, ist die Ziege abgehauen, echt.'::text),
(350800,38978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки фермер ... свого капелюха, коза змилася, реально.'::text,'поправляв'::text,'поправив'::text,'поправив'::text,'Бро, поки фермер поправляв свого капелюха, коза змилася, реально.'::text),
(350799,38978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mientras el granjero se ... el sombrero, la cabra se piró, en serio.'::text,'estaba colocando'::text,'colocó'::text,'ha colocado'::text,'Bro, mientras el granjero se estaba colocando el sombrero, la cabra se piró, en serio.'::text),
(350798,38978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, pendant que le fermier ... son chapeau, la chèvre s''est tirée, grave.'::text,'réajustait'::text,'a réajusté'::text,'a réajusté'::text,'Frère, pendant que le fermier réajustait son chapeau, la chèvre s''est tirée, grave.'::text),
(350801,38978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çiftçi şapkasını ..., keçi kaçıp gitti, cidden.'::text,'düzeltirken'::text,'düzelttiğinde'::text,'düzeltmişken'::text,'Kanka, çiftçi şapkasını düzeltirken, keçi kaçıp gitti, cidden.'::text),
(350802,38978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, miközben a gazda ... a kalapját, a kecske meglógott, komolyan.'::text,'igazgatta'::text,'megigazította'::text,'megigazította'::text,'Tesó, miközben a gazda igazgatta a kalapját, a kecske meglógott, komolyan.'::text),
(350805,38979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut Vorfallbericht ... diese Ziege bisher 3-mal aus dem Gehege ausgebrochen.'::text,'ist'::text,'ist'::text,'brach'::text,'Laut Vorfallbericht ist diese Ziege bisher 3-mal aus dem Gehege ausgebrochen.'::text),
(350809,38979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Згідно зі звітом про інцидент, ця коза ... із загону вже 3 рази.'::text,'тікала'::text,'тікала'::text,'втекла'::text,'Згідно зі звітом про інцидент, ця коза тікала із загону вже 3 рази.'::text),
(350808,38979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según el informe del incidente, esta cabra ... del corral 3 veces hasta ahora.'::text,'se ha escapado'::text,'se ha estado escapando'::text,'se escapó'::text,'Según el informe del incidente, esta cabra se ha escapado del corral 3 veces hasta ahora.'::text),
(350807,38979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''après le rapport d''incident, cette chèvre ... de l''enclos 3 fois jusqu''ici.'::text,'s''est échappée'::text,'s''est échappée'::text,'s''échappa'::text,'D''après le rapport d''incident, cette chèvre s''est échappée de l''enclos 3 fois jusqu''ici.'::text),
(350810,38979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olay raporuna göre bu keçi şimdiye kadar ağıldan 3 kez ...'::text,'kaçtı'::text,'kaçıp duruyor'::text,'kaçtı'::text,'Olay raporuna göre bu keçi şimdiye kadar ağıldan 3 kez kaçtı.'::text),
(350811,38979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az incidensjelentés szerint ez a kecske eddig 3-szor ... meg a karámból.'::text,'szökött'::text,'szökdösött'::text,'szökött'::text,'Az incidensjelentés szerint ez a kecske eddig 3-szor szökött meg a karámból.'::text),
(350814,38980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bauer griff daneben, weil die Ziege aus dem Gehege ..., also war die Ziege nicht da.'::text,'ausgebrochen war'::text,'ausgebrochen ist'::text,'ausbricht'::text,'Der Bauer griff daneben, weil die Ziege aus dem Gehege ausgebrochen war, also war die Ziege nicht da.'::text),
(350818,38980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фермер схибив, бо коза вже ... із загону, тож кози там не було.'::text,'втекла'::text,'втекла'::text,'тікає'::text,'Фермер схибив, бо коза вже втекла із загону, тож кози там не було.'::text),
(350817,38980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El granjero falló porque la cabra ... del corral, así que la cabra no estaba allí.'::text,'se había escapado'::text,'se ha escapado'::text,'se escapa'::text,'El granjero falló porque la cabra se había escapado del corral, así que la cabra no estaba allí.'::text),
(350816,38980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fermier l''a ratée parce que la chèvre ... de l''enclos, donc la chèvre n''était pas là.'::text,'s''était échappée'::text,'s''est échappée'::text,'s''échappe'::text,'Le fermier l''a ratée parce que la chèvre s''était échappée de l''enclos, donc la chèvre n''était pas là.'::text),
(350819,38980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiftçi ıskaladı çünkü keçi ağıldan ..., yani keçi orada değildi.'::text,'kaçmıştı'::text,'kaçtı'::text,'kaçıyor'::text,'Çiftçi ıskaladı çünkü keçi ağıldan kaçmıştı, yani keçi orada değildi.'::text),
(350820,38980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gazda mellényúlt, mert a kecske már ... a karámból, így a kecske nem volt ott.'::text,'megszökött'::text,'megszökött'::text,'megszökik'::text,'A gazda mellényúlt, mert a kecske már megszökött a karámból, így a kecske nem volt ott.'::text),
(350823,38981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Exemplar ... zwischen den Brettern entkommen sein, da der Riegel geschlossen bleibt.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Das Exemplar muss zwischen den Brettern entkommen sein, da der Riegel geschlossen bleibt.'::text),
(350827,38981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Особина ... між дошками, оскільки засув залишається зачиненим.'::text,'мусила втекти'::text,'не могла втекти'::text,'мала втекти'::text,'Особина мусила втекти між дошками, оскільки засув залишається зачиненим.'::text),
(350826,38981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ejemplar ... entre las tablas, ya que el pestillo sigue cerrado.'::text,'debió de escaparse'::text,'no pudo escaparse'::text,'debería haberse escapado'::text,'El ejemplar debió de escaparse entre las tablas, ya que el pestillo sigue cerrado.'::text),
(350825,38981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le spécimen ... entre les planches, puisque le loquet reste fermé.'::text,'a dû s''échapper'::text,'n''a pas pu s''échapper'::text,'aurait dû s''échapper'::text,'Le spécimen a dû s''échapper entre les planches, puisque le loquet reste fermé.'::text),
(350828,38981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mandal kapalı kaldığına göre, örnek tahtaların arasından ...'::text,'kaçmış olmalı'::text,'kaçmış olamaz'::text,'kaçmalıydı'::text,'Mandal kapalı kaldığına göre, örnek tahtaların arasından kaçmış olmalı.'::text),
(350829,38981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A példány ... a deszkák között szökött meg, mivel a retesz zárva maradt.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'A példány biztosan a deszkák között szökött meg, mivel a retesz zárva maradt.'::text),
(350832,38982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach dem Ausbruch ließ der Bauer das Tor mit stabileren Brettern ...'::text,'reparieren'::text,'reparieren'::text,'reparieren'::text,'Nach dem Ausbruch ließ der Bauer das Tor mit stabileren Brettern reparieren.'::text),
(350836,38982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після втечі фермер доручив ... ворота міцнішими дошками.'::text,'полагодити'::text,'полагодити'::text,'полагодити'::text,'Після втечі фермер доручив полагодити ворота міцнішими дошками.'::text),
(350835,38982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tras la fuga, el granjero mandó ... la puerta con tablas más resistentes.'::text,'reparar'::text,'reparar'::text,'reparar'::text,'Tras la fuga, el granjero mandó reparar la puerta con tablas más resistentes.'::text),
(350834,38982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après l''évasion, le fermier a fait ... la porte avec des planches plus solides.'::text,'réparer'::text,'réparer'::text,'réparer'::text,'Après l''évasion, le fermier a fait réparer la porte avec des planches plus solides.'::text),
(350837,38982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaçıştan sonra çiftçi kapıyı daha sağlam tahtalarla ...'::text,'tamir ettirdi'::text,'tamir ettirdi'::text,'tamir ettirdi'::text,'Kaçıştan sonra çiftçi kapıyı daha sağlam tahtalarla tamir ettirdi.'::text),
(350838,38982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szökés után a gazda erősebb deszkákkal ... a kaput.'::text,'javíttatta meg'::text,'javíttatta meg'::text,'javíttatta meg'::text,'A szökés után a gazda erősebb deszkákkal javíttatta meg a kaput.'::text),
(350850,38984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ziege, ... Hörner kurz stecken blieben, entkam trotzdem durch das Tor.'::text,'deren'::text,'die'::text,'die'::text,'Die Ziege, deren Hörner kurz stecken blieben, entkam trotzdem durch das Tor.'::text),
(350854,38984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коза, ... роги на мить застрягли, все одно втекла крізь ворота.'::text,'чиї'::text,'яка'::text,'яка'::text,'Коза, чиї роги на мить застрягли, все одно втекла крізь ворота.'::text),
(350853,38984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cabra, ... cuernos se atascaron un momento, aun así se escapó por la puerta.'::text,'cuyos'::text,'que'::text,'que'::text,'La cabra, cuyos cuernos se atascaron un momento, aun así se escapó por la puerta.'::text),
(350852,38984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chèvre, ... les cornes sont restées coincées un instant, s''est quand même échappée par la porte.'::text,'dont'::text,'qui'::text,'qui'::text,'La chèvre, dont les cornes sont restées coincées un instant, s''est quand même échappée par la porte.'::text),
(350855,38984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir an ... boynuzları sıkışan keçi yine de kapıdan kaçtı.'::text,''::text,NULL::text,NULL::text,'Bir an boynuzları sıkışan keçi yine de kapıdan kaçtı.'::text),
(350856,38984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kecske, ... szarva egy pillanatra beszorult, mégis megszökött a kapun át.'::text,'amelynek a'::text,'amely'::text,'aki'::text,'A kecske, amelynek a szarva egy pillanatra beszorult, mégis megszökött a kapun át.'::text),
(350859,38985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ziege entkam ... des Versuchs des Bauern, sie zu packen.'::text,'trotz'::text,'obwohl'::text,'trotz'::text,'Die Ziege entkam trotz des Versuchs des Bauern, sie zu packen.'::text),
(350863,38985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коза втекла ... спробу фермера її схопити.'::text,'попри'::text,'хоча'::text,'попри'::text,'Коза втекла попри спробу фермера її схопити.'::text),
(350862,38985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cabra se escapó ... el intento del granjero de agarrarla.'::text,'a pesar de'::text,'aunque'::text,'a pesar de'::text,'La cabra se escapó a pesar de el intento del granjero de agarrarla.'::text),
(350861,38985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chèvre s''est échappée ... la tentative du fermier de l''attraper.'::text,'malgré'::text,'bien que'::text,'malgré'::text,'La chèvre s''est échappée malgré la tentative du fermier de l''attraper.'::text),
(350864,38985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keçi, çiftçinin onu yakalama girişimine ... kaçtı.'::text,'rağmen'::text,'rağmen'::text,'rağmen'::text,'Keçi, çiftçinin onu yakalama girişimine rağmen kaçtı.'::text),
(350865,38985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kecske megszökött, a gazda próbálkozása ..., hogy elkapja.'::text,'ellenére'::text,'bár'::text,'ellenére'::text,'A kecske megszökött, a gazda próbálkozása ellenére, hogy elkapja.'::text),
(350868,38986,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... die Ziege noch dreimal ausgebrochen sein. Perfektes Tor.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Sonnenuntergang wird die Ziege noch dreimal ausgebrochen sein. Perfektes Tor.'::text),
(350872,38986,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця коза ... ще тричі. Бездоганні ворота.'::text,'втече'::text,'втече'::text,'тікає'::text,'До заходу сонця коза втече ще тричі. Бездоганні ворота.'::text),
(350871,38986,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, la cabra ... tres veces más. Puerta impecable.'::text,'se habrá escapado'::text,'se escapará'::text,'se escapa'::text,'Para el atardecer, la cabra se habrá escapado tres veces más. Puerta impecable.'::text),
(350870,38986,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, la chèvre ... encore trois fois. Porte impeccable.'::text,'se sera échappée'::text,'s''échappera'::text,'s''échappe'::text,'D''ici le coucher du soleil, la chèvre se sera échappée encore trois fois. Porte impeccable.'::text),
(350873,38986,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar keçi üç kez daha ..., kusursuz kapı.'::text,'kaçmış olacak'::text,'kaçacak'::text,'kaçıyor'::text,'Gün batımına kadar keçi üç kez daha kaçmış olacak, kusursuz kapı.'::text),
(350874,38986,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtáig a kecske ... még háromszor. Hibátlan kapu.'::text,'megszökik'::text,'meg fog szökni'::text,'szökik'::text,'Napnyugtáig a kecske megszökik még háromszor. Hibátlan kapu.'::text),
(378471,42053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er ... gerade die Flagge am Mast hoch, als die Trommler ziemlich durchdrehten.'::text,'zog'::text,'zog'::text,'zog'::text,'Digga, er zog gerade die Flagge am Mast hoch, als die Trommler ziemlich durchdrehten.'::text),
(378475,42053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... прапор на щоглу, коли барабанщики трохи пішли в рознос.'::text,'піднімав'::text,'підняв'::text,'підняв'::text,'Бро, він піднімав прапор на щоглу, коли барабанщики трохи пішли в рознос.'::text),
(378474,42053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... la bandera por el mástil cuando los tamborileros se volvieron un poco locos.'::text,'estaba izando'::text,'izó'::text,'ha izado'::text,'Bro, él estaba izando la bandera por el mástil cuando los tamborileros se volvieron un poco locos.'::text),
(378473,42053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... le drapeau au mât quand les batteurs se sont un peu déchaînés.'::text,'hissait'::text,'a hissé'::text,'a hissé'::text,'Frère, il hissait le drapeau au mât quand les batteurs se sont un peu déchaînés.'::text),
(378476,42053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, davulcular baya çıldırdığında o bayrağı direğe ...'::text,'çekiyordu'::text,'çekti'::text,'çekti'::text,'Kanka, davulcular baya çıldırdığında o bayrağı direğe çekiyordu.'::text),
(378477,42053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp ... a zászlót a rúdra, amikor a dobosok eléggé bekattantak.'::text,'húzta fel'::text,'felhúzta'::text,'felhúzta'::text,'Tesó, épp húzta fel a zászlót a rúdra, amikor a dobosok eléggé bekattantak.'::text),
(378480,42054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit 10 Minuten die grüne Flagge, und die Stakeholder klatschen immer noch.'::text,'hisst'::text,'hisst'::text,'hisst'::text,'Er hisst seit 10 Minuten die grüne Flagge, und die Stakeholder klatschen immer noch.'::text),
(378484,42054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... зелений прапор уже 10 хвилин, а стейкхолдери досі аплодують.'::text,'піднімає'::text,'піднімає'::text,'піднімає'::text,'Він піднімає зелений прапор уже 10 хвилин, а стейкхолдери досі аплодують.'::text),
(378483,42054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la bandera verde durante 10 minutos, y los stakeholders siguen aplaudiendo.'::text,'ha estado izando'::text,'está izando'::text,'iza'::text,'Él ha estado izando la bandera verde durante 10 minutos, y los stakeholders siguen aplaudiendo.'::text),
(378482,42054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le drapeau vert depuis 10 minutes, et les parties prenantes applaudissent encore.'::text,'hisse'::text,'hisse'::text,'hisse'::text,'Il hisse le drapeau vert depuis 10 minutes, et les parties prenantes applaudissent encore.'::text),
(378485,42054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'10 dakikadır yeşil bayrağı ... ve paydaşlar hâlâ alkışlıyor.'::text,'çekiyor'::text,'çekiyor'::text,'çeker'::text,'10 dakikadır yeşil bayrağı çekiyor ve paydaşlar hâlâ alkışlıyor.'::text),
(378486,42054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már 10 perce ... a zöld zászlót, és az érintettek még mindig tapsolnak.'::text,'húzza fel'::text,'húzza fel'::text,'húzza fel'::text,'Már 10 perce húzza fel a zöld zászlót, és az érintettek még mindig tapsolnak.'::text),
(378489,42055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Flagge am Mast hoch, also ging die Flagge nach oben.'::text,'zog'::text,'zog'::text,'zieht'::text,'Er zog die Flagge am Mast hoch, also ging die Flagge nach oben.'::text),
(378493,42055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... прапор на щоглу, тож прапор піднявся.'::text,'підняв'::text,'піднімав'::text,'піднімає'::text,'Він підняв прапор на щоглу, тож прапор піднявся.'::text),
(378492,42055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la bandera por el mástil, así que la bandera subió.'::text,'izó'::text,'estaba izando'::text,'iza'::text,'Él izó la bandera por el mástil, así que la bandera subió.'::text),
(378491,42055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le drapeau en haut du mât, donc le drapeau est monté.'::text,'a hissé'::text,'hissait'::text,'hisse'::text,'Il a hissé le drapeau en haut du mât, donc le drapeau est monté.'::text),
(378494,42055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bayrağı direğe ..., yani bayrak yukarı çıktı.'::text,'çekti'::text,'çekiyordu'::text,'çeker'::text,'Bayrağı direğe çekti, yani bayrak yukarı çıktı.'::text),
(378495,42055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a zászlót a rúdra, így a zászló fölment.'::text,'felhúzta'::text,'húzta'::text,'felhúzza'::text,'Ő felhúzta a zászlót a rúdra, így a zászló fölment.'::text),
(378498,42056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte ... die Flagge gehisst, und der Prozess der Gebäudeeröffnung ist nun abgeschlossen.'::text,'hat'::text,'hat'::text,'hisst'::text,'Der Beamte hat die Flagge gehisst, und der Prozess der Gebäudeeröffnung ist nun abgeschlossen.'::text),
(378502,42056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Посадовець ... прапор, і процес відкриття будівлі тепер завершено.'::text,'підняв'::text,'піднімав'::text,'піднімає'::text,'Посадовець підняв прапор, і процес відкриття будівлі тепер завершено.'::text),
(378501,42056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El funcionario ... la bandera, y el proceso de inauguración del edificio ha concluido.'::text,'ha izado'::text,'ha estado izando'::text,'iza'::text,'El funcionario ha izado la bandera, y el proceso de inauguración del edificio ha concluido.'::text),
(378500,42056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le responsable ... le drapeau, et la procédure d''inauguration du bâtiment est désormais terminée.'::text,'a hissé'::text,'hisse'::text,'hisse'::text,'Le responsable a hissé le drapeau, et la procédure d''inauguration du bâtiment est désormais terminée.'::text),
(378503,42056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetkili bayrağı ... ve binanın açılış süreci artık tamamlandı.'::text,'çekti'::text,'çekiyordu'::text,'çeker'::text,'Yetkili bayrağı çekti ve binanın açılış süreci artık tamamlandı.'::text),
(378504,42056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tisztviselő ... a zászlót, és az épület megnyitásának folyamata most lezárult.'::text,'felvonta'::text,'vonta'::text,'felvonja'::text,'A tisztviselő felvonta a zászlót, és az épület megnyitásának folyamata most lezárult.'::text),
(378507,42057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Trommler aufhörten, ... er die Flagge schon ganz nach oben gezogen! Absolut legendär!'::text,'hatte'::text,'hat'::text,'zieht'::text,'Als die Trommler aufhörten, hatte er die Flagge schon ganz nach oben gezogen! Absolut legendär!'::text),
(378511,42057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли барабанщики замовкли, він уже ... прапор на саму верхівку! Абсолютно легендарно!'::text,'підняв'::text,'підняв'::text,'піднімає'::text,'Коли барабанщики замовкли, він уже підняв прапор на саму верхівку! Абсолютно легендарно!'::text),
(378510,42057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando los tamborileros pararon, él ya ... la bandera hasta arriba del todo! ¡Absolutamente legendario!'::text,'había izado'::text,'ha izado'::text,'iza'::text,'¡Para cuando los tamborileros pararon, él ya había izado la bandera hasta arriba del todo! ¡Absolutamente legendario!'::text),
(378509,42057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les batteurs se sont arrêtés, il ... déjà le drapeau tout en haut ! Absolument légendaire !'::text,'avait hissé'::text,'a hissé'::text,'hisse'::text,'Quand les batteurs se sont arrêtés, il avait hissé déjà le drapeau tout en haut ! Absolument légendaire !'::text),
(378512,42057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Davulcular durduğunda bayrağı çoktan en tepeye ...! Tamamen efsane!'::text,'çekmişti'::text,'çekti'::text,'çekiyor'::text,'Davulcular durduğunda bayrağı çoktan en tepeye çekmişti! Tamamen efsane!'::text),
(378513,42057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a dobosok abbahagyták, ő már ... a zászlót egészen a csúcsig! Abszolút legendás!'::text,'felhúzta'::text,'felhúzta'::text,'húzza'::text,'Mire a dobosok abbahagyták, ő már felhúzta a zászlót egészen a csúcsig! Abszolút legendás!'::text),
(378525,42059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hisste die Flagge ... des starken Windes, der sie ständig zur Seite zog.'::text,'trotz'::text,'obwohl'::text,'weil'::text,'Er hisste die Flagge trotz des starken Windes, der sie ständig zur Seite zog.'::text),
(378529,42059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він підняв прапор ... сильний вітер, який постійно тягнув його вбік.'::text,'попри'::text,'хоча'::text,'бо'::text,'Він підняв прапор попри сильний вітер, який постійно тягнув його вбік.'::text),
(378528,42059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Izó la bandera ... el fuerte viento, que no dejaba de empujarla hacia un lado.'::text,'a pesar de'::text,'aunque'::text,'porque'::text,'Izó la bandera a pesar de el fuerte viento, que no dejaba de empujarla hacia un lado.'::text),
(378527,42059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a hissé le drapeau ... le vent fort, qui n''arrêtait pas de le tirer sur le côté.'::text,'malgré'::text,'bien que'::text,'parce que'::text,'Il a hissé le drapeau malgré le vent fort, qui n''arrêtait pas de le tirer sur le côté.'::text),
(378530,42059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu sürekli yana çeken sert rüzgâra ... bayrağı göndere çekti.'::text,'rağmen'::text,'rağmen'::text,'yüzünden'::text,'Onu sürekli yana çeken sert rüzgâra rağmen bayrağı göndere çekti.'::text),
(378531,42059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felvonta a zászlót az erős szél ..., amely folyton oldalra húzta.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Felvonta a zászlót az erős szél ellenére, amely folyton oldalra húzta.'::text),
(378534,42060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alle wussten, dass der Mann mit dem weißen Schutzhelm nach dem Schild die Flagge ...'::text,'hissen würde'::text,'hissen wird'::text,'hisst'::text,'Alle wussten, dass der Mann mit dem weißen Schutzhelm nach dem Schild die Flagge hissen würde.'::text),
(378538,42060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі знали, що чоловік у білій касці ... прапор після таблички.'::text,'підніме'::text,'підніме'::text,'піднімає'::text,'Усі знали, що чоловік у білій касці підніме прапор після таблички.'::text),
(378537,42060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todos sabían que el hombre del casco blanco ... la bandera después del cartel.'::text,'izaría'::text,'izará'::text,'iza'::text,'Todos sabían que el hombre del casco blanco izaría la bandera después del cartel.'::text),
(378536,42060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le monde savait que l''homme au casque blanc ... le drapeau après la plaque.'::text,'hisserait'::text,'hissera'::text,'hisse'::text,'Tout le monde savait que l''homme au casque blanc hisserait le drapeau après la plaque.'::text),
(378539,42060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herkes beyaz baretli adamın tabeladan sonra bayrağı ... biliyordu.'::text,'çekeceğini'::text,'çekeceğini'::text,'çektiğini'::text,'Herkes beyaz baretli adamın tabeladan sonra bayrağı çekeceğini biliyordu.'::text),
(378540,42060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindenki tudta, hogy a fehér sisakos férfi a tábla után ... a zászlót.'::text,'fel fogja vonni'::text,'fel fogja vonni'::text,'felvonja'::text,'Mindenki tudta, hogy a fehér sisakos férfi a tábla után fel fogja vonni a zászlót.'::text),
(378543,42061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge ..., seit er die Flagge gehisst hat, eindeutig eine sehr ruhige Veranstaltung.'::text,'klatscht'::text,'klatscht'::text,'klatscht'::text,'Die Menge klatscht, seit er die Flagge gehisst hat, eindeutig eine sehr ruhige Veranstaltung.'::text),
(378547,42061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп ... відтоді, як він підняв прапор, явно дуже тиха подія.'::text,'аплодує'::text,'аплодує'::text,'аплодує'::text,'Натовп аплодує відтоді, як він підняв прапор, явно дуже тиха подія.'::text),
(378546,42061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La multitud ... desde que izó la bandera, claramente un evento muy tranquilo.'::text,'lleva aplaudiendo'::text,'está aplaudiendo'::text,'aplaude'::text,'La multitud lleva aplaudiendo desde que izó la bandera, claramente un evento muy tranquilo.'::text),
(378545,42061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule ... depuis qu''il a hissé le drapeau, clairement un événement très calme.'::text,'applaudit'::text,'applaudit'::text,'applaudit'::text,'La foule applaudit depuis qu''il a hissé le drapeau, clairement un événement très calme.'::text),
(378548,42061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bayrağı çektiğinden beri kalabalık ..., belli ki çok sakin bir etkinlik.'::text,'alkışlıyor'::text,'alkışlıyor'::text,'alkışlar'::text,'Bayrağı çektiğinden beri kalabalık alkışlıyor, belli ki çok sakin bir etkinlik.'::text),
(378549,42061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg azóta ..., hogy felvonta a zászlót, egyértelműen nagyon csendes esemény.'::text,'tapsol'::text,'tapsol'::text,'tapsol'::text,'A tömeg azóta tapsol, hogy felvonta a zászlót, egyértelműen nagyon csendes esemény.'::text),
(378561,42063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bis nächstes Jahr ... sie auf jedem neuen Gebäude eine Flagge gehisst haben, kein Witz.'::text,'werden'::text,'werden'::text,'werden'::text,'Yo, bis nächstes Jahr werden sie auf jedem neuen Gebäude eine Flagge gehisst haben, kein Witz.'::text),
(378565,42063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, до наступного року вони ... прапор на кожній новій будівлі, без жартів.'::text,'піднімуть'::text,'піднімуть'::text,'піднімають'::text,'Йо, до наступного року вони піднімуть прапор на кожній новій будівлі, без жартів.'::text),
(378564,42063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, para el año que viene ... una bandera en cada edificio nuevo, en serio.'::text,'habrán izado'::text,'izarán'::text,'izan'::text,'Ey, para el año que viene habrán izado una bandera en cada edificio nuevo, en serio.'::text),
(378563,42063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, d''ici l''année prochaine, ils ... un drapeau sur chaque nouveau bâtiment, sans mentir.'::text,'auront hissé'::text,'hisseront'::text,'hissent'::text,'Yo, d''ici l''année prochaine, ils auront hissé un drapeau sur chaque nouveau bâtiment, sans mentir.'::text),
(378566,42063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, seneye kadar her yeni binaya bir bayrak ..., cidden.'::text,'çekmiş olacaklar'::text,'çekecekler'::text,'çekiyorlar'::text,'Yo, seneye kadar her yeni binaya bir bayrak çekmiş olacaklar, cidden.'::text),
(378567,42063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyi, jövő évre minden új épületre ... egy zászlót, komolyan.'::text,'felvonnak'::text,'fel fognak vonni'::text,'felvonnak'::text,'Figyi, jövő évre minden új épületre felvonnak egy zászlót, komolyan.'::text),
(333498,37056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Band weiterspielt, ... die Menge um den Brunnen größer.'::text,'wird'::text,'würde'::text,'wurde'::text,'Wenn die Band weiterspielt, wird die Menge um den Brunnen größer.'::text),
(333502,37056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо гурт гратиме далі, натовп біля фонтану ... більшим.'::text,'стане'::text,'став би'::text,'став'::text,'Якщо гурт гратиме далі, натовп біля фонтану стане більшим.'::text),
(333501,37056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la banda sigue tocando, la multitud alrededor de la fuente ... más grande.'::text,'se hará'::text,'se haría'::text,'se hizo'::text,'Si la banda sigue tocando, la multitud alrededor de la fuente se hará más grande.'::text),
(333500,37056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le groupe continue de jouer, la foule autour de la fontaine ... plus grande.'::text,'deviendra'::text,'deviendrait'::text,'est devenue'::text,'Si le groupe continue de jouer, la foule autour de la fontaine deviendra plus grande.'::text),
(333503,37056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup çalmaya devam ederse, çeşmenin etrafındaki kalabalık ...'::text,'büyüyecek'::text,'büyürdü'::text,'büyüdü'::text,'Grup çalmaya devam ederse, çeşmenin etrafındaki kalabalık büyüyecek.'::text),
(333504,37056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a zenekar tovább játszik, a tömeg a szökőkút körül ...'::text,'nagyobb lesz'::text,'nagyobb lenne'::text,'nagyobb lett'::text,'Ha a zenekar tovább játszik, a tömeg a szökőkút körül nagyobb lesz.'::text),
(333507,37057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Band einen Schlagzeuger hätte, ... der Platz noch lauter.'::text,'klänge'::text,'wird klingen'::text,'klingt'::text,'Wenn die Band einen Schlagzeuger hätte, klänge der Platz noch lauter.'::text),
(333511,37057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в гурту був барабанщик, площа ... ще гучніше.'::text,'звучала б'::text,'звучатиме'::text,'звучить'::text,'Якби в гурту був барабанщик, площа звучала б ще гучніше.'::text),
(333510,37057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la banda tuviera batería, la plaza ... aún más fuerte.'::text,'sonaría'::text,'sonará'::text,'suena'::text,'Si la banda tuviera batería, la plaza sonaría aún más fuerte.'::text),
(333509,37057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le groupe avait un batteur, la place ... encore plus fort.'::text,'résonnerait'::text,'résonnera'::text,'résonne'::text,'Si le groupe avait un batteur, la place résonnerait encore plus fort.'::text),
(333512,37057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grubun bir davulcusu olsaydı, meydan daha da gürültülü ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Grubun bir davulcusu olsaydı, meydan daha da gürültülü olurdu.'::text),
(333513,37057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a zenekarnak lenne dobosa, a tér még hangosabban ...'::text,'szólna'::text,'fog szólni'::text,'szól'::text,'Ha a zenekarnak lenne dobosa, a tér még hangosabban szólna.'::text),
(333516,37058,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Band ... von einer etwas größeren Menge als erwartet beobachtet.'::text,'wurde'::text,'beobachtete'::text,'wird'::text,'Die Band wurde von einer etwas größeren Menge als erwartet beobachtet.'::text),
(333520,37058,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За гуртом ... трохи більший натовп, ніж очікувалося.'::text,'спостерігав'::text,'спостерігав'::text,'спостерігає'::text,'За гуртом спостерігав трохи більший натовп, ніж очікувалося.'::text),
(333519,37058,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La banda ... por una multitud un poco más grande de lo esperado.'::text,'fue vista'::text,'vio'::text,'es vista'::text,'La banda fue vista por una multitud un poco más grande de lo esperado.'::text),
(333518,37058,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe ... par une foule un peu plus grande que prévu.'::text,'a été regardé'::text,'a regardé'::text,'est regardé'::text,'Le groupe a été regardé par une foule un peu plus grande que prévu.'::text),
(333521,37058,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup, beklenenden biraz daha büyük bir kalabalık tarafından ...'::text,'izlendi'::text,'izledi'::text,'izleniyor'::text,'Grup, beklenenden biraz daha büyük bir kalabalık tarafından izlendi.'::text),
(333522,37058,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zenekart a vártnál kicsit nagyobb tömeg ...'::text,'nézte'::text,'nézte'::text,'nézi'::text,'A zenekart a vártnál kicsit nagyobb tömeg nézte.'::text),
(333525,37059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Band ... Gitarren und Tuba neben dem Steinbrunnen.'::text,'spielt'::text,'wird gespielt'::text,'spielend'::text,'Die Band spielt Gitarren und Tuba neben dem Steinbrunnen.'::text),
(333529,37059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гурт ... на гітарах і тубі біля кам''яного фонтану.'::text,'грає'::text,'грається'::text,'граючи'::text,'Гурт грає на гітарах і тубі біля кам''яного фонтану.'::text),
(333528,37059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La banda ... guitarras y una tuba junto a la fuente de piedra.'::text,'toca'::text,'es tocada'::text,'tocando'::text,'La banda toca guitarras y una tuba junto a la fuente de piedra.'::text),
(333527,37059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe ... de la guitare et du tuba à côté de la fontaine en pierre.'::text,'joue'::text,'est joué'::text,'jouant'::text,'Le groupe joue de la guitare et du tuba à côté de la fontaine en pierre.'::text),
(333530,37059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup taş çeşmenin yanında gitar ve tuba ...'::text,'çalıyor'::text,'çalınıyor'::text,'çalarak'::text,'Grup taş çeşmenin yanında gitar ve tuba çalıyor.'::text),
(333531,37059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zenekar gitáron és tubán ... a kőszökőkút mellett.'::text,'játszik'::text,'játszódik'::text,'játszva'::text,'A zenekar gitáron és tubán játszik a kőszökőkút mellett.'::text),
(333534,37060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Band ... hier berühmt sein, weil sich der ganze Platz zum Zuhören versammelt.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Die Band muss hier berühmt sein, weil sich der ganze Platz zum Zuhören versammelt.'::text),
(333538,37060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гурт ... бути тут відомим, бо вся площа збирається послухати.'::text,'мусить'::text,'не може'::text,'мав би'::text,'Гурт мусить бути тут відомим, бо вся площа збирається послухати.'::text),
(333537,37060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La banda ... ser famosa aquí, porque toda la plaza se reúne para escucharla.'::text,'debe de'::text,'no puede'::text,'debería'::text,'La banda debe de ser famosa aquí, porque toda la plaza se reúne para escucharla.'::text),
(333536,37060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe ... être célèbre ici, parce que toute la place se rassemble pour l''écouter.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Le groupe doit être célèbre ici, parce que toute la place se rassemble pour l''écouter.'::text),
(333539,37060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup burada ünlü ..., çünkü bütün meydan dinlemek için toplanıyor.'::text,'olmalı'::text,'olamaz'::text,'olması gerekir'::text,'Grup burada ünlü olmalı, çünkü bütün meydan dinlemek için toplanıyor.'::text),
(333540,37060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zenekar itt ... híres, mert az egész tér összegyűlik, hogy hallgassa.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'A zenekar itt biztosan híres, mert az egész tér összegyűlik, hogy hallgassa.'::text),
(333543,37061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Band, ... Musik den Platz erfüllt, spielt neben dem Brunnen.'::text,'deren'::text,'die'::text,'die'::text,'Die Band, deren Musik den Platz erfüllt, spielt neben dem Brunnen.'::text),
(333547,37061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гурт, ... музика наповнює площу, грає біля фонтану.'::text,'чия'::text,'який'::text,'хто'::text,'Гурт, чия музика наповнює площу, грає біля фонтану.'::text),
(333546,37061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La banda ... música llena la plaza toca junto a la fuente.'::text,'cuya'::text,'que'::text,'quien'::text,'La banda cuya música llena la plaza toca junto a la fuente.'::text),
(333545,37061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe ... la musique remplit la place joue à côté de la fontaine.'::text,'dont'::text,'qui'::text,'qui'::text,'Le groupe dont la musique remplit la place joue à côté de la fontaine.'::text),
(333548,37061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... müziği meydanı dolduran grup çeşmenin yanında çalıyor.'::text,''::text,NULL::text,NULL::text,'Müziği meydanı dolduran grup çeşmenin yanında çalıyor.'::text),
(333549,37061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zenekar, ... zenéje betölti a teret, a szökőkút mellett játszik.'::text,'amelynek a'::text,'amely'::text,'aki'::text,'A zenekar, amelynek a zenéje betölti a teret, a szökőkút mellett játszik.'::text),
(333552,37062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kellner deutete an, dass die Band am folgenden Abend erneut ...'::text,'spielen würde'::text,'spielen wird'::text,'spielt'::text,'Der Kellner deutete an, dass die Band am folgenden Abend erneut spielen würde.'::text),
(333556,37062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіціант зазначив, що гурт ... знову наступного вечора.'::text,'гратиме'::text,'гратиме'::text,'грає'::text,'Офіціант зазначив, що гурт гратиме знову наступного вечора.'::text),
(333555,37062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El camarero indicó que la banda ... de nuevo la noche siguiente.'::text,'tocaría'::text,'tocará'::text,'toca'::text,'El camarero indicó que la banda tocaría de nuevo la noche siguiente.'::text),
(333554,37062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le serveur a indiqué que le groupe ... de nouveau le lendemain soir.'::text,'jouerait'::text,'jouera'::text,'joue'::text,'Le serveur a indiqué que le groupe jouerait de nouveau le lendemain soir.'::text),
(333557,37062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Garson, grubun ertesi akşam yeniden ... belirtti.'::text,'çalacağını'::text,'çalacağını'::text,'çaldığını'::text,'Garson, grubun ertesi akşam yeniden çalacağını belirtti.'::text),
(333558,37062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pincér jelezte, hogy a zenekar másnap este újra ...'::text,'játszani fog'::text,'játszani fog'::text,'játszik'::text,'A pincér jelezte, hogy a zenekar másnap este újra játszani fog.'::text),
(333561,37063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Band ... früher völlig unbekannt, und jetzt schreit der ganze Platz nach ihr!'::text,'war'::text,'war'::text,'war'::text,'Diese Band war früher völlig unbekannt, und jetzt schreit der ganze Platz nach ihr!'::text),
(333565,37063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей гурт ... зовсім невідомим, а тепер уся площа кричить заради нього!'::text,'колись був'::text,'колись був'::text,'звик бути'::text,'Цей гурт колись був зовсім невідомим, а тепер уся площа кричить заради нього!'::text),
(333564,37063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta banda ... completamente desconocida, y ahora toda la plaza grita por ella!'::text,'solía ser'::text,'solía ser'::text,'estaba acostumbrada a ser'::text,'¡Esta banda solía ser completamente desconocida, y ahora toda la plaza grita por ella!'::text),
(333563,37063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce groupe ... complètement inconnu, et maintenant toute la place hurle pour lui !'::text,'était autrefois'::text,'était autrefois'::text,'avait l''habitude d''être'::text,'Ce groupe était autrefois complètement inconnu, et maintenant toute la place hurle pour lui !'::text),
(333566,37063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu grup eskiden tamamen ..., şimdi ise bütün meydan onlar için çığlık atıyor!'::text,'bilinmezdi'::text,'bilinmezdi'::text,'bilinmemeye alışkındı'::text,'Bu grup eskiden tamamen bilinmezdi, şimdi ise bütün meydan onlar için çığlık atıyor!'::text),
(333567,37063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a zenekar ... teljesen ismeretlen volt, most meg az egész tér értük sikolt!'::text,'régen'::text,'régen'::text,'megszokásból'::text,'Ez a zenekar régen teljesen ismeretlen volt, most meg az egész tér értük sikolt!'::text),
(333588,37066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... diese Band seit Jahren jedes Wochenende auf demselben Platz.'::text,'spielt'::text,'spielt'::text,'spielt'::text,'Mädel, angeblich spielt diese Band seit Jahren jedes Wochenende auf demselben Platz.'::text),
(333592,37066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, цей гурт уже багато років ... на тій самій площі щовихідних.'::text,'грає'::text,'грає'::text,'грає'::text,'Подруго, кажуть, цей гурт уже багато років грає на тій самій площі щовихідних.'::text),
(333591,37066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que esta banda ... en la misma plaza cada fin de semana desde hace años.'::text,'ha estado tocando'::text,'está tocando'::text,'toca'::text,'Tía, parece que esta banda ha estado tocando en la misma plaza cada fin de semana desde hace años.'::text),
(333590,37066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment ce groupe ... sur la même place chaque week-end depuis des années.'::text,'joue'::text,'joue'::text,'joue'::text,'Ma belle, apparemment ce groupe joue sur la même place chaque week-end depuis des années.'::text),
(333593,37066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya bu grup yıllardır her hafta sonu aynı meydanda ...'::text,'çalıyormuş'::text,'çalıyor'::text,'çalar'::text,'Kızım, güya bu grup yıllardır her hafta sonu aynı meydanda çalıyormuş.'::text),
(333594,37066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ez a zenekar évek óta minden hétvégén ugyanazon a téren ...'::text,'játszik'::text,'játszik'::text,'játszik'::text,'Csajszi, állítólag ez a zenekar évek óta minden hétvégén ugyanazon a téren játszik.'::text),
(386490,42944,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verspricht, er ... beim nächsten Spiel etwas weniger rum. Eindeutig ein Mann der großen Ruhe.'::text,'schreit'::text,'schreit'::text,'schreit'::text,'Er verspricht, er schreit beim nächsten Spiel etwas weniger rum. Eindeutig ein Mann der großen Ruhe.'::text),
(386494,42944,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обіцяє, що на наступному матчі ... трохи менше. Явно людина великого спокою.'::text,'кричатиме'::text,'кричатиме'::text,'кричить'::text,'Він обіцяє, що на наступному матчі кричатиме трохи менше. Явно людина великого спокою.'::text),
(386493,42944,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Promete que en el próximo partido ... un poco menos. Claramente, un hombre de gran calma.'::text,'gritará'::text,'estará gritando'::text,'está gritando'::text,'Promete que en el próximo partido gritará un poco menos. Claramente, un hombre de gran calma.'::text),
(386492,42944,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet qu''il ... un peu moins au prochain match. Clairement un homme d''un grand calme.'::text,'criera'::text,'sera en train de crier'::text,'crie'::text,'Il promet qu''il criera un peu moins au prochain match. Clairement un homme d''un grand calme.'::text),
(386495,42944,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sonraki maçta biraz daha az ... söz veriyor. Belli ki çok sakin bir adam.'::text,'bağıracağına'::text,'bağırıyor olacağına'::text,'bağırdığına'::text,'Bir sonraki maçta biraz daha az bağıracağına söz veriyor. Belli ki çok sakin bir adam.'::text),
(386496,42944,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígéri, hogy ... egy kicsit kevesebbet a következő meccsen. Egyértelműen a nyugalom embere.'::text,'fog kiabálni'::text,'fog kiabálni'::text,'kiabál'::text,'Megígéri, hogy fog kiabálni egy kicsit kevesebbet a következő meccsen. Egyértelműen a nyugalom embere.'::text),
(386499,42945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Team ein Tor schießt, ... die Fans in diesem Stadion immer und boxen in die Luft.'::text,'schreien'::text,'schreien'::text,'schrien'::text,'Wenn ein Team ein Tor schießt, schreien die Fans in diesem Stadion immer und boxen in die Luft.'::text),
(386503,42945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли команда забиває, фанати на цьому стадіоні завжди ... і б''ють кулаками в повітря.'::text,'кричать'::text,'кричатимуть'::text,'кричали'::text,'Коли команда забиває, фанати на цьому стадіоні завжди кричать і б''ють кулаками в повітря.'::text),
(386502,42945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un equipo marca, los aficionados de este estadio siempre ... y dan puñetazos al aire.'::text,'gritan'::text,'gritarán'::text,'gritaron'::text,'Si un equipo marca, los aficionados de este estadio siempre gritan y dan puñetazos al aire.'::text),
(386501,42945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand une équipe marque, les supporters de ce stade ... toujours et donnent des coups de poing en l''air.'::text,'crient'::text,'crieront'::text,'criaient'::text,'Quand une équipe marque, les supporters de ce stade crient toujours et donnent des coups de poing en l''air.'::text),
(386504,42945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir takım gol atınca, bu stadyumdaki taraftarlar her zaman ... ve havaya yumruk sallar.'::text,'bağırır'::text,'bağıracak'::text,'bağırdı'::text,'Bir takım gol atınca, bu stadyumdaki taraftarlar her zaman bağırır ve havaya yumruk sallar.'::text),
(386505,42945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy csapat gólt lő, a szurkolók ebben a stadionban mindig ... és a levegőbe öklöznek.'::text,'kiabálnak'::text,'kiabálni fognak'::text,'kiabáltak'::text,'Ha egy csapat gólt lő, a szurkolók ebben a stadionban mindig kiabálnak és a levegőbe öklöznek.'::text),
(386508,42946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach dem Spiel sagte der Mann mit dem Schal, er ... lauter geschrien als alle anderen.'::text,'habe'::text,'hat'::text,'hat'::text,'Nach dem Spiel sagte der Mann mit dem Schal, er habe lauter geschrien als alle anderen.'::text),
(386512,42946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після матчу чоловік із шарфом сказав, що ... голосніше за всіх.'::text,'кричав'::text,'кричав'::text,'кричить'::text,'Після матчу чоловік із шарфом сказав, що кричав голосніше за всіх.'::text),
(386511,42946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después del partido, el hombre de la bufanda dijo que ... más fuerte que nadie.'::text,'había gritado'::text,'ha gritado'::text,'grita'::text,'Después del partido, el hombre de la bufanda dijo que había gritado más fuerte que nadie.'::text),
(386510,42946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après le match, l''homme à l''écharpe a dit qu''il ... plus fort que tout le monde.'::text,'avait crié'::text,'a crié'::text,'crie'::text,'Après le match, l''homme à l''écharpe a dit qu''il avait crié plus fort que tout le monde.'::text),
(386513,42946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maçtan sonra atkılı adam herkesten daha yüksek sesle ... söyledi.'::text,'bağırdığını'::text,'bağırdığını'::text,'bağırdığını'::text,'Maçtan sonra atkılı adam herkesten daha yüksek sesle bağırdığını söyledi.'::text),
(386514,42946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A meccs után a sálas férfi azt mondta, hogy mindenkinél hangosabban ...'::text,'kiabált'::text,'kiabált'::text,'kiabál'::text,'A meccs után a sálas férfi azt mondta, hogy mindenkinél hangosabban kiabált.'::text),
(386517,42947,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... früher ein ruhiger Fan, aber heute Abend schreit er lauter als alle.'::text,'war'::text,'war'::text,'war'::text,'Der Mann war früher ein ruhiger Fan, aber heute Abend schreit er lauter als alle.'::text),
(386521,42947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей чоловік ... тихим уболівальником, але сьогодні ввечері кричить голосніше за всіх.'::text,'колись був'::text,'колись був'::text,'звик бути'::text,'Цей чоловік колись був тихим уболівальником, але сьогодні ввечері кричить голосніше за всіх.'::text),
(386520,42947,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... ser un aficionado tranquilo, pero esta noche grita más fuerte que nadie.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'El hombre solía ser un aficionado tranquilo, pero esta noche grita más fuerte que nadie.'::text),
(386519,42947,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... un supporter calme, mais ce soir il crie plus fort que tout le monde.'::text,'était autrefois'::text,'était autrefois'::text,'avait l''habitude d''être'::text,'L''homme était autrefois un supporter calme, mais ce soir il crie plus fort que tout le monde.'::text),
(386522,42947,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam eskiden sessiz bir taraftar ..., ama bu akşam herkesten yüksek sesle bağırıyor.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Adam eskiden sessiz bir taraftar olurdu, ama bu akşam herkesten yüksek sesle bağırıyor.'::text),
(386523,42947,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ... csendes szurkoló volt, de ma este mindenkinél hangosabban kiabál.'::text,'régen'::text,'régen'::text,'megszokásból'::text,'A férfi régen csendes szurkoló volt, de ma este mindenkinél hangosabban kiabál.'::text),
(386526,42948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kann nicht aufhören zu ..., selbst wenn seine Stimme völlig kaputt ist!'::text,'schreien'::text,'schreien'::text,'schreien'::text,'Er kann nicht aufhören zu schreien, selbst wenn seine Stimme völlig kaputt ist!'::text),
(386530,42948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не може перестати ..., навіть коли його голос повністю зірваний!'::text,'кричати'::text,'кричати'::text,'кричати'::text,'Він не може перестати кричати, навіть коли його голос повністю зірваний!'::text),
(386529,42948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No puede dejar de ..., incluso cuando tiene la voz completamente destrozada!'::text,'gritar'::text,'gritar'::text,'gritar'::text,'¡No puede dejar de gritar, incluso cuando tiene la voz completamente destrozada!'::text),
(386528,42948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''arrive pas à s''arrêter de ..., même quand sa voix est complètement cassée !'::text,'crier'::text,'crier'::text,'crier'::text,'Il n''arrive pas à s''arrêter de crier, même quand sa voix est complètement cassée !'::text),
(386531,42948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sesi tamamen mahvolsa bile ... duramıyor!'::text,'bağırmadan'::text,'bağırmadan'::text,'bağırmadan'::text,'Sesi tamamen mahvolsa bile bağırmadan duramıyor!'::text),
(386532,42948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tud leállni a ..., még akkor sem, amikor a hangja teljesen tönkrement!'::text,'kiabálással'::text,'kiabálással'::text,'kiabálással'::text,'Nem tud leállni a kiabálással, még akkor sem, amikor a hangja teljesen tönkrement!'::text),
(386535,42949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ganze Stadion hat geschrien, bis das Dach fast eingestürzt ist, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Das ganze Stadion hat geschrien, bis das Dach fast eingestürzt ist, nicht wahr?'::text),
(386539,42949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Увесь стадіон кричав, аж поки дах ледь не обвалився, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Увесь стадіон кричав, аж поки дах ледь не обвалився, правда?'::text),
(386538,42949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo el estadio gritó hasta que el techo casi se derrumbó, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Todo el estadio gritó hasta que el techo casi se derrumbó, ¿verdad?'::text),
(386537,42949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le stade a crié jusqu''à ce que le toit manque de s''effondrer, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Tout le stade a crié jusqu''à ce que le toit manque de s''effondrer, n''est-ce pas ?'::text),
(386540,42949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün stadyum çatı neredeyse çökene kadar bağırdı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Bütün stadyum çatı neredeyse çökene kadar bağırdı, değil mi?'::text),
(386541,42949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész stadion addig kiabált, amíg majdnem leszakadt a tető, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Az egész stadion addig kiabált, amíg majdnem leszakadt a tető, ugye?'::text),
(386544,42950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Der Mann schrie, bis seine Stimme weg war, und ...'::text,'die Fans auch'::text,'die Fans auch'::text,'die Fans auch'::text,'Katastrophe! Der Mann schrie, bis seine Stimme weg war, und die Fans auch.'::text),
(386548,42950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Чоловік кричав, поки не зірвав голос, і ...'::text,'фанати теж'::text,'фанати теж'::text,'фанати теж'::text,'Катастрофа! Чоловік кричав, поки не зірвав голос, і фанати теж.'::text),
(386547,42950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! El hombre gritó hasta quedarse sin voz, y ...'::text,'los aficionados también'::text,'los aficionados también'::text,'los aficionados también'::text,'¡Desastre! El hombre gritó hasta quedarse sin voz, y los aficionados también.'::text),
(386546,42950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! L''homme a crié jusqu''à perdre la voix, et ...'::text,'les supporters aussi'::text,'les supporters aussi'::text,'les supporters aussi'::text,'Catastrophe ! L''homme a crié jusqu''à perdre la voix, et les supporters aussi.'::text),
(386549,42950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Adam sesi gidene kadar bağırdı, ...'::text,'taraftarlar da öyle'::text,'taraftarlar da öyle'::text,'taraftarlar da öyle'::text,'Felaket! Adam sesi gidene kadar bağırdı, taraftarlar da öyle.'::text),
(386550,42950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A férfi addig kiabált, amíg el nem ment a hangja, és ...'::text,'a szurkolók is'::text,'a szurkolók is'::text,'a szurkolók is'::text,'Katasztrófa! A férfi addig kiabált, amíg el nem ment a hangja, és a szurkolók is.'::text),
(386553,42951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er hat mir gesagt, dass er bis zum Schlusspfiff jeden Fangesang zweimal ...'::text,'gebrüllt haben wird'::text,'brüllen wird'::text,'brüllen wird'::text,'Hör mal, er hat mir gesagt, dass er bis zum Schlusspfiff jeden Fangesang zweimal gebrüllt haben wird.'::text),
(386557,42951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що до фінального свистка ... кожну кричалку двічі.'::text,'прокричить'::text,'прокричить'::text,'кричатиме'::text,'Слухай, він сказав мені, що до фінального свистка прокричить кожну кричалку двічі.'::text),
(386556,42951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que para el pitido final ... cada cántico dos veces.'::text,'habrá gritado'::text,'gritará'::text,'estará gritando'::text,'Oye, me dijo que para el pitido final habrá gritado cada cántico dos veces.'::text),
(386555,42951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que d''ici le coup de sifflet final, il ... chaque chant deux fois.'::text,'aura crié'::text,'criera'::text,'sera en train de crier'::text,'Écoute, il m''a dit que d''ici le coup de sifflet final, il aura crié chaque chant deux fois.'::text),
(386558,42951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana son düdüğe kadar her tezahüratı iki kez ... söyledi.'::text,'bağırmış olacağını'::text,'bağıracağını'::text,'bağırıyor olacağını'::text,'Dinle, bana son düdüğe kadar her tezahüratı iki kez bağırmış olacağını söyledi.'::text),
(386559,42951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta nekem, hogy a lefújásig minden rigmust kétszer ...'::text,'elkiabál'::text,'el fog kiabálni'::text,'kiabálni fog'::text,'Figyelj, azt mondta nekem, hogy a lefújásig minden rigmust kétszer elkiabál.'::text),
(386562,42952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... der Mann mit dem Schal gerade aufs Spielfeld, weil sie getroffen haben.'::text,'brüllt'::text,'brüllt'::text,'hat gebrüllt'::text,'Bestie, angeblich brüllt der Mann mit dem Schal gerade aufs Spielfeld, weil sie getroffen haben.'::text),
(386566,42952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, чоловік із шарфом саме зараз ... на поле, бо вони забили.'::text,'кричить'::text,'кричить'::text,'кричав'::text,'Подруго, кажуть, чоловік із шарфом саме зараз кричить на поле, бо вони забили.'::text),
(386565,42952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que el hombre de la bufanda ... al campo ahora mismo porque han marcado.'::text,'está gritando'::text,'grita'::text,'ha gritado'::text,'Amiga, parece que el hombre de la bufanda está gritando al campo ahora mismo porque han marcado.'::text),
(386564,42952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment l''homme à l''écharpe ... vers le terrain en ce moment parce qu''ils ont marqué.'::text,'crie'::text,'crie'::text,'a crié'::text,'Ma belle, apparemment l''homme à l''écharpe crie vers le terrain en ce moment parce qu''ils ont marqué.'::text),
(386567,42952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya atkılı adam şu an sahaya ..., çünkü gol attılar.'::text,'bağırıyormuş'::text,'bağırırmış'::text,'bağırmış'::text,'Kanka, güya atkılı adam şu an sahaya bağırıyormuş, çünkü gol attılar.'::text),
(386568,42952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a sálas férfi épp most ... a pályára, mert gólt lőttek.'::text,'kiabál'::text,'kiabál'::text,'kiabált'::text,'Csajszi, állítólag a sálas férfi épp most kiabál a pályára, mert gólt lőttek.'::text),
(358536,39838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der alte Mann im Dorf bliebe, ... sich die Dorfbewohner nicht am Kai.'::text,'verabschiedeten'::text,'verabschieden'::text,'verabschieden'::text,'Wenn der alte Mann im Dorf bliebe, verabschiedeten sich die Dorfbewohner nicht am Kai.'::text),
(358540,39838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби старий залишився в селі, селяни ... з ним на набережній.'::text,'не прощалися б'::text,'не прощатимуться'::text,'не прощаються'::text,'Якби старий залишився в селі, селяни не прощалися б з ним на набережній.'::text),
(358539,39838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el anciano se quedara en el pueblo, los vecinos ... en el muelle.'::text,'no se despedirían'::text,'no se despedirán'::text,'no se despiden'::text,'Si el anciano se quedara en el pueblo, los vecinos no se despedirían en el muelle.'::text),
(358538,39838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vieil homme restait au village, les villageois ... sur le quai.'::text,'ne lui diraient pas au revoir'::text,'ne lui diront pas au revoir'::text,'ne lui disent pas au revoir'::text,'Si le vieil homme restait au village, les villageois ne lui diraient pas au revoir sur le quai.'::text),
(358541,39838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam köyde kalsaydı, köylüler rıhtımda onunla ...'::text,'vedalaşmazdı'::text,'vedalaşmayacak'::text,'vedalaşmıyor'::text,'Yaşlı adam köyde kalsaydı, köylüler rıhtımda onunla vedalaşmazdı.'::text),
(358542,39838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az öreg a faluban maradna, a falusiak ... tőle a rakparton.'::text,'nem búcsúznának el'::text,'nem fognak elbúcsúzni'::text,'nem búcsúznak el'::text,'Ha az öreg a faluban maradna, a falusiak nem búcsúznának el tőle a rakparton.'::text),
(358554,39840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Dorfbewohner ... dem alten Mann von der Hafenmauer aus zum Abschied.'::text,'winkten'::text,'wurden gewinkt'::text,'winkend'::text,'Die Dorfbewohner winkten dem alten Mann von der Hafenmauer aus zum Abschied.'::text),
(358558,39840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Селяни ... старому на прощання з портової стіни.'::text,'помахали'::text,'були помахані'::text,'махаючи'::text,'Селяни помахали старому на прощання з портової стіни.'::text),
(358557,39840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los vecinos le ... al anciano desde el muro del puerto.'::text,'dijeron adiós'::text,'fueron despedidos'::text,'diciendo adiós'::text,'Los vecinos le dijeron adiós al anciano desde el muro del puerto.'::text),
(358556,39840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les villageois ... le vieil homme depuis le mur du port pour lui dire au revoir.'::text,'ont salué'::text,'ont été salués'::text,'saluant'::text,'Les villageois ont salué le vieil homme depuis le mur du port pour lui dire au revoir.'::text),
(358559,39840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köylüler liman duvarından yaşlı adama veda için el ...'::text,'salladı'::text,'sallandı'::text,'sallayarak'::text,'Köylüler liman duvarından yaşlı adama veda için el salladı.'::text),
(358560,39840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A falusiak a kikötőfalról ... búcsút az öregnek.'::text,'intettek'::text,'intettek'::text,'intve'::text,'A falusiak a kikötőfalról intettek búcsút az öregnek.'::text),
(358563,39841,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das halbe Dorf winkt, also ... dieser Abschied eine große Sache sein. Total entspannt, klar.'::text,'muss'::text,'kann nicht'::text,'könnte nicht'::text,'Das halbe Dorf winkt, also muss dieser Abschied eine große Sache sein. Total entspannt, klar.'::text),
(358567,39841,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Половина села махає, тож це прощання ... бути чимось важливим. Абсолютно буденно, звісно.'::text,'мусить'::text,'не може'::text,'може й не'::text,'Половина села махає, тож це прощання мусить бути чимось важливим. Абсолютно буденно, звісно.'::text),
(358566,39841,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Medio pueblo está saludando, así que esta despedida ... ser algo importante. Totalmente casual, obviamente.'::text,'debe de'::text,'no puede'::text,'podría no'::text,'Medio pueblo está saludando, así que esta despedida debe de ser algo importante. Totalmente casual, obviamente.'::text),
(358565,39841,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La moitié du village fait coucou, donc cet adieu ... être un gros truc. Totalement banal, évidemment.'::text,'doit'::text,'ne peut pas'::text,'pourrait ne pas'::text,'La moitié du village fait coucou, donc cet adieu doit être un gros truc. Totalement banal, évidemment.'::text),
(358568,39841,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köyün yarısı el sallıyor, yani bu veda büyük bir olay ..., tamamen sıradan tabii ki.'::text,'olmalı'::text,'olamaz'::text,'olmayabilir'::text,'Köyün yarısı el sallıyor, yani bu veda büyük bir olay olmalı, tamamen sıradan tabii ki.'::text),
(358569,39841,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fél falu integet, szóval ez a búcsú ... nagy dolog. Teljesen hétköznapi, nyilván.'::text,'biztosan'::text,'biztosan nem'::text,'lehet, hogy nem'::text,'A fél falu integet, szóval ez a búcsú biztosan nagy dolog. Teljesen hétköznapi, nyilván.'::text),
(358572,39842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Boot, ... ihn aus dem Hafen bringt, macht es zu einem sehr schnellen Abschied, offensichtlich.'::text,'das'::text,'der'::text,'wo'::text,'Das Boot, das ihn aus dem Hafen bringt, macht es zu einem sehr schnellen Abschied, offensichtlich.'::text),
(358576,39842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Човен, ... везе його з гавані, робить це прощання дуже швидким, очевидно.'::text,'який'::text,'хто'::text,'де'::text,'Човен, який везе його з гавані, робить це прощання дуже швидким, очевидно.'::text),
(358575,39842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco ... lo saca del puerto hace que la despedida sea muy rápida, obviamente.'::text,'que'::text,'quien'::text,'donde'::text,'El barco que lo saca del puerto hace que la despedida sea muy rápida, obviamente.'::text),
(358574,39842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bateau ... l''emmène hors du port en fait un adieu très rapide, évidemment.'::text,'qui'::text,'qui'::text,'où'::text,'Le bateau qui l''emmène hors du port en fait un adieu très rapide, évidemment.'::text),
(358577,39842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... onu limandan dışarı taşıyan tekne bunu çok hızlı bir veda yapıyor, belli ki.'::text,''::text,NULL::text,NULL::text,'Onu limandan dışarı taşıyan tekne bunu çok hızlı bir veda yapıyor, belli ki.'::text),
(358578,39842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csónak, ... kiviszi a kikötőből, nagyon gyors búcsút csinál belőle, nyilván.'::text,'amely'::text,'aki'::text,'ahol'::text,'A csónak, amely kiviszi a kikötőből, nagyon gyors búcsút csinál belőle, nyilván.'::text),
(358581,39843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er meinte, er ... im nächsten Sommer zurück, also tat der Abschied schon irgendwie weh.'::text,'käme'::text,'kommt'::text,'kommt'::text,'Alter, er meinte, er käme im nächsten Sommer zurück, also tat der Abschied schon irgendwie weh.'::text),
(358585,39843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він сказав, що ... наступного літа, тож те прощання трохи боліло.'::text,'повернеться'::text,'повернеться'::text,'повертається'::text,'Чувак, він сказав, що повернеться наступного літа, тож те прощання трохи боліло.'::text),
(358584,39843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, dijo que ... el verano siguiente, así que esa despedida dolió un poco.'::text,'volvería'::text,'volverá'::text,'vuelve'::text,'Tío, dijo que volvería el verano siguiente, así que esa despedida dolió un poco.'::text),
(358583,39843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il a dit qu''il ... l''été suivant, donc cet adieu a un peu fait mal.'::text,'reviendrait'::text,'reviendra'::text,'revient'::text,'Mec, il a dit qu''il reviendrait l''été suivant, donc cet adieu a un peu fait mal.'::text),
(358586,39843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ertesi yaz ... söyledi, o yüzden o veda biraz acıttı.'::text,'döneceğini'::text,'döneceğini'::text,'döndüğünü'::text,'Kanka, ertesi yaz döneceğini söyledi, o yüzden o veda biraz acıttı.'::text),
(358587,39843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, azt mondta, hogy a következő nyáron ..., szóval az a búcsú elég fájt.'::text,'visszajön'::text,'vissza fog jönni'::text,'visszajön'::text,'Haver, azt mondta, hogy a következő nyáron visszajön, szóval az a búcsú elég fájt.'::text),
(358590,39844,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Sonntag ... die Dorfbewohner den Booten vom Kai aus zum Abschied zu winken.'::text,'pflegten'::text,'pflegten'::text,'waren gewohnt'::text,'Jeden Sonntag pflegten die Dorfbewohner den Booten vom Kai aus zum Abschied zu winken.'::text),
(358594,39844,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щонеділі селяни ... махати на прощання човнам із набережної.'::text,'мали звичку'::text,'мали звичку'::text,'звикли'::text,'Щонеділі селяни мали звичку махати на прощання човнам із набережної.'::text),
(358593,39844,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada domingo los vecinos ... despedir a los barcos desde el muelle.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'Cada domingo los vecinos solían despedir a los barcos desde el muelle.'::text),
(358592,39844,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque dimanche, les villageois ... dire au revoir de la main aux bateaux depuis le quai.'::text,'avaient l''habitude de'::text,'avaient l''habitude de'::text,'étaient habitués à'::text,'Chaque dimanche, les villageois avaient l''habitude de dire au revoir de la main aux bateaux depuis le quai.'::text),
(358595,39844,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her pazar köylüler rıhtımdan teknelere veda için el ...'::text,'sallardı'::text,'sallardı'::text,'sallamaya alışkındı'::text,'Her pazar köylüler rıhtımdan teknelere veda için el sallardı.'::text),
(358596,39844,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden vasárnap a falusiak régen ... a rakpartról búcsút inteni a hajóknak.'::text,'szoktak'::text,'szoktak'::text,'hozzá voltak szokva'::text,'Minden vasárnap a falusiak régen szoktak a rakpartról búcsút inteni a hajóknak.'::text),
(358599,39845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann wollte sich nicht zu lange ...'::text,'verabschieden'::text,'verabschieden'::text,'verabschieden'::text,'Der alte Mann wollte sich nicht zu lange verabschieden.'::text),
(358603,39845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий не хотів ... надто довго.'::text,'прощатися'::text,'прощатися'::text,'прощатися'::text,'Старий не хотів прощатися надто довго.'::text),
(358602,39845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anciano no quería ... durante demasiado tiempo.'::text,'despedirse'::text,'despedirse'::text,'despedirse'::text,'El anciano no quería despedirse durante demasiado tiempo.'::text),
(358601,39845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme ne voulait pas ... au revoir trop longtemps.'::text,'dire'::text,'dire'::text,'dire'::text,'Le vieil homme ne voulait pas dire au revoir trop longtemps.'::text),
(358604,39845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam çok uzun süre ... istemedi.'::text,'vedalaşmak'::text,'vedalaşmak'::text,'vedalaşmak'::text,'Yaşlı adam çok uzun süre vedalaşmak istemedi.'::text),
(358605,39845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az öreg nem akart túl sokáig ...'::text,'búcsúzkodni'::text,'búcsúzkodni'::text,'búcsúzkodni'::text,'Az öreg nem akart túl sokáig búcsúzkodni.'::text),
(358608,39846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand am Kai wird ... vergessen, den sie dem alten Mann an jenem Morgen bereitet haben.'::text,'den Abschied'::text,'einen Abschied'::text,'Abschied'::text,'Niemand am Kai wird den Abschied vergessen, den sie dem alten Mann an jenem Morgen bereitet haben.'::text),
(358612,39846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто на набережній не забуде ..., яке вони влаштували старому того ранку.'::text,'прощання'::text,'прощання'::text,'прощання'::text,'Ніхто на набережній не забуде прощання, яке вони влаштували старому того ранку.'::text),
(358611,39846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadie en el muelle olvidará ... que le dieron al anciano aquella mañana.'::text,'la despedida'::text,'una despedida'::text,'despedida'::text,'Nadie en el muelle olvidará la despedida que le dieron al anciano aquella mañana.'::text),
(358610,39846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne sur le quai n''oubliera ... qu''ils ont faits au vieil homme ce matin-là.'::text,'les adieux'::text,'des adieux'::text,'adieux'::text,'Personne sur le quai n''oubliera les adieux qu''ils ont faits au vieil homme ce matin-là.'::text),
(358613,39846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rıhtımdaki hiç kimse o sabah yaşlı adama yaptıkları ... unutmayacak.'::text,'vedayı'::text,'bir vedayı'::text,'vedayı'::text,'Rıhtımdaki hiç kimse o sabah yaşlı adama yaptıkları vedayı unutmayacak.'::text),
(358614,39846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakparton senki sem fogja elfelejteni ..., amelyet aznap reggel az öregnek rendeztek.'::text,'a búcsút'::text,'egy búcsút'::text,'búcsút'::text,'A rakparton senki sem fogja elfelejteni a búcsút, amelyet aznap reggel az öregnek rendeztek.'::text),
(358617,39847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... ihm das ganze Dorf gerade zum Abschied.'::text,'winkt'::text,'winkt'::text,'hat gewinkt'::text,'Mädel, angeblich winkt ihm das ganze Dorf gerade zum Abschied.'::text),
(358621,39847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, усе село саме зараз ... йому на прощання.'::text,'махає'::text,'махає'::text,'помахало'::text,'Подруго, кажуть, усе село саме зараз махає йому на прощання.'::text),
(358620,39847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que todo el pueblo le ... adiós ahora mismo.'::text,'está diciendo'::text,'dice'::text,'ha dicho'::text,'Tía, parece que todo el pueblo le está diciendo adiós ahora mismo.'::text),
(358619,39847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment tout le village lui ... au revoir en ce moment.'::text,'fait'::text,'fait'::text,'a fait'::text,'Ma belle, apparemment tout le village lui fait au revoir en ce moment.'::text),
(358622,39847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya bütün köy şu an ona veda için el ...'::text,'sallıyormuş'::text,'sallarmış'::text,'sallamış'::text,'Kızım, güya bütün köy şu an ona veda için el sallıyormuş.'::text),
(358623,39847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az egész falu épp most ... búcsút neki.'::text,'int'::text,'int'::text,'intett'::text,'Csajszi, állítólag az egész falu épp most int búcsút neki.'::text),
(351651,39073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie ihn ..., begann der Regenbogen zu verblassen.'::text,'ansah'::text,'ansah'::text,'angesehen hat'::text,'Während sie ihn ansah, begann der Regenbogen zu verblassen.'::text),
(351655,39073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... на веселку, та почала блякнути.'::text,'дивилася'::text,'подивилася'::text,'подивилася'::text,'Поки вона дивилася на веселку, та почала блякнути.'::text),
(351654,39073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ella ... el arcoíris, este empezó a desvanecerse.'::text,'estaba mirando'::text,'miró'::text,'ha mirado'::text,'Mientras ella estaba mirando el arcoíris, este empezó a desvanecerse.'::text),
(351653,39073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... l''arc-en-ciel, il a commencé à s''estomper.'::text,'regardait'::text,'a regardé'::text,'a regardé'::text,'Pendant qu''elle regardait l''arc-en-ciel, il a commencé à s''estomper.'::text),
(351656,39073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O gökkuşağına ..., gökkuşağı solmaya başladı.'::text,'bakarken'::text,'baktığında'::text,'bakmışken'::text,'O gökkuşağına bakarken, gökkuşağı solmaya başladı.'::text),
(351657,39073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a szivárványt, az halványulni kezdett.'::text,'nézte'::text,'megnézte'::text,'megnézte'::text,'Miközben ő nézte a szivárványt, az halványulni kezdett.'::text),
(351660,39074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Regenbogen ... schon so eine ganze Minute, ist irgendwie traurig.'::text,'verblasst'::text,'verblasst'::text,'verblasst'::text,'Digga, der Regenbogen verblasst schon so eine ganze Minute, ist irgendwie traurig.'::text),
(351664,39074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, та веселка ... вже десь хвилину, це якось сумно.'::text,'блякне'::text,'блякне'::text,'блякне'::text,'Бро, та веселка блякне вже десь хвилину, це якось сумно.'::text),
(351663,39074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese arcoíris ... como un minuto entero desvaneciéndose, es un poco triste.'::text,'lleva'::text,'está'::text,'está'::text,'Bro, ese arcoíris lleva como un minuto entero desvaneciéndose, es un poco triste.'::text),
(351662,39074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, cet arc-en-ciel ... depuis genre une minute, c''est un peu triste.'::text,'s''estompe'::text,'s''estompe'::text,'s''estompe'::text,'Frère, cet arc-en-ciel s''estompe depuis genre une minute, c''est un peu triste.'::text),
(351665,39074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o gökkuşağı resmen bir dakikadır ..., biraz hüzünlü.'::text,'soluyor'::text,'soluyor'::text,'solar'::text,'Kanka, o gökkuşağı resmen bir dakikadır soluyor, biraz hüzünlü.'::text),
(351666,39074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a szivárvány már vagy egy teljes perce ..., elég szomorú.'::text,'halványul'::text,'halványul'::text,'halványul'::text,'Tesó, az a szivárvány már vagy egy teljes perce halványul, elég szomorú.'::text),
(351669,39075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Regenbogen ..., als sie begann, ihren 2-minütigen Wetterbericht aufzunehmen.'::text,'verblasste schon'::text,'war schon verblasst'::text,'ist schon verblasst'::text,'Der Regenbogen verblasste schon, als sie begann, ihren 2-minütigen Wetterbericht aufzunehmen.'::text),
(351673,39075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Веселка ..., коли вона почала записувати свій 2-хвилинний прогноз погоди.'::text,'уже блякла'::text,'уже зблякла'::text,'уже зблякла'::text,'Веселка уже блякла, коли вона почала записувати свій 2-хвилинний прогноз погоди.'::text),
(351672,39075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El arcoíris ... cuando ella empezó a grabar su parte meteorológico de 2 minutos.'::text,'ya se estaba desvaneciendo'::text,'ya se desvaneció'::text,'ya se ha desvanecido'::text,'El arcoíris ya se estaba desvaneciendo cuando ella empezó a grabar su parte meteorológico de 2 minutos.'::text),
(351671,39075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arc-en-ciel ... quand elle a commencé à enregistrer son bulletin météo de 2 minutes.'::text,'s''estompait déjà'::text,'s''est déjà estompé'::text,'s''est déjà estompé'::text,'L''arc-en-ciel s''estompait déjà quand elle a commencé à enregistrer son bulletin météo de 2 minutes.'::text),
(351674,39075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2 dakikalık hava durumu raporunu kaydetmeye başladığında gökkuşağı ...'::text,'çoktan soluyordu'::text,'çoktan soldu'::text,'çoktan soldu'::text,'2 dakikalık hava durumu raporunu kaydetmeye başladığında gökkuşağı çoktan soluyordu.'::text),
(351675,39075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szivárvány ..., amikor elkezdte felvenni a 2 perces időjárás-jelentését.'::text,'már halványult'::text,'már elhalványult'::text,'már elhalványult'::text,'A szivárvány már halványult, amikor elkezdte felvenni a 2 perces időjárás-jelentését.'::text),
(351678,39076,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Regenbogen ist komplett ..., also hat der Himmel jetzt keinen Regenbogen.'::text,'verblasst'::text,'verblasst'::text,'verblasst'::text,'Der Regenbogen ist komplett verblasst, also hat der Himmel jetzt keinen Regenbogen.'::text),
(351682,39076,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Веселка ... повністю, тож тепер на небі немає веселки.'::text,'зблякла'::text,'блякла'::text,'блякне'::text,'Веселка зблякла повністю, тож тепер на небі немає веселки.'::text),
(351681,39076,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El arcoíris ... por completo, así que ahora el cielo no tiene arcoíris.'::text,'se ha desvanecido'::text,'se ha estado desvaneciendo'::text,'se desvanece'::text,'El arcoíris se ha desvanecido por completo, así que ahora el cielo no tiene arcoíris.'::text),
(351680,39076,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arc-en-ciel ... complètement, donc maintenant le ciel n''a plus d''arc-en-ciel.'::text,'s''est estompé'::text,'s''estompe'::text,'s''estompe'::text,'L''arc-en-ciel s''est estompé complètement, donc maintenant le ciel n''a plus d''arc-en-ciel.'::text),
(351683,39076,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökkuşağı tamamen ..., yani artık gökyüzünde gökkuşağı yok.'::text,'soldu'::text,'soluyor'::text,'solar'::text,'Gökkuşağı tamamen soldu, yani artık gökyüzünde gökkuşağı yok.'::text),
(351684,39076,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szivárvány teljesen ..., úgyhogy most nincs szivárvány az égen.'::text,'elhalványult'::text,'halványult'::text,'halványul'::text,'A szivárvány teljesen elhalványult, úgyhogy most nincs szivárvány az égen.'::text),
(351687,39077,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sich die Beobachterin umdrehte, ... die linke Seite bereits deutlich verblasst.'::text,'war'::text,'ist'::text,'ist'::text,'Als sich die Beobachterin umdrehte, war die linke Seite bereits deutlich verblasst.'::text),
(351691,39077,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли спостерігачка обернулася, ліва частина вже ... значною мірою.'::text,'зблякла'::text,'зблякла'::text,'блякне'::text,'Коли спостерігачка обернулася, ліва частина вже зблякла значною мірою.'::text),
(351690,39077,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando la observadora se dio la vuelta, el lado izquierdo ... considerablemente.'::text,'se había desvanecido'::text,'se ha desvanecido'::text,'se desvanece'::text,'Para cuando la observadora se dio la vuelta, el lado izquierdo se había desvanecido considerablemente.'::text),
(351689,39077,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''observatrice s''est retournée, le côté gauche ... considérablement.'::text,'s''était estompé'::text,'s''est estompé'::text,'s''estompe'::text,'Quand l''observatrice s''est retournée, le côté gauche s''était estompé considérablement.'::text),
(351692,39077,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemci arkasını döndüğünde sol taraf epey ...'::text,'solmuştu'::text,'soldu'::text,'soluyor'::text,'Gözlemci arkasını döndüğünde sol taraf epey solmuştu.'::text),
(351693,39077,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a megfigyelő megfordult, a bal oldal jelentősen ...'::text,'elhalványult'::text,'elhalványult'::text,'halványul'::text,'Mire a megfigyelő megfordult, a bal oldal jelentősen elhalványult.'::text),
(351705,39079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ich wette, deine gute Laune ..., wenn dieser Regenbogen verblasst.'::text,'verfliegt nicht'::text,'wird nicht verfliegen'::text,'verfliegt gerade nicht'::text,'Ehrlich, ich wette, deine gute Laune verfliegt nicht, wenn dieser Regenbogen verblasst.'::text),
(351709,39079,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, б''юся об заклад, твій гарний настрій ..., коли ця веселка зблякне.'::text,'не зникне'::text,'не зникатиме'::text,'не зникає'::text,'Чесно, б''юся об заклад, твій гарний настрій не зникне, коли ця веселка зблякне.'::text),
(351708,39079,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, apuesto a que tu buen humor ... cuando este arcoíris se desvanezca.'::text,'no se desvanecerá'::text,'no se estará desvaneciendo'::text,'no se está desvaneciendo'::text,'En serio, apuesto a que tu buen humor no se desvanecerá cuando este arcoíris se desvanezca.'::text),
(351707,39079,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, je parie que ta bonne humeur ... quand cet arc-en-ciel s''estompera.'::text,'ne s''estompera pas'::text,'ne sera pas en train de s''estomper'::text,'ne s''estompe pas'::text,'Franchement, je parie que ta bonne humeur ne s''estompera pas quand cet arc-en-ciel s''estompera.'::text),
(351710,39079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bahse girerim bu gökkuşağı solduğunda senin güzel ruh halin ...'::text,'solmayacak'::text,'soluyor olmayacak'::text,'solmuyor'::text,'Açıkçası, bahse girerim bu gökkuşağı solduğunda senin güzel ruh halin solmayacak.'::text),
(351711,39079,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, fogadok, hogy a jókedved ..., amikor ez a szivárvány elhalványul.'::text,'nem fog elmúlni'::text,'nem fog elmúlni'::text,'nem múlik el'::text,'Őszintén, fogadok, hogy a jókedved nem fog elmúlni, amikor ez a szivárvány elhalványul.'::text),
(351714,39080,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, du weißt es: Wenn die Sonne hinter einer Wolke ..., verblasst der Regenbogen.'::text,'verschwindet'::text,'verschwand'::text,'verschwinden wird'::text,'Mal ehrlich, du weißt es: Wenn die Sonne hinter einer Wolke verschwindet, verblasst der Regenbogen.'::text),
(351718,39080,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не збрешу, ти ж знаєш: коли сонце ... за хмару, веселка блякне.'::text,'заходить'::text,'зайшло'::text,'зайде'::text,'Не збрешу, ти ж знаєш: коли сонце заходить за хмару, веселка блякне.'::text),
(351717,39080,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ya lo sabes: si el sol ... detrás de una nube, el arcoíris se desvanece.'::text,'se esconde'::text,'se escondió'::text,'se esconderá'::text,'No te voy a mentir, ya lo sabes: si el sol se esconde detrás de una nube, el arcoíris se desvanece.'::text),
(351716,39080,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu le sais : si le soleil ... derrière un nuage, l''arc-en-ciel s''estompe.'::text,'passe'::text,'est passé'::text,'passera'::text,'Je vais pas mentir, tu le sais : si le soleil passe derrière un nuage, l''arc-en-ciel s''estompe.'::text),
(351719,39080,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, biliyorsun: güneş bir bulutun arkasına ..., gökkuşağı solar.'::text,'girerse'::text,'girdiyse'::text,'girecekse'::text,'Yalan yok, biliyorsun: güneş bir bulutun arkasına girerse, gökkuşağı solar.'::text),
(351720,39080,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te is tudod: ha a nap ... egy felhő mögé, a szivárvány elhalványul.'::text,'bemegy'::text,'bement'::text,'be fog menni'::text,'Nem hazudok, te is tudod: ha a nap bemegy egy felhő mögé, a szivárvány elhalványul.'::text),
(351723,39081,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie wegschaut, ... der Regenbogen endgültig. Tolles Timing, klar.'::text,'verblasst'::text,'verblasste'::text,'verblasste'::text,'Wenn sie wegschaut, verblasst der Regenbogen endgültig. Tolles Timing, klar.'::text),
(351727,39081,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона відвернеться, веселка ... назавжди. Чудовий таймінг, звісно.'::text,'зблякне'::text,'зблякла б'::text,'зблякла'::text,'Якщо вона відвернеться, веселка зблякне назавжди. Чудовий таймінг, звісно.'::text),
(351726,39081,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si aparta la vista, el arcoíris ... para siempre. Qué oportuno, obviamente.'::text,'se desvanecerá'::text,'se desvanecería'::text,'se desvaneció'::text,'Si aparta la vista, el arcoíris se desvanecerá para siempre. Qué oportuno, obviamente.'::text),
(351725,39081,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle détourne le regard, l''arc-en-ciel ... pour de bon. Super timing, évidemment.'::text,'s''estompera'::text,'s''estomperait'::text,'s''est estompé'::text,'Si elle détourne le regard, l''arc-en-ciel s''estompera pour de bon. Super timing, évidemment.'::text),
(351728,39081,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başını çevirirse gökkuşağı tamamen ..., harika zamanlama tabii ki.'::text,'solacak'::text,'solardı'::text,'soldu'::text,'Başını çevirirse gökkuşağı tamamen solacak, harika zamanlama tabii ki.'::text),
(351729,39081,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elfordítja a fejét, a szivárvány ... végleg. Remek időzítés, nyilván.'::text,'elhalványul'::text,'elhalványulna'::text,'elhalványult'::text,'Ha elfordítja a fejét, a szivárvány elhalványul végleg. Remek időzítés, nyilván.'::text),
(351732,39082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Regenbogen nicht so schnell verblassen würde, ... sie ein längeres Video.'::text,'drehte'::text,'wird'::text,'dreht'::text,'Wenn der Regenbogen nicht so schnell verblassen würde, drehte sie ein längeres Video.'::text),
(351736,39082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби веселка не блякла так швидко, вона ... довше відео.'::text,'зняла б'::text,'зніме'::text,'знімає'::text,'Якби веселка не блякла так швидко, вона зняла б довше відео.'::text),
(351735,39082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el arcoíris no se desvaneciera tan rápido, ella ... un vídeo más largo.'::text,'grabaría'::text,'grabará'::text,'graba'::text,'Si el arcoíris no se desvaneciera tan rápido, ella grabaría un vídeo más largo.'::text),
(351734,39082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''arc-en-ciel ne s''estompait pas aussi vite, elle ... une vidéo plus longue.'::text,'filmerait'::text,'filmera'::text,'filme'::text,'Si l''arc-en-ciel ne s''estompait pas aussi vite, elle filmerait une vidéo plus longue.'::text),
(351737,39082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökkuşağı bu kadar hızlı solmasaydı, daha uzun bir video ...'::text,'çekerdi'::text,'çekecek'::text,'çekiyor'::text,'Gökkuşağı bu kadar hızlı solmasaydı, daha uzun bir video çekerdi.'::text),
(351738,39082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szivárvány nem halványulna el ilyen gyorsan, ő hosszabb videót ...'::text,'forgatna'::text,'fog forgatni'::text,'forgat'::text,'Ha a szivárvány nem halványulna el ilyen gyorsan, ő hosszabb videót forgatna.'::text),
(351741,39083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Regenbogen ... ein paar Sekunden lang, bevor der Himmel grau wurde.'::text,'verblasste'::text,'verblasst'::text,'verblasst'::text,'Der Regenbogen verblasste ein paar Sekunden lang, bevor der Himmel grau wurde.'::text),
(351745,39083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Веселка ... кілька секунд, перш ніж небо посіріло.'::text,'блякла'::text,'блякне'::text,'блякне'::text,'Веселка блякла кілька секунд, перш ніж небо посіріло.'::text),
(351744,39083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El arcoíris ... unos segundos desvaneciéndose antes de que el cielo se volviera gris.'::text,'llevaba'::text,'lleva'::text,'está'::text,'El arcoíris llevaba unos segundos desvaneciéndose antes de que el cielo se volviera gris.'::text),
(351743,39083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arc-en-ciel ... depuis quelques secondes quand le ciel est devenu gris.'::text,'s''estompait'::text,'s''estompe'::text,'s''estompe'::text,'L''arc-en-ciel s''estompait depuis quelques secondes quand le ciel est devenu gris.'::text),
(351746,39083,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökyüzü griye dönmeden önce gökkuşağı birkaç saniyedir ...'::text,'soluyordu'::text,'soluyor'::text,'soluyor'::text,'Gökyüzü griye dönmeden önce gökkuşağı birkaç saniyedir soluyordu.'::text),
(351747,39083,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szivárvány már néhány másodperce ..., mielőtt az ég elszürkült.'::text,'halványult'::text,'halványul'::text,'halványul'::text,'A szivárvány már néhány másodperce halványult, mielőtt az ég elszürkült.'::text),
(377418,41936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um 9 Uhr ... die Einheit Schlagübungen, um ihr Trainingsziel zu erreichen.'::text,'macht'::text,'macht'::text,'macht'::text,'Morgen um 9 Uhr macht die Einheit Schlagübungen, um ihr Trainingsziel zu erreichen.'::text),
(377422,41936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о 9:00 підрозділ ... вправи з ударів кулаком, щоб досягти тренувальної цілі.'::text,'виконуватиме'::text,'виконає'::text,'виконує'::text,'Завтра о 9:00 підрозділ виконуватиме вправи з ударів кулаком, щоб досягти тренувальної цілі.'::text),
(377421,41936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las 9:00, la unidad ... ejercicios de puñetazo para cumplir su objetivo de entrenamiento.'::text,'estará haciendo'::text,'hará'::text,'hace'::text,'Mañana a las 9:00, la unidad estará haciendo ejercicios de puñetazo para cumplir su objetivo de entrenamiento.'::text),
(377420,41936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à 9 h, l''unité ... des exercices de coups de poing pour atteindre son objectif d''entraînement.'::text,'sera en train de faire'::text,'fera'::text,'fait'::text,'Demain à 9 h, l''unité sera en train de faire des exercices de coups de poing pour atteindre son objectif d''entraînement.'::text),
(377423,41936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın sabah 9''da birlik, eğitim hedefine ulaşmak için yumruk tatbikatı ...'::text,'yapıyor olacak'::text,'yapacak'::text,'yapıyor'::text,'Yarın sabah 9''da birlik, eğitim hedefine ulaşmak için yumruk tatbikatı yapıyor olacak.'::text),
(377424,41936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap reggel 9-kor az egység ütésgyakorlatokat ..., hogy elérje az edzéscélját.'::text,'fog végezni'::text,'fog végezni'::text,'végez'::text,'Holnap reggel 9-kor az egység ütésgyakorlatokat fog végezni, hogy elérje az edzéscélját.'::text),
(377436,41938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Faustschlag ein gepolstertes Schild ..., verteilt sich die Kraft typischerweise über die Oberfläche.'::text,'trifft'::text,'traf'::text,'treffen wird'::text,'Wenn ein Faustschlag ein gepolstertes Schild trifft, verteilt sich die Kraft typischerweise über die Oberfläche.'::text),
(377440,41938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли удар кулаком ... м''який щит, сила зазвичай розподіляється по поверхні.'::text,'влучає в'::text,'влучив у'::text,'влучить у'::text,'Коли удар кулаком влучає в м''який щит, сила зазвичай розподіляється по поверхні.'::text),
(377439,41938,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un puñetazo ... un escudo acolchado, la fuerza suele repartirse por la superficie.'::text,'golpea'::text,'golpeó'::text,'golpeará'::text,'Si un puñetazo golpea un escudo acolchado, la fuerza suele repartirse por la superficie.'::text),
(377438,41938,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un coup de poing ... un bouclier rembourré, la force se répartit généralement sur la surface.'::text,'frappe'::text,'a frappé'::text,'frappera'::text,'Si un coup de poing frappe un bouclier rembourré, la force se répartit généralement sur la surface.'::text),
(377441,41938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yumruk dolgulu bir kalkana ..., kuvvet genellikle yüzeye yayılır.'::text,'çarparsa'::text,'çarptıysa'::text,'çarpacaksa'::text,'Bir yumruk dolgulu bir kalkana çarparsa, kuvvet genellikle yüzeye yayılır.'::text),
(377442,41938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy ütés ... egy párnázott pajzsot, az erő jellemzően szétterjed a felületen.'::text,'eltalál'::text,'eltalált'::text,'el fog találni'::text,'Ha egy ütés eltalál egy párnázott pajzsot, az erő jellemzően szétterjed a felületen.'::text),
(377445,41939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wow! Der letzte Schlag hat das Schild fast zerstört, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Wow! Der letzte Schlag hat das Schild fast zerstört, nicht wahr?'::text),
(377449,41939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ого! Той останній удар мало не знищив щит, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Ого! Той останній удар мало не знищив щит, правда?'::text),
(377448,41939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Guau! Ese último puñetazo casi destroza el escudo, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'¡Guau! Ese último puñetazo casi destroza el escudo, ¿verdad?'::text),
(377447,41939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Waouh ! Ce dernier coup de poing a failli détruire le bouclier, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Waouh ! Ce dernier coup de poing a failli détruire le bouclier, n''est-ce pas ?'::text),
(377450,41939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vay! O son yumruk kalkanı neredeyse parçaladı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Vay! O son yumruk kalkanı neredeyse parçaladı, değil mi?'::text),
(377451,41939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hűha! Az utolsó ütés majdnem szétverte a pajzsot, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Hűha! Az utolsó ütés majdnem szétverte a pajzsot, ugye?'::text),
(377454,41940,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaos! Sie hat mit einem Schlag fast das Schild zerstört, und ...'::text,'ihr Partner auch'::text,'ihr Partner auch'::text,'ihr Partner auch nicht'::text,'Chaos! Sie hat mit einem Schlag fast das Schild zerstört, und ihr Partner auch.'::text),
(377458,41940,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хаос! Вона одним ударом мало не знищила щит, і ...'::text,'її партнер теж'::text,'її партнер теж'::text,'її партнер теж ні'::text,'Хаос! Вона одним ударом мало не знищила щит, і її партнер теж.'::text),
(377457,41940,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Caos! Casi destroza el escudo de un puñetazo, y ...'::text,'su compañero también'::text,'su compañero también'::text,'su compañero tampoco'::text,'¡Caos! Casi destroza el escudo de un puñetazo, y su compañero también.'::text),
(377456,41940,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaos ! Elle a failli détruire le bouclier d''un seul coup de poing, et ...'::text,'son partenaire aussi'::text,'son partenaire aussi'::text,'son partenaire non plus'::text,'Chaos ! Elle a failli détruire le bouclier d''un seul coup de poing, et son partenaire aussi.'::text),
(377459,41940,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaos! Tek yumrukla kalkanı neredeyse parçaladı, ...'::text,'partneri de öyle'::text,'partneri de öyle'::text,'partneri de öyle değil'::text,'Kaos! Tek yumrukla kalkanı neredeyse parçaladı, partneri de öyle.'::text),
(377460,41940,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Káosz! Egyetlen ütéssel majdnem szétverte a pajzsot, és ...'::text,'a partnere is'::text,'a partnere is'::text,'a partnere sem'::text,'Káosz! Egyetlen ütéssel majdnem szétverte a pajzsot, és a partnere is.'::text),
(377463,41941,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie seinen Griff geblockt, ... dieser Schlag den ganzen Kampf gewonnen! Katastrophe!'::text,'hätte'::text,'wird'::text,'hat'::text,'Hätte sie seinen Griff geblockt, hätte dieser Schlag den ganzen Kampf gewonnen! Katastrophe!'::text),
(377467,41941,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона заблокувала його захват, той удар ... весь бій! Катастрофа!'::text,'виграв би'::text,'виграє'::text,'виграв'::text,'Якби вона заблокувала його захват, той удар виграв би весь бій! Катастрофа!'::text),
(377466,41941,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si hubiera bloqueado su agarre, ese puñetazo ... todo el combate! ¡Desastre!'::text,'habría ganado'::text,'ganará'::text,'ganó'::text,'¡Si hubiera bloqueado su agarre, ese puñetazo habría ganado todo el combate! ¡Desastre!'::text),
(377465,41941,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait bloqué sa prise, ce coup de poing ... tout le combat ! Catastrophe !'::text,'aurait gagné'::text,'gagnera'::text,'a gagné'::text,'Si elle avait bloqué sa prise, ce coup de poing aurait gagné tout le combat ! Catastrophe !'::text),
(377468,41941,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun tutuşunu bloklasaydı, o yumruk bütün dövüşü ...! Felaket!'::text,'kazandırırdı'::text,'kazandıracak'::text,'kazandırdı'::text,'Onun tutuşunu bloklasaydı, o yumruk bütün dövüşü kazandırırdı! Felaket!'::text),
(377469,41941,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kivédte volna a fogását, az az ütés ... az egész küzdelmet! Katasztrófa!'::text,'megnyerte volna'::text,'meg fogja nyerni'::text,'megnyerte'::text,'Ha kivédte volna a fogását, az az ütés megnyerte volna az egész küzdelmet! Katasztrófa!'::text),
(377481,41943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hätte das Schild höher halten ..., denn ihr Schlag traf fast sein Kinn.'::text,'sollen'::text,'müssen'::text,'können'::text,'Er hätte das Schild höher halten sollen, denn ihr Schlag traf fast sein Kinn.'::text),
(377485,41943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... тримати щит вище, бо її удар мало не влучив йому в підборіддя.'::text,'мав'::text,'мусив'::text,'міг'::text,'Він мав тримати щит вище, бо її удар мало не влучив йому в підборіддя.'::text),
(377484,41943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... sostenido el escudo más alto, porque su puñetazo casi le da en la barbilla.'::text,'debería haber'::text,'debe de haber'::text,'podría haber'::text,'Él debería haber sostenido el escudo más alto, porque su puñetazo casi le da en la barbilla.'::text),
(377483,41943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... tenir le bouclier plus haut, parce que son coup de poing a failli le toucher au menton.'::text,'aurait dû'::text,'a dû'::text,'pouvait'::text,'Il aurait dû tenir le bouclier plus haut, parce que son coup de poing a failli le toucher au menton.'::text),
(377486,41943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalkanı daha yüksekte ..., çünkü kadının yumruğu neredeyse çenesine geliyordu.'::text,'tutmalıydı'::text,'tutmuş olmalı'::text,'tutabilirdi'::text,'Kalkanı daha yüksekte tutmalıydı, çünkü kadının yumruğu neredeyse çenesine geliyordu.'::text),
(377487,41943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Magasabban ... tartania a pajzsot, mert a nő ütése majdnem eltalálta az állát.'::text,'kellett volna'::text,'kellett'::text,'lehetett volna'::text,'Magasabban kellett volna tartania a pajzsot, mert a nő ütése majdnem eltalálta az állát.'::text),
(377490,41944,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Trainer ließ die Soldaten ihre Schläge paarweise auf den Matten ...'::text,'üben'::text,'üben'::text,'üben'::text,'Der Trainer ließ die Soldaten ihre Schläge paarweise auf den Matten üben.'::text),
(377494,41944,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренер змусив солдатів ... удари в парах на матах.'::text,'відпрацьовувати'::text,'відпрацьовувати'::text,'відпрацьовувати'::text,'Тренер змусив солдатів відпрацьовувати удари в парах на матах.'::text),
(377493,41944,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El entrenador puso a los soldados a ... sus golpes por parejas en las colchonetas.'::text,'practicar'::text,'practicar'::text,'practicar'::text,'El entrenador puso a los soldados a practicar sus golpes por parejas en las colchonetas.'::text),
(377492,41944,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''entraîneur a fait ... leurs coups de poing aux soldats, par paires, sur les tapis.'::text,'travailler'::text,'travailler'::text,'travailler'::text,'L''entraîneur a fait travailler leurs coups de poing aux soldats, par paires, sur les tapis.'::text),
(377495,41944,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenör askerlere minderlerde ikişerli yumruk ...'::text,'çalıştırdı'::text,'çalıştırdı'::text,'çalıştırdı'::text,'Antrenör askerlere minderlerde ikişerli yumruk çalıştırdı.'::text),
(377496,41944,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző párokban ... a katonákkal az ütéseket a szőnyegeken.'::text,'gyakoroltatta'::text,'gyakoroltatta'::text,'gyakoroltatta'::text,'Az edző párokban gyakoroltatta a katonákkal az ütéseket a szőnyegeken.'::text),
(377499,41945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er wünschte, er ... ihren Schlag kommen sehen, der hat ihn echt zerlegt.'::text,'hätte'::text,'sah'::text,'würde'::text,'Digga, er wünschte, er hätte ihren Schlag kommen sehen, der hat ihn echt zerlegt.'::text),
(377503,41945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, шкода, що він не ... її удар, той його прям розніс.'::text,'побачив'::text,'бачив'::text,'побачить'::text,'Бро, шкода, що він не побачив її удар, той його прям розніс.'::text),
(377502,41945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ojalá él ... venir su puñetazo, lo dejó hecho polvo.'::text,'hubiera visto'::text,'viera'::text,'vería'::text,'Bro, ojalá él hubiera visto venir su puñetazo, lo dejó hecho polvo.'::text),
(377501,41945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il aimerait ... son coup de poing arriver, ça l''a un peu détruit.'::text,'avoir vu'::text,'voir'::text,'voir'::text,'Frère, il aimerait avoir vu son coup de poing arriver, ça l''a un peu détruit.'::text),
(377504,41945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke kadının yumruğunun geldiğini ... diyor, baya dağıttı onu.'::text,'görseydim'::text,'görsem'::text,'göreceğim'::text,'Kanka, keşke kadının yumruğunun geldiğini görseydim diyor, baya dağıttı onu.'::text),
(377505,41945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, bárcsak ... jönni az ütését, eléggé szétszedte.'::text,'látta volna'::text,'látná'::text,'látná'::text,'Tesó, bárcsak látta volna jönni az ütését, eléggé szétszedte.'::text),
(377508,41946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schlag, ... das Schild so hart getroffen hat, war irgendwie der beste des Tages, Digga.'::text,'der'::text,'der'::text,'der'::text,'Der Schlag, der das Schild so hart getroffen hat, war irgendwie der beste des Tages, Digga.'::text),
(377512,41946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той удар, ... так сильно влучив у щит, був, чесно, найкращим за день, бро.'::text,'який'::text,'що'::text,'хто'::text,'Той удар, який так сильно влучив у щит, був, чесно, найкращим за день, бро.'::text),
(377511,41946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese puñetazo, ... dio tan fuerte en el escudo, fue en plan el mejor del día, bro.'::text,'que'::text,'que'::text,'quien'::text,'Ese puñetazo, que dio tan fuerte en el escudo, fue en plan el mejor del día, bro.'::text),
(377510,41946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce coup de poing, ... a frappé le bouclier si fort, était genre le meilleur de la journée, frère.'::text,'qui'::text,'qui'::text,'qui'::text,'Ce coup de poing, qui a frappé le bouclier si fort, était genre le meilleur de la journée, frère.'::text),
(377513,41946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalkana ... öyle sert vuran o yumruk, resmen günün en iyisiydi kanka.'::text,''::text,NULL::text,NULL::text,'Kalkana öyle sert vuran o yumruk, resmen günün en iyisiydi kanka.'::text),
(377514,41946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az az ütés, ... olyan keményen eltalálta a pajzsot, lazán a nap legjobbja volt, tesó.'::text,'amely'::text,'ami'::text,'aki'::text,'Az az ütés, amely olyan keményen eltalálta a pajzsot, lazán a nap legjobbja volt, tesó.'::text),
(331338,36816,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rekruten in der Armee wird typischerweise ..., einen Partner auf die Matten zu werfen.'::text,'beigebracht'::text,'beibringen'::text,'beibringend'::text,'Rekruten in der Armee wird typischerweise beigebracht, einen Partner auf die Matten zu werfen.'::text),
(331342,36816,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Новобранців в армії зазвичай ... кидати партнера на мати.'::text,'навчають'::text,'навчати'::text,'навчаючи'::text,'Новобранців в армії зазвичай навчають кидати партнера на мати.'::text),
(331341,36816,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A los reclutas del ejército normalmente se les ... a lanzar a un compañero sobre las colchonetas.'::text,'enseña'::text,'enseñar'::text,'enseñando'::text,'A los reclutas del ejército normalmente se les enseña a lanzar a un compañero sobre las colchonetas.'::text),
(331340,36816,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les recrues de l''armée sont généralement ... à projeter un partenaire sur les tapis.'::text,'formées'::text,'former'::text,'formant'::text,'Les recrues de l''armée sont généralement formées à projeter un partenaire sur les tapis.'::text),
(331343,36816,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Orduda acemi askerlere genellikle bir partneri minderlere fırlatmak ...'::text,'öğretilir'::text,'öğretmek'::text,'öğreterek'::text,'Orduda acemi askerlere genellikle bir partneri minderlere fırlatmak öğretilir.'::text),
(331344,36816,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hadseregben az újoncoknak jellemzően ..., hogyan dobják a társukat a szőnyegre.'::text,'megtanítják'::text,'tanítani'::text,'tanítva'::text,'A hadseregben az újoncoknak jellemzően megtanítják, hogyan dobják a társukat a szőnyegre.'::text),
(331347,36817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Armee ... sie zur Kämpferin gemacht, und es gibt absolut kein Zurück!'::text,'hat'::text,'wurde'::text,'machend'::text,'Die Armee hat sie zur Kämpferin gemacht, und es gibt absolut kein Zurück!'::text),
(331351,36817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Армія ... її на бійчиню, і шляху назад абсолютно немає!'::text,'перетворила'::text,'була перетворена'::text,'перетворюючи'::text,'Армія перетворила її на бійчиню, і шляху назад абсолютно немає!'::text),
(331350,36817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El ejército la ... en una luchadora, y no hay absolutamente vuelta atrás!'::text,'ha convertido'::text,'ha sido convertida'::text,'convirtiendo'::text,'¡El ejército la ha convertido en una luchadora, y no hay absolutamente vuelta atrás!'::text),
(331349,36817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''armée ... en combattante, et il n''y a absolument aucun retour en arrière possible !'::text,'l''a transformée'::text,'a été transformée'::text,'la transformant'::text,'L''armée l''a transformée en combattante, et il n''y a absolument aucun retour en arrière possible !'::text),
(331352,36817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ordu onu bir savaşçıya ... ve kesinlikle geri dönüş yok!'::text,'dönüştürdü'::text,'dönüştürüldü'::text,'dönüştürerek'::text,'Ordu onu bir savaşçıya dönüştürdü ve kesinlikle geri dönüş yok!'::text),
(331353,36817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hadsereg harcost ... belőle, és egyáltalán nincs visszaút!'::text,'csinált'::text,'csináltak'::text,'csinálva'::text,'A hadsereg harcost csinált belőle, és egyáltalán nincs visszaút!'::text),
(331365,36819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Armee, ... Soldaten sich gegenseitig auf die Matten werfen, ist absolut gnadenlos!'::text,'deren'::text,'die'::text,'die'::text,'Die Armee, deren Soldaten sich gegenseitig auf die Matten werfen, ist absolut gnadenlos!'::text),
(331369,36819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Армія, ... солдати кидають одне одного на мати, абсолютно безжальна!'::text,'чиї'::text,'яка'::text,'хто'::text,'Армія, чиї солдати кидають одне одного на мати, абсолютно безжальна!'::text),
(331368,36819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El ejército ... soldados se lanzan unos a otros sobre las colchonetas es absolutamente despiadado!'::text,'cuyos'::text,'que'::text,'quien'::text,'¡El ejército cuyos soldados se lanzan unos a otros sobre las colchonetas es absolutamente despiadado!'::text),
(331367,36819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''armée ... les soldats se projettent les uns les autres sur les tapis est absolument impitoyable !'::text,'dont'::text,'qui'::text,'qui'::text,'L''armée dont les soldats se projettent les uns les autres sur les tapis est absolument impitoyable !'::text),
(331370,36819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... askerleri birbirini minderlere fırlatan ordu kesinlikle acımasız!'::text,''::text,NULL::text,NULL::text,'Askerleri birbirini minderlere fırlatan ordu kesinlikle acımasız!'::text),
(331371,36819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hadsereg, ... katonái egymást dobálják a szőnyegre, abszolút könyörtelen!'::text,'amelynek a'::text,'amely'::text,'aki'::text,'A hadsereg, amelynek a katonái egymást dobálják a szőnyegre, abszolút könyörtelen!'::text),
(331374,36820,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir erzählt, die Armee ... sie nächstes Jahr zur Feldwebelin.'::text,'mache'::text,'macht'::text,'macht'::text,'Bestie, sie hat mir erzählt, die Armee mache sie nächstes Jahr zur Feldwebelin.'::text),
(331378,36820,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що армія ... її сержанткою наступного року.'::text,'зробить'::text,'зробить'::text,'робить'::text,'Подруго, вона сказала мені, що армія зробить її сержанткою наступного року.'::text),
(331377,36820,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que el ejército la ... sargento el año que viene.'::text,'haría'::text,'hará'::text,'hace'::text,'Amiga, me dijo que el ejército la haría sargento el año que viene.'::text),
(331376,36820,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit que l''armée la ... sergente l''année prochaine.'::text,'nommerait'::text,'nommera'::text,'nomme'::text,'Ma belle, elle m''a dit que l''armée la nommerait sergente l''année prochaine.'::text),
(331379,36820,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana ordunun onu seneye çavuş ... söyledi.'::text,'yapacağını'::text,'yapacağını'::text,'yaptığını'::text,'Kanka, bana ordunun onu seneye çavuş yapacağını söyledi.'::text),
(331380,36820,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a hadsereg jövőre őrmesterré ...'::text,'fogja tenni'::text,'fogja tenni'::text,'teszi'::text,'Csajszi, azt mondta, hogy a hadsereg jövőre őrmesterré fogja tenni.'::text),
(331383,36821,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor der Armee ... sie früher Angst vor dem Nahkampf.'::text,'hatte'::text,'hatte'::text,'hatte'::text,'Vor der Armee hatte sie früher Angst vor dem Nahkampf.'::text),
(331387,36821,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До армії вона ... ближнього бою.'::text,'колись боялася'::text,'колись боялася'::text,'звикла боятися'::text,'До армії вона колись боялася ближнього бою.'::text),
(331386,36821,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del ejército, ... tenerle miedo al combate cuerpo a cuerpo.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Antes del ejército, solía tenerle miedo al combate cuerpo a cuerpo.'::text),
(331385,36821,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant l''armée, elle ... peur du combat rapproché.'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Avant l''armée, elle avait peur du combat rapproché.'::text),
(331388,36821,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ordudan önce yakın dövüşten ...'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkındı'::text,'Ordudan önce yakın dövüşten korkardı.'::text),
(331389,36821,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hadsereg előtt ... a közelharctól.'::text,'félt'::text,'félt'::text,'hozzá volt szokva, hogy féljen'::text,'A hadsereg előtt félt a közelharctól.'::text),
(331392,36822,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der Armee übt sie stundenlang das ... auf das Schild.'::text,'Schlagen'::text,'Schlagen'::text,'Schlagen'::text,'In der Armee übt sie stundenlang das Schlagen auf das Schild.'::text),
(331396,36822,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'В армії вона годинами відпрацьовує ... по щиту.'::text,'удари'::text,'удари'::text,'удари'::text,'В армії вона годинами відпрацьовує удари по щиту.'::text),
(331395,36822,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En el ejército, se pasa horas ... el escudo.'::text,'golpeando'::text,'golpeando'::text,'golpeando'::text,'En el ejército, se pasa horas golpeando el escudo.'::text),
(331394,36822,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À l''armée, elle s''entraîne à ... le bouclier pendant des heures.'::text,'frapper'::text,'frapper'::text,'frapper'::text,'À l''armée, elle s''entraîne à frapper le bouclier pendant des heures.'::text),
(331397,36822,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Orduda saatlerce kalkana ... çalışıyor.'::text,'yumruk atmaya'::text,'yumruk atmaya'::text,'yumruk atmaya'::text,'Orduda saatlerce kalkana yumruk atmaya çalışıyor.'::text),
(331398,36822,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hadseregben órákig gyakorolja a pajzs ...'::text,'ütését'::text,'ütését'::text,'ütését'::text,'A hadseregben órákig gyakorolja a pajzs ütését.'::text),
(331401,36823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Training in der Armee ist harte Arbeit, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Das Training in der Armee ist harte Arbeit, nicht wahr?'::text),
(331405,36823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Армійські тренування — це важка праця, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Армійські тренування — це важка праця, правда?'::text),
(331404,36823,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El entrenamiento en el ejército es un trabajo duro, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'El entrenamiento en el ejército es un trabajo duro, ¿verdad?'::text),
(331403,36823,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''entraînement à l''armée, c''est du boulot, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'L''entraînement à l''armée, c''est du boulot, n''est-ce pas ?'::text),
(331406,36823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ordu eğitimi zor iş, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Ordu eğitimi zor iş, değil mi?'::text),
(331407,36823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A katonai kiképzés kemény munka, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A katonai kiképzés kemény munka, ugye?'::text),
(331410,36824,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie schmeißt die Armee nicht hin, und ihr Partner ..., echt.'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Digga, sie schmeißt die Armee nicht hin, und ihr Partner auch nicht, echt.'::text),
(331414,36824,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона не збирається кидати армію, і її напарник ..., реально.'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Бро, вона не збирається кидати армію, і її напарник теж ні, реально.'::text),
(331413,36824,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella no va a dejar el ejército, y su compañero ..., en serio.'::text,'tampoco'::text,'también'::text,'tampoco'::text,'Bro, ella no va a dejar el ejército, y su compañero tampoco, en serio.'::text),
(331412,36824,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle va pas quitter l''armée, et son partenaire ..., grave.'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Frère, elle va pas quitter l''armée, et son partenaire non plus, grave.'::text),
(331415,36824,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o ordudan ayrılmayacak, partneri de ..., cidden.'::text,'ayrılmayacak'::text,'ayrılacak'::text,'ayrılmıyor'::text,'Kanka, o ordudan ayrılmayacak, partneri de ayrılmayacak, cidden.'::text),
(331416,36824,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő nem fog kilépni a hadseregből, és a társa ..., komolyan.'::text,'sem'::text,'is'::text,'sem'::text,'Tesó, ő nem fog kilépni a hadseregből, és a társa sem, komolyan.'::text),
(331419,36825,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Armee ... 6 Stunden lang geübt, bevor der Trainingsbericht fertig war.'::text,'hatte'::text,'hat'::text,'war'::text,'Die Armee hatte 6 Stunden lang geübt, bevor der Trainingsbericht fertig war.'::text),
(331423,36825,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Армія ... 6 годин, перш ніж звіт про навчання було завершено.'::text,'тренувалася'::text,'тренується'::text,'тренувалася'::text,'Армія тренувалася 6 годин, перш ніж звіт про навчання було завершено.'::text),
(331422,36825,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ejército ... 6 horas haciendo maniobras antes de que se terminara el informe de entrenamiento.'::text,'llevaba'::text,'lleva'::text,'estaba'::text,'El ejército llevaba 6 horas haciendo maniobras antes de que se terminara el informe de entrenamiento.'::text),
(331421,36825,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''armée ... depuis 6 heures quand le rapport d''entraînement a été terminé.'::text,'s''entraînait'::text,'s''entraîne'::text,'s''entraînait'::text,'L''armée s''entraînait depuis 6 heures quand le rapport d''entraînement a été terminé.'::text),
(331424,36825,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitim raporu bitmeden önce ordu 6 saattir ...'::text,'talim yapıyordu'::text,'talim yapıyor'::text,'talim yapıyordu'::text,'Eğitim raporu bitmeden önce ordu 6 saattir talim yapıyordu.'::text),
(331425,36825,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hadsereg 6 órán át ..., mielőtt elkészült a kiképzési jelentés.'::text,'gyakorlatozott'::text,'gyakorlatozik'::text,'gyakorlatozott'::text,'A hadsereg 6 órán át gyakorlatozott, mielőtt elkészült a kiképzési jelentés.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
